(function () {
  'use strict';
  CF.content.extendPack('srd-5.2', { spells: [{"id":"acid-arrow","name":"Acid Arrow","level":2,"school":"Evocation","classes":["wizard"],"time":"Action","range":"90 ft","components":"V, S, M (powdered rhubarb leaf)","duration":"Instantaneous","concentration":false,"text":"A shimmering green arrow streaks toward a target within range and bursts in a spray of acid. Make a ranged spell attack against the target. On a hit, the target takes 4d4 Acid damage and 2d4 Acid damage at the end of its next turn. On a miss, the arrow splashes the target with acid for half as much of the initial damage only.\nUsing a Higher-Level Spell Slot. The damage (both initial and later) increases by 1d4 for each spell slot level above 2.","attack":"ranged","effect":{"dice":"4d4","type":"acid"},"higher":"The damage (both initial and later) increases by 1d4 for each spell slot level above 2.","upcast":{"dice":"1d4"},"componentsShort":"V, S, M"},{"id":"acid-splash","name":"Acid Splash","level":0,"school":"Evocation","classes":["sorcerer","wizard"],"time":"Action","range":"60 ft","components":"V, S","duration":"Instantaneous","concentration":false,"text":"You create an acidic bubble at a point within range, where it explodes in a 5-ft-radius Sphere. Each creature in that Sphere must succeed on a Dexterity saving throw or take 1d6 Acid damage.\nCantrip Upgrade. The damage increases by 1d6 when you reach levels 5 (2d6), 11 (3d6), and 17 (4d6).","save":"dex","effect":{"dice":"1d6","type":"acid"},"componentsShort":"V, S"},{"id":"aid","name":"Aid","level":2,"school":"Abjuration","classes":["bard","cleric","druid","paladin","ranger"],"time":"Action","range":"30 ft","components":"V, S, M (a strip of white cloth)","duration":"8 hours","concentration":false,"text":"Choose up to three creatures within range. Each target’s Hit Point maximum and current Hit Points increase by 5 for the duration.\nUsing a Higher-Level Spell Slot. Each target’s Hit Points increase by 5 for each spell slot level above 2.","higher":"Each target’s Hit Points increase by 5 for each spell slot level above 2.","componentsShort":"V, S, M","effect":{"text":"+5 current and max HP, up to 3 creatures"}},{"id":"alarm","name":"Alarm","level":1,"school":"Abjuration","classes":["ranger","wizard"],"time":"1 minute","range":"30 ft","components":"V, S, M (a bell and silver wire)","duration":"8 hours","concentration":false,"text":"You set an alarm against intrusion. Choose a door, a window, or an area within range that is no larger than a 20-ft Cube. Until the spell ends, an alarm alerts you whenever a creature touches or enters the warded area. When you cast the spell, you can designate creatures that won’t set off the alarm. You also choose whether the alarm is audible or mental:\nAudible Alarm. The alarm produces the sound of a handbell for 10 seconds within 60 ft of the warded area.\nMental Alarm. You are alerted by a mental ping if you are within 1 mile of the warded area. This ping awakens you if you’re asleep.","ritual":true,"componentsShort":"V, S, M","effect":{"text":"Set an alarm against intrusion"}},{"id":"alter-self","name":"Alter Self","level":2,"school":"Transmutation","classes":["sorcerer","wizard"],"time":"Action","range":"Self","components":"V, S","duration":"Up to 1 hour","concentration":true,"text":"You alter your physical form. Choose one of the following options. Its effects last for the duration, during which you can take a Magic action to replace the option you chose with a different one.\nAquatic Adaptation. You sprout gills and grow webs between your fingers. You can breathe underwater and gain a Swim Speed equal to your Speed.\nChange Appearance. You alter your appearance. You decide what you look like, including your height, weight, facial features, sound of your voice, hair length, coloration, and other distinguishing characteristics. You can make yourself appear as a member of another species, though none of your statistics change. You can’t appear as a creature of a different size, and your basic shape stays the same; if you’re bipedal, you can’t use this spell to become quadrupedal, for instance. For the duration, you can take a Magic action to change your appearance in this way again.\nNatural Weapons. You grow claws (Slashing), fangs (Piercing), horns (Piercing), or hooves (Bludgeoning). When you use your Unarmed Strike to deal damage with that new growth, it deals 1d6 damage of the type in parentheses instead of dealing the normal damage for your Unarmed Strike, and you use your spellcasting ability modifier for the attack and damage rolls rather than using Strength.","concDuration":"1 hour","componentsShort":"V, S","effect":{"text":"Aquatic, change appearance or natural weapons"}},{"id":"animal-friendship","name":"Animal Friendship","level":1,"school":"Enchantment","classes":["bard","druid","ranger"],"time":"Action","range":"30 ft","components":"V, S, M (a morsel of food)","duration":"24 hours","concentration":false,"text":"Target a Beast that you can see within range. The target must succeed on a Wisdom saving throw or have the Charmed condition for the duration. If you or one of your allies deals damage to the target, the spells ends.\nUsing a Higher-Level Spell Slot. You can target one additional Beast for each spell slot level above 1.","save":"wis","higher":"You can target one additional Beast for each spell slot level above 1.","componentsShort":"V, S, M","effect":{"text":"Target a Beast that you can see within range"}},{"id":"animal-messenger","name":"Animal Messenger","level":2,"school":"Enchantment","classes":["bard","druid","ranger"],"time":"Action","range":"30 ft","components":"V, S, M (a morsel of food)","duration":"24 hours","concentration":false,"text":"A Tiny Beast of your choice that you can see within range must succeed on a Charisma saving throw, or it attempts to deliver a message for you (if the target’s Challenge Rating isn’t 0, it automatically succeeds). You specify a location you have visited and a recipient who matches a general description, such as “a person dressed in the uniform of the town guard” or “a red-haired dwarf wearing a pointed hat.” You also communicate a message of up to twenty-five words. The Beast travels for the duration toward the specified location, covering about 25 miles per 24 hours or 50 miles if the Beast can fly.\nWhen the Beast arrives, it delivers your message to the creature that you described, mimicking your communication. If the Beast doesn’t reach its destination before the spell ends, the message is lost, and the Beast returns to where you cast the spell.\nUsing a Higher-Level Spell Slot. The spell’s duration increases by 48 hours for each spell slot level above 2.","ritual":true,"save":"cha","higher":"The spell’s duration increases by 48 hours for each spell slot level above 2.","componentsShort":"V, S, M","effect":{"text":"A Tiny Beast of your choice that you can see within range…"}},{"id":"animal-shapes","name":"Animal Shapes","level":8,"school":"Transmutation","classes":["druid"],"time":"Action","range":"30 ft","components":"V, S","duration":"24 hours","concentration":false,"text":"Choose any number of willing creatures that you can see within range. Each target shape-shifts into a Large or smaller Beast of your choice that has a Challenge Rating of 4 or lower. You can choose a different form for each target. On later turns, you can take a Magic action to transform the targets again.\nA target’s game statistics are replaced by the chosen Beast’s statistics, but the target retains its creature type; Hit Points; Hit Point Dice; alignment; ability to communicate; and Intelligence, Wisdom, and Charisma scores. The target’s actions are limited by the Beast form’s anatomy, and it can’t cast spells. The target’s equipment melds into the new form, and the target can’t use any of that equipment while in that form.\nThe target gains a number of Temporary Hit Points equal to the Hit Points of the first form into which it shape-shifts. These Temporary Hit Points vanish if any remain when the spell ends. The transformation lasts for the duration or until the target ends it as a Bonus Action.","componentsShort":"V, S","effect":{"text":"Choose any number of willing creatures that you can see…"}},{"id":"animate-dead","name":"Animate Dead","level":3,"school":"Necromancy","classes":["cleric","wizard"],"time":"1 minute","range":"10 ft","components":"V, S, M (a drop of blood, a piece of flesh, and a pinch of bone dust)","duration":"Instantaneous","concentration":false,"text":"Choose a pile of bones or a corpse of a Medium or Small Humanoid within range. The target becomes an Undead creature: a Skeleton if you chose bones or a Zombie if you chose a corpse (see “Monsters”\nfor the stat blocks).\nOn each of your turns, you can take a Bonus Action to mentally command any creature you made with this spell if the creature is within 60 ft of you (if you control multiple creatures, you can command any of them at the same time, issuing the same command to each one). You decide what action the creature will take and where it will move on its next turn, or you can issue a general command, such as to guard a chamber or corridor. If you issue no commands, the creature takes the Dodge action and moves only to avoid harm. Once given an order, the creature continues to follow it until its task is complete.\nThe creature is under your control for 24 hours, after which it stops obeying any command you’ve given it. To maintain control of the creature for another 24 hours, you must cast this spell on the creature again before the current 24-hour period ends. This use of the spell reasserts your control over up to four creatures you have animated with this spell rather than animating a new creature.\nUsing a Higher-Level Spell Slot. You animate or reassert control over two additional Undead creatures for each spell slot level above 3. Each of the creatures must come from a different corpse or pile of bones.","higher":"You animate or reassert control over two additional Undead creatures for each spell slot level above 3. Each of the creatures must come from a different corpse or pile of bones.","componentsShort":"V, S, M","effect":{"text":"Choose a pile of bones or a corpse of a Medium or Small…"}},{"id":"animate-objects","name":"Animate Objects","level":5,"school":"Transmutation","classes":["bard","sorcerer","wizard"],"time":"Action","range":"120 ft","components":"V, S","duration":"Up to 1 minute","concentration":true,"text":"Objects animate at your command. Choose a number of nonmagical objects within range that aren’t being worn or carried, aren’t fixed to a surface, and aren’t Gargantuan. The maximum number of objects is equal to your spellcasting ability modifier; for this number, a Medium or smaller target counts as one object, a Large target counts as two, and a Huge target counts as three.\nEach target animates, sprouts legs, and becomes a Construct that uses the Animated Object stat block; this creature is under your control until the spell ends or until it is reduced to 0 Hit Points. Each creature you make with this spell is an ally to you and your allies. In combat, it shares your Initiative count and takes its turn immediately after yours.\nUntil the spell ends, you can take a Bonus Action to mentally command any creature you made with this spell if the creature is within 500 ft of you (if you control multiple creatures, you can command any of them at the same time, issuing the same command to each one). If you issue no commands, the creature takes the Dodge action and moves only to avoid harm. When the creature drops to 0 Hit Points, it reverts to its object form, and any remaining damage carries over to that form.\nUsing a Higher-Level Spell Slot. The creature’s Slam damage increases by 1d4 (Medium or smaller), 1d6 (Large), or 1d12 (Huge) for each spell slot level above 5.\nAnimated Object\nHuge or Smaller Construct, Unaligned AC 15 HP 10 (Medium or smaller), 20 (Large), 40 (Huge) Speed 30 ft.\nMOD SAVE\nMOD SAVE\nMOD SAVE\nStr 16 +3 +3 Int 3 −4 −4\nDex 10 +0 +0 Wis 3 −4 −4\nCon 10 +0 +0 Cha 1 −5 −5\nImmunities Poison, Psychic; Charmed, Exhaustion, Frightened, Paralyzed, Poisoned Senses Blindsight 30 ft.; Passive Perception 6 Languages Understands the languages you know CR None (XP 0; PB equals your Proficiency Bonus)\nActions Slam. Melee Attack Roll: Bonus equals your spell attack modifier, reach 5 ft. Hit: Force damage equal to 1d4 + 3 (Medium or smaller), 2d6 + 3 + your spellcasting ability modifier (Large), or 2d12 + 3 + your spellcasting ability modifier (Huge).","concDuration":"1 min","higher":"The creature’s Slam damage increases by 1d4 (Medium or smaller), 1d6 (Large), or 1d12 (Huge) for each spell slot level above 5.","componentsShort":"V, S","effect":{"text":"Objects animate at your command"}},{"id":"antilife-shell","name":"Antilife Shell","level":5,"school":"Abjuration","classes":["druid"],"time":"Action","range":"Self","components":"V, S","duration":"Up to 1 hour","concentration":true,"text":"An aura extends from you in a 10-ft Emanation for the duration. The aura prevents creatures other than Constructs and Undead from passing or reaching through it. An affected creature can cast spells or make attacks with Ranged or Reach weapons through the barrier.\nIf you move so that an affected creature is forced to pass through the barrier, the spell ends.","concDuration":"1 hour","componentsShort":"V, S","effect":{"text":"An aura extends from you in a 10-ft Emanation for the duration"}},{"id":"antimagic-field","name":"Antimagic Field","level":8,"school":"Abjuration","classes":["cleric","wizard"],"time":"Action","range":"Self","components":"V, S, M (iron filings)","duration":"Up to 1 hour","concentration":true,"text":"An aura of antimagic surrounds you in 10-ft Emanation. No one can cast spells, take Magic actions, or create other magical effects inside the aura, and those things can’t target or otherwise affect anything inside it. Magical properties of magic items don’t work inside the aura or on anything inside it.\nAreas of effect created by spells or other magic can’t extend into the aura, and no one can teleport into or out of it or use planar travel there. Portals close temporarily while in the aura.\nOngoing spells, except those cast by an Artifact or a deity, are suppressed in the area. While an effect is suppressed, it doesn’t function, but the time it spends suppressed counts against its duration.\nDispel Magic has no effect on the aura, and the auras created by different Antimagic Field spells don’t nullify each other.","concDuration":"1 hour","componentsShort":"V, S, M","effect":{"text":"An aura of antimagic surrounds you in 10-ft Emanation"}},{"id":"antipathy-sympathy","name":"Antipathy/Sympathy","level":8,"school":"Enchantment","classes":["bard","druid","wizard"],"time":"1 hour","range":"60 ft","components":"V, S, M (a mix of vinegar and honey)","duration":"10 days","concentration":false,"text":"As you cast the spell, choose whether it creates antipathy or sympathy, and target one creature or object that is Huge or smaller. Then specify a kind of creature, such as red dragons, goblins, or vampires.\nA creature of the chosen kind makes a Wisdom saving throw when it comes within 120 ft of the target. Your choice of antipathy or sympathy determines what happens to a creature when it fails that save:\nAntipathy. The creature has the Frightened condition. The Frightened creature must use its movement on its turns to get as far away as possible from the target, moving by the safest route.\nSympathy. The creature has the Charmed condition. The Charmed creature must use its movement on its turns to get as close as possible to the target, moving by the safest route. If the creature is within 5 ft of the target, the creature can’t willingly move away. If the target damages the Charmed creature, that creature can make a\nWisdom saving throw to end the effect, as described below.\nEnding the Effect. If the Frightened or Charmed creature ends its turn more than 120 ft away from the target, the creature makes a Wisdom saving throw. On a successful save, the creature is no longer affected by the target. A creature that successfully saves against this effect is immune to it for 1 minute, after which it can be affected again.","save":"wis","componentsShort":"V, S, M","effect":{"text":"As you cast the spell, choose whether it creates antipathy or…"}},{"id":"arcane-eye","name":"Arcane Eye","level":4,"school":"Divination","classes":["wizard"],"time":"Action","range":"30 ft","components":"V, S, M (a bit of bat fur)","duration":"Up to 1 hour","concentration":true,"text":"You create an Invisible, invulnerable eye within range that hovers for the duration. You mentally receive visual information from the eye, which can see in every direction. It also has Darkvision with a range of 30 ft.\nAs a Bonus Action, you can move the eye up to 30 ft in any direction. A solid barrier blocks the eye’s movement, but the eye can pass through an opening as small as 1 inch in diameter.","concDuration":"1 hour","componentsShort":"V, S, M","effect":{"text":"Invisible floating scout eye"}},{"id":"arcane-hand","name":"Arcane Hand","level":5,"school":"Evocation","classes":["sorcerer","wizard"],"time":"Action","range":"120 ft","components":"V, S, M (an eggshell and a glove)","duration":"Up to 1 minute","concentration":true,"text":"You create a Large hand of shimmering magical energy in an unoccupied space that you can see within range. The hand lasts for the duration, and it moves at your command, mimicking the movements of your own hand.\nThe hand is an object that has AC 20 and Hit Points equal to your Hit Point maximum. If it drops to 0 Hit Points, the spell ends. The hand doesn’t occupy its space.\nWhen you cast the spell and as a Bonus Action on your later turns, you can move the hand up to 60 ft and then cause one of the following effects:\nClenched Fist. The hand strikes a target within 5 ft of it. Make a melee spell attack. On a hit, the target takes 5d8 Force damage.\nForceful Hand. The hand attempts to push a Huge or smaller creature within 5 ft of it. The target must succeed on a Strength saving throw, or the hand pushes the target up to 5 ft plus a number of feet equal to five times your spellcasting ability modifier. The hand moves with the target, remaining within 5 ft of it.\nGrasping Hand. The hand attempts to grapple a Huge or smaller creature within 5 ft of it. The target must succeed on a Dexterity saving throw, or the target has the Grappled condition, with an escape DC equal to your spell save DC. While the hand grapples the target, you can take a Bonus Action to cause the hand to crush it, dealing Bludgeoning damage to the target equal to 4d6 plus your spellcasting ability modifier.\nInterposing Hand. The hand grants you Half Cover against attacks and other effects that originate from its space or that pass through it. In addition, its space counts as Difficult Terrain for your enemies.\nUsing a Higher-Level Spell Slot. The damage of the Clenched Fist increases by 2d8 and the damage of the Grasping Hand increases by 2d6 for each spell slot level above 5.","concDuration":"1 min","attack":"melee","save":"str","effect":{"dice":"5d8","type":"force"},"higher":"The damage of the Clenched Fist increases by 2d8 and the damage of the Grasping Hand increases by 2d6 for each spell slot level above 5.","upcast":{"dice":"2d6"},"componentsShort":"V, S, M"},{"id":"arcane-lock","name":"Arcane Lock","level":2,"school":"Abjuration","classes":["wizard"],"time":"Action","range":"Touch","components":"V, S, M (gold dust worth 25+ GP, which the spell consumes)","duration":"Until dispelled","concentration":false,"text":"You touch a closed door, window, gate, container, or hatch and magically lock it for the duration. This lock can’t be unlocked by any nonmagical means. You and any creatures you designate when you cast the spell can open and close the object despite the lock. You can also set a password that, when spoken within 5 ft of the object, unlocks it for 1 minute.","componentsShort":"V, S, M","effect":{"text":"Touch a closed door, window, gate, container, or hatch and…"}},{"id":"arcane-sword","name":"Arcane Sword","level":7,"school":"Evocation","classes":["bard","wizard"],"time":"Action","range":"90 ft","components":"V, S, M (a miniature sword worth 250+ GP)","duration":"Up to 1 minute","concentration":true,"text":"You create a spectral sword that hovers within range. It lasts for the duration.\nWhen the sword appears, you make a melee spell attack against a target within 5 ft of the sword. On a hit, the target takes Force damage equal to 4d12 plus your spellcasting ability modifier. On your later turns, you can take a Bonus Action to move the sword up to 30 ft to a spot you can see and repeat the attack against the same target or a different one.","concDuration":"1 min","attack":"melee","componentsShort":"V, S, M","effect":{"text":"Create a spectral sword that hovers within range"}},{"id":"arcanists-magic-aura","name":"Arcanist’s Magic Aura","level":2,"school":"Illusion","classes":["wizard"],"time":"Action","range":"Touch","components":"V, S, M (a small square of silk)","duration":"24 hours","concentration":false,"text":"With a touch, you place an illusion on a willing creature or an object that isn’t being worn or carried. A creature gains the Mask effect below, and an object gains the False Aura effect below. The effect lasts for the duration. If you cast the spell on the same target every day for 30 days, the illusion lasts until dispelled.\nMask (Creature). Choose a creature type other than the target’s actual type. Spells and other magical effects treat the target as if it were a creature of the chosen type.\nFalse Aura (Object). You change the way the target appears to spells and magical effects that detect magical auras, such as Detect Magic. You can make a nonmagical object appear magical, make a magic item appear nonmagical, or change the object’s aura so that it appears to belong to a school of magic you choose.","componentsShort":"V, S, M","effect":{"text":"With a touch, you place an illusion on a willing creature or…"}},{"id":"astral-projection","name":"Astral Projection","level":9,"school":"Necromancy","classes":["cleric","warlock","wizard"],"time":"1 hour","range":"10 ft","components":"V, S, M (for each of the spell’s targets, one jacinth worth 1,000+ GP and one silver bar worth 100+ GP, all of which the spell consumes)","duration":"Until dispelled","concentration":false,"text":"You and up to eight willing creatures within range project your astral bodies into the Astral Plane (the spell ends instantly if you are already on that plane). Each target’s body is left behind in a state of suspended animation; it has the Unconscious condition, doesn’t need food or air, and doesn’t age. A target’s astral form resembles its body in almost every way, replicating its game statistics and possessions. The principal difference is the addition of a silvery cord that trails from between the shoulder blades of the astral form. The cord fades from view after 1 ft. If the cord is cut—which happens only when an effect states that it does so—the target’s body and astral form both die.\nA target’s astral form can travel through the Astral Plane. The moment an astral form leaves that plane, the target’s body and possessions travel along the silver cord, causing the target to re-enter its body on the new plane.\nAny damage or other effects that apply to an astral form have no effect on the target’s body and vice versa. If a target’s body or astral form drops to 0 Hit Points, the spell ends for that target. The spell ends for all the targets if you take a Magic action to dismiss it.\nWhen the spell ends for a target who isn’t dead, the target reappears in its body and exits the state of suspended animation.","componentsShort":"V, S, M","effect":{"text":"And up to eight willing creatures within range project your…"}},{"id":"augury","name":"Augury","level":2,"school":"Divination","classes":["cleric","druid","wizard"],"time":"1 minute","range":"Self","components":"V, S, M (specially marked sticks, bones, cards, or other divinatory tokens worth 25+ GP)","duration":"Instantaneous","concentration":false,"text":"You receive an omen from an otherworldly entity about the results of a course of action that you plan to take within the next 30 minutes. The GM chooses the omen from the Omens table.\nOmens Omen\nFor Results That Will Be …\nWeal\nGood\nWoe\nBad\nWeal and woe\nGood and bad\nIndifference\nNeither good nor bad\nThe spell doesn’t account for circumstances, such as other spells, that might change the results.\nIf you cast the spell more than once before finishing a Long Rest, there is a cumulative 25 percent chance for each casting after the first that you get no answer.","ritual":true,"componentsShort":"V, S, M","effect":{"text":"Receive an omen from an otherworldly entity about the results…"}},{"id":"aura-of-life","name":"Aura of Life","level":4,"school":"Abjuration","classes":["cleric","paladin"],"time":"Action","range":"Self","components":"V","duration":"Up to 10 minutes","concentration":true,"text":"An aura radiates from you in a 30-ft Emanation for the duration. While in the aura, you and your allies have Resistance to Necrotic damage, and your Hit Point maximums can’t be reduced. If an ally with 0 Hit Points starts its turn in the aura, that ally regains 1 Hit Point.","concDuration":"10 min","componentsShort":"V","effect":{"text":"An aura radiates from you in a 30-ft Emanation for the duration"}},{"id":"awaken","name":"Awaken","level":5,"school":"Transmutation","classes":["bard","druid"],"time":"8 hours","range":"Touch","components":"V, S, M (an agate worth 1,000+ GP, which the spell consumes)","duration":"Instantaneous","concentration":false,"text":"You spend the casting time tracing magical pathways within a precious gemstone, and then touch the target. The target must be either a Beast or Plant creature with an Intelligence of 3 or less or a natural plant that isn’t a creature. The target gains an Intelligence of 10 and the ability to speak one language you know. If the target is a natural plant, it becomes a Plant creature and gains the ability to move its limbs, roots, vines, creepers, and so forth, and it gains senses similar to a human’s. The GM chooses statistics appropriate for the awakened Plant, such as the statistics for the Awakened Shrub or Awakened Tree in “Monsters.”\nThe awakened target has the Charmed condition for 30 days or until you or your allies deal damage to it. When that condition ends, the awakened creature chooses its attitude toward you.","componentsShort":"V, S, M","effect":{"text":"Spend the casting time tracing magical pathways within a…"}},{"id":"bane","name":"Bane","level":1,"school":"Enchantment","classes":["bard","cleric","warlock"],"time":"Action","range":"30 ft","components":"V, S, M (a drop of blood)","duration":"Up to 1 minute","concentration":true,"text":"Up to three creatures of your choice that you can see within range must each make a Charisma saving throw. Whenever a target that fails this save makes an attack roll or a saving throw before the spell ends, the target must subtract 1d4 from the attack roll or save.\nUsing a Higher-Level Spell Slot. You can target one additional creature for each spell slot level above 1.","concDuration":"1 min","save":"cha","higher":"You can target one additional creature for each spell slot level above 1.","componentsShort":"V, S, M","effect":{"text":"Up to three creatures of your choice that you can see within…"}},{"id":"banishment","name":"Banishment","level":4,"school":"Abjuration","classes":["cleric","paladin","sorcerer","warlock","wizard"],"time":"Action","range":"30 ft","components":"V, S, M (a pentacle)","duration":"Up to 1 minute","concentration":true,"text":"One creature that you can see within range must succeed on a Charisma saving throw or be transported to a harmless demiplane for the duration. While there, the target has the Incapacitated condition. When the spell ends, the target reappears in the space it left or in the nearest unoccupied space if that space is occupied.\nIf the target is an Aberration, a Celestial, an Elemental, a Fey, or a Fiend, the target doesn’t return if the spell lasts for 1 minute. The target is instead transported to a random location on a plane (GM’s choice) associated with its creature type.\nUsing a Higher-Level Spell Slot. You can target one additional creature for each spell slot level above 4.","concDuration":"1 min","save":"cha","higher":"You can target one additional creature for each spell slot level above 4.","componentsShort":"V, S, M","effect":{"text":"Send a creature to a harmless demiplane"}},{"id":"barkskin","name":"Barkskin","level":2,"school":"Transmutation","classes":["druid","ranger"],"time":"Bonus Action","range":"Touch","components":"V, S, M (a handful of bark)","duration":"1 hour","concentration":false,"text":"You touch a willing creature. Until the spell ends, the target’s skin assumes a bark-like appearance, and the target has an Armor Class of 17 if its AC is lower than that.","componentsShort":"V, S, M","effect":{"text":"AC can’t be lower than 17"}},{"id":"beacon-of-hope","name":"Beacon of Hope","level":3,"school":"Abjuration","classes":["cleric"],"time":"Action","range":"30 ft","components":"V, S","duration":"Up to 1 minute","concentration":true,"text":"Choose any number of creatures within range. For the duration, each target has Advantage on Wisdom saving throws and Death Saving Throws and regains the maximum number of Hit Points possible from any healing.","concDuration":"1 min","save":"wis","componentsShort":"V, S","effect":{"text":"Advantage on WIS and death saves; max healing"}},{"id":"befuddlement","name":"Befuddlement","level":8,"school":"Enchantment","classes":["bard","druid","warlock","wizard"],"time":"Action","range":"150 ft","components":"V, S, M (a key ring with no keys)","duration":"Instantaneous","concentration":false,"text":"You blast the mind of a creature that you can see within range. The target makes an Intelligence saving throw.\nOn a failed save, the target takes 10d12 Psychic damage and can’t cast spells or take the Magic action. At the end of every 30 days, the target repeats the save, ending the effect on a success. The effect can also be ended by the Greater Restoration, Heal, or Wish spell.\nOn a successful save, the target takes half as much damage only.","save":"int","effect":{"dice":"10d12","type":"psychic","addMod":false,"text":"10d12 psychic; can’t cast or think clearly"},"componentsShort":"V, S, M"},{"id":"bestow-curse","name":"Bestow Curse","level":3,"school":"Necromancy","classes":["bard","cleric","wizard"],"time":"Action","range":"Touch","components":"V, S","duration":"Up to 1 minute","concentration":true,"text":"You touch a creature, which must succeed on a Wisdom saving throw or become cursed for the duration. Until the curse ends, the target suffers one of the following effects of your choice:\n• Choose one ability. The target has Disadvantage on ability checks and saving throws made with that ability.\n• The target has Disadvantage on attack rolls against you.\n• In combat, the target must succeed on a Wisdom saving throw at the start of each of its turns or be forced to take the Dodge action on that turn.\n• If you deal damage to the target with an attack roll or a spell, the target takes an extra 1d8 Necrotic damage.\nUsing a Higher-Level Spell Slot. If you cast this spell using a level 4 spell slot, you can maintain Concentration on it for up to 10 minutes. If you use a level 5+ spell slot, the spell doesn’t require Concentration, and the duration becomes 8 hours (level 5–6 slot) or 24 hours (level 7–8 slot). If you use a level 9 spell slot, the spell lasts until dispelled.","concDuration":"1 min","save":"wis","effect":{"dice":"1d8","type":"necrotic"},"higher":"If you cast this spell using a level 4 spell slot, you can maintain Concentration on it for up to 10 minutes. If you use a level 5+ spell slot, the spell doesn’t require Concentration, and the duration becomes 8 hours (level 5–6 slot) or 24 hours (level 7–8 slot). If you use a level 9 spell slot, the spell lasts until dispelled.","componentsShort":"V, S"},{"id":"black-tentacles","name":"Black Tentacles","level":4,"school":"Conjuration","classes":["wizard"],"time":"Action","range":"90 ft","components":"V, S, M (a tentacle)","duration":"Up to 1 minute","concentration":true,"text":"Squirming, ebony tentacles fill a 20-ft square on ground that you can see within range. For the duration, these tentacles turn the ground in that area into Difficult Terrain.\nEach creature in that area makes a Strength saving throw. On a failed save, it takes 3d6 Bludgeoning damage, and it has the Restrained condition until the spell ends. A creature also makes that save if it enters the area or ends it turn there. A creature makes that save only once per turn.\nA Restrained creature can take an action to make a Strength (Athletics) check against your spell save DC, ending the condition on itself on a success.","concDuration":"1 min","save":"str","effect":{"dice":"3d6","type":"bludgeoning"},"componentsShort":"V, S, M"},{"id":"blade-barrier","name":"Blade Barrier","level":6,"school":"Evocation","classes":["cleric"],"time":"Action","range":"90 ft","components":"V, S","duration":"Up to 10 minutes","concentration":true,"text":"You create a wall of whirling blades made of magical energy. The wall appears within range and lasts for the duration. You make a straight wall up to 100 ft long, 20 ft high, and 5 ft thick, or a ringed wall up to 60 ft in diameter, 20 ft high, and 5 ft thick. The wall provides Three-Quarters Cover, and its space is Difficult Terrain.\nAny creature in the wall’s space makes a Dexterity saving throw, taking 6d10 Force damage on a failed save or half as much damage on a successful one. A creature also makes that save if it enters the wall’s space or ends it turn there. A creature makes that save only once per turn.","concDuration":"10 min","save":"dex","effect":{"dice":"6d10","type":"force"},"componentsShort":"V, S"},{"id":"bless","name":"Bless","level":1,"school":"Enchantment","classes":["cleric","paladin"],"time":"Action","range":"30 ft","components":"V, S, M (a Holy Symbol worth 5+ GP)","duration":"Up to 1 minute","concentration":true,"text":"You bless up to three creatures within range. Whenever a target makes an attack roll or a saving throw before the spell ends, the target adds 1d4 to the attack roll or save.\nUsing a Higher-Level Spell Slot. You can target one additional creature for each spell slot level above 1.","concDuration":"1 min","higher":"You can target one additional creature for each spell slot level above 1.","componentsShort":"V, S, M","effect":{"text":"+1d4 to attacks and saves, up to 3 creatures"}},{"id":"blight","name":"Blight","level":4,"school":"Necromancy","classes":["druid","sorcerer","warlock","wizard"],"time":"Action","range":"30 ft","components":"V, S","duration":"Instantaneous","concentration":false,"text":"A creature that you can see within range makes a Constitution saving throw, taking 8d8 Necrotic damage on a failed save or half as much damage on a successful one. A Plant creature automatically fails the save.\nAlternatively, target a nonmagical plant that isn’t a creature, such as a tree or shrub. It doesn’t make a save; it simply withers and dies.\nUsing a Higher-Level Spell Slot. The damage increases by 1d8 for each spell slot level above 4.","save":"con","effect":{"dice":"8d8","type":"necrotic","addMod":false},"higher":"The damage increases by 1d8 for each spell slot level above 4.","upcast":{"dice":"1d8"},"componentsShort":"V, S"},{"id":"blindness-deafness","name":"Blindness/Deafness","level":2,"school":"Transmutation","classes":["bard","cleric","sorcerer","wizard"],"time":"Action","range":"120 ft","components":"V","duration":"1 minute","concentration":false,"text":"One creature that you can see within range must succeed on a Constitution saving throw, or it has the Blinded or Deafened condition (your choice) for the duration. At the end of each of its turns, the target repeats the save, ending the spell on itself on a success.\nUsing a Higher-Level Spell Slot. You can target one additional creature for each spell slot level above 2.","save":"con","higher":"You can target one additional creature for each spell slot level above 2.","componentsShort":"V","effect":{"text":"One creature that you can see within range must succeed on a…"}},{"id":"blink","name":"Blink","level":3,"school":"Transmutation","classes":["sorcerer","wizard"],"time":"Action","range":"Self","components":"V, S","duration":"1 minute","concentration":false,"text":"Roll 1d6 at the end of each of your turns for the duration. On a roll of 4–6, you vanish from your current plane of existence and appear in the Ethereal Plane (the spell ends instantly if you are already on that plane). While on the Ethereal Plane, you can perceive the plane you left, which is cast in shades of gray, but you can’t see anything there more than 60 ft away. You can affect and be affected only by other creatures on the Ethereal Plane, and creatures on the other plane can’t perceive you unless they have a special ability that lets them perceive things on the Ethereal Plane.\nYou return to the other plane at the start of your next turn and when the spell ends if you are on the Ethereal Plane. You return to an unoccupied space of your choice that you can see within 10 ft of the space you left. If no unoccupied space is available within that range, you appear in the nearest unoccupied space.","componentsShort":"V, S","effect":{"text":"Roll 1d6 at the end of each of your turns for the duration"}},{"id":"blur","name":"Blur","level":2,"school":"Illusion","classes":["sorcerer","wizard"],"time":"Action","range":"Self","components":"V","duration":"Up to 1 minute","concentration":true,"text":"Your body becomes blurred. For the duration, any creature has Disadvantage on attack rolls against you. An attacker is immune to this effect if it perceives you with Blindsight or Truesight.","concDuration":"1 min","componentsShort":"V","effect":{"text":"Attacks against you have Disadvantage"}},{"id":"burning-hands","name":"Burning Hands","level":1,"school":"Evocation","classes":["sorcerer","wizard"],"time":"Action","range":"Self","components":"V, S","duration":"Instantaneous","concentration":false,"text":"A thin sheet of flames shoots forth from you. Each creature in a 15-ft Cone makes a Dexterity saving throw, taking 3d6 Fire damage on a failed save or half as much damage on a successful one.\nFlammable objects in the Cone that aren’t being worn or carried start burning.\nUsing a Higher-Level Spell Slot. The damage increases by 1d6 for each spell slot level above 1.","save":"dex","effect":{"dice":"3d6","type":"fire"},"higher":"The damage increases by 1d6 for each spell slot level above 1.","upcast":{"dice":"1d6"},"componentsShort":"V, S"},{"id":"call-lightning","name":"Call Lightning","level":3,"school":"Conjuration","classes":["druid"],"time":"Action","range":"120 ft","components":"V, S","duration":"Up to 10 minutes","concentration":true,"text":"A storm cloud appears at a point within range that you can see above yourself. It takes the shape of a Cylinder that is 10 ft tall with a 60-ft radius.\nWhen you cast the spell, choose a point you can see under the cloud. A lightning bolt shoots from the cloud to that point. Each creature within 5 ft of that point makes a Dexterity saving throw, taking 3d10 Lightning damage on a failed save or half as much damage on a successful one.\nUntil the spell ends, you can take a Magic action to call down lightning in that way again, targeting the same point or a different one.\nIf you’re outdoors in a storm when you cast this spell, the spell gives you control over that storm instead of creating a new one. Under such conditions, the spell’s damage increases by 1d10.\nUsing a Higher-Level Spell Slot. The damage increases by 1d10 for each spell slot level above 3.","concDuration":"10 min","save":"dex","effect":{"dice":"3d10","type":"lightning"},"higher":"The damage increases by 1d10 for each spell slot level above 3.","upcast":{"dice":"1d10"},"componentsShort":"V, S"},{"id":"calm-emotions","name":"Calm Emotions","level":2,"school":"Enchantment","classes":["bard","cleric"],"time":"Action","range":"60 ft","components":"V, S","duration":"Up to 1 minute","concentration":true,"text":"Each Humanoid in a 20-ft-radius Sphere centered on a point you choose within range must succeed on a Charisma saving throw or be affected by one of the following effects (choose for each creature):\n• The creature has Immunity to the Charmed and Frightened conditions until the spell ends. If the creature was already Charmed or Frightened, those conditions are suppressed for the duration.\n• The creature becomes Indifferent about creatures of your choice that it’s Hostile toward. This indifference ends if the target takes damage or witnesses its allies taking damage. When the spell ends, the creature’s attitude returns to normal.","concDuration":"1 min","save":"cha","componentsShort":"V, S","effect":{"text":"Each Humanoid in a 20-ft-radius Sphere centered on a point…"}},{"id":"chain-lightning","name":"Chain Lightning","level":6,"school":"Evocation","classes":["sorcerer","wizard"],"time":"Action","range":"150 ft","components":"V, S, M (three silver pins)","duration":"Instantaneous","concentration":false,"text":"You launch a lightning bolt toward a target you can see within range. Three bolts then leap from that target to as many as three other targets of your choice, each of which must be within 30 ft of the first target. A target can be a creature or an object and can be targeted by only one of the bolts.\nEach target makes a Dexterity saving throw, taking 10d8 Lightning damage on a failed save or half as much damage on a successful one.\nUsing a Higher-Level Spell Slot. One additional bolt leaps from the first target to another target for each spell slot level above 6.","save":"dex","effect":{"dice":"10d8","type":"lightning","addMod":false,"text":"One target + 3 more within 30 ft"},"higher":"One additional bolt leaps from the first target to another target for each spell slot level above 6.","componentsShort":"V, S, M"},{"id":"charm-monster","name":"Charm Monster","level":4,"school":"Enchantment","classes":["bard","druid","sorcerer","warlock","wizard"],"time":"Action","range":"30 ft","components":"V, S","duration":"1 hour","concentration":false,"text":"One creature you can see within range makes a Wisdom saving throw. It does so with Advantage if you or your allies are fighting it. On a failed save, the target has the Charmed condition until the spell ends or until you or your allies damage it. The Charmed creature is Friendly to you. When the spell ends, the target knows it was Charmed by you.\nUsing a Higher-Level Spell Slot. You can target one additional creature for each spell slot level above 4.","save":"wis","higher":"You can target one additional creature for each spell slot level above 4.","componentsShort":"V, S","effect":{"text":"Charmed (any creature) for 1 hour"}},{"id":"charm-person","name":"Charm Person","level":1,"school":"Enchantment","classes":["bard","druid","sorcerer","warlock","wizard"],"time":"Action","range":"30 ft","components":"V, S","duration":"1 hour","concentration":false,"text":"One Humanoid you can see within range makes a Wisdom saving throw. It does so with Advantage if you or your allies are fighting it. On a failed save, the target has the Charmed condition until the spell ends or until you or your allies damage it. The Charmed creature is Friendly to you. When the spell ends, the target knows it was Charmed by you.\nUsing a Higher-Level Spell Slot. You can target one additional creature for each spell slot level above 1.","save":"wis","higher":"You can target one additional creature for each spell slot level above 1.","componentsShort":"V, S","effect":{"text":"Charmed (friendly) for 1 hour"}},{"id":"chill-touch","name":"Chill Touch","level":0,"school":"Necromancy","classes":["sorcerer","warlock","wizard"],"time":"Action","range":"Touch","components":"V, S","duration":"Instantaneous","concentration":false,"text":"Channeling the chill of the grave, make a melee spell attack against a target within reach. On a hit, the target takes 1d10 Necrotic damage, and it can’t regain Hit Points until the end of your next turn.\nCantrip Upgrade. The damage increases by 1d10 when you reach levels 5 (2d10), 11 (3d10), and 17 (4d10).","attack":"melee","effect":{"dice":"1d10","type":"necrotic"},"componentsShort":"V, S"},{"id":"chromatic-orb","name":"Chromatic Orb","level":1,"school":"Evocation","classes":["sorcerer","wizard"],"time":"Action","range":"90 ft","components":"V, S, M (a diamond worth 50+ GP)","duration":"Instantaneous","concentration":false,"text":"You hurl an orb of energy at a target within range.\nChoose Acid, Cold, Fire, Lightning, Poison, or Thunder for the type of orb you create, and then make a ranged spell attack against the target. On a hit, the target takes 3d8 damage of the chosen type.\nIf you roll the same number on two or more of the d8s, the orb leaps to a different target of your choice within 30 ft of the target. Make an attack roll against the new target, and make a new damage roll. The orb can’t leap again unless you cast the spell with a level 2+ spell slot.\nUsing a Higher-Level Spell Slot. The damage increases by 1d8 for each spell slot level above 1. The orb can leap a maximum number of times equal to the level of the slot expended, and a creature can be targeted only once by each casting of this spell.","attack":"ranged","higher":"The damage increases by 1d8 for each spell slot level above 1. The orb can leap a maximum number of times equal to the level of the slot expended, and a creature can be targeted only once by each casting of this spell.","componentsShort":"V, S, M","effect":{"dice":"3d8","type":"acid, cold, fire, lightning, poison or thunder"}},{"id":"circle-of-death","name":"Circle of Death","level":6,"school":"Necromancy","classes":["sorcerer","warlock","wizard"],"time":"Action","range":"150 ft","components":"V, S, M (the powder of a crushed black pearl worth 500+ GP)","duration":"Instantaneous","concentration":false,"text":"Negative energy ripples out in a 60-ft-radius Sphere from a point you choose within range. Each creature in that area makes a Constitution saving throw, taking 8d8 Necrotic damage on a failed save or half as much damage on a successful one.\nUsing a Higher-Level Spell Slot. The damage increases by 2d8 for each spell slot level above 6.","save":"con","effect":{"dice":"8d8","type":"necrotic","addMod":false},"higher":"The damage increases by 2d8 for each spell slot level above 6.","upcast":{"dice":"2d8"},"componentsShort":"V, S, M"},{"id":"clairvoyance","name":"Clairvoyance","level":3,"school":"Divination","classes":["bard","cleric","sorcerer","wizard"],"time":"10 minutes","range":"1 mile","components":"V, S, M (a focus worth 100+ GP, either a jeweled horn for hearing or a glass eye for seeing)","duration":"Up to 10 minutes","concentration":true,"text":"You create an Invisible sensor within range in a location familiar to you (a place you have visited or seen before) or in an obvious location that is unfamiliar to you (such as behind a door, around a corner, or in a grove of trees). The intangible, invulnerable sensor remains in place for the duration. When you cast the spell, choose seeing or hearing.\nYou can use the chosen sense through the sensor as if you were in its space. As a Bonus Action, you can switch between seeing and hearing.\nA creature that sees the sensor (such as a creature benefiting from See Invisibility or Truesight) sees a luminous orb about the size of your fist.","concDuration":"10 min","componentsShort":"V, S, M","effect":{"text":"Create an Invisible sensor within range in a location…"}},{"id":"clone","name":"Clone","level":8,"school":"Necromancy","classes":["wizard"],"time":"1 hour","range":"Touch","components":"V, S, M (a diamond worth 1,000+ GP, which the spell consumes, and a sealable vessel worth 2,000+ GP that is large enough to hold the creature being cloned)","duration":"Instantaneous","concentration":false,"text":"You touch a creature or at least 1 cubic inch of its flesh. An inert duplicate of that creature forms inside the vessel used in the spell’s casting and finishes growing after 120 days; you choose whether the finished clone is the same age as the creature or younger. The clone remains inert and endures indefinitely while its vessel remains undisturbed. If the original creature dies after the clone finishes forming, the creature’s soul transfers to the clone if the soul is free and willing to return. The clone is physically identical to the original and has the same personality, memories, and abilities, but none of the original’s equipment. The creature’s original remains, if any, become inert and can’t be revived, since the creature’s soul is elsewhere.","componentsShort":"V, S, M","effect":{"text":"Touch a creature or at least 1 cubic inch of its flesh"}},{"id":"cloudkill","name":"Cloudkill","level":5,"school":"Conjuration","classes":["sorcerer","wizard"],"time":"Action","range":"120 ft","components":"V, S","duration":"Up to 10 minutes","concentration":true,"text":"You create a 20-ft-radius Sphere of yellow-green fog centered on a point within range. The fog lasts for the duration or until strong wind (such as the one created by Gust of Wind) disperses it, ending the spell. Its area is Heavily Obscured.\nEach creature in the Sphere makes a Constitution saving throw, taking 5d8 Poison damage on a failed save or half as much damage on a successful one. A creature must also make this save when the Sphere moves into its space and when it enters the Sphere or ends its turn there. A creature makes this save only once per turn.\nThe Sphere moves 10 ft away from you at the start of each of your turns.\nUsing a Higher-Level Spell Slot. The damage increases by 1d8 for each spell slot level above 5.","concDuration":"10 min","save":"con","effect":{"dice":"5d8","type":"poison"},"higher":"The damage increases by 1d8 for each spell slot level above 5.","upcast":{"dice":"1d8"},"componentsShort":"V, S"},{"id":"color-spray","name":"Color Spray","level":1,"school":"Illusion","classes":["bard","sorcerer","wizard"],"time":"Action","range":"Self","components":"V, S, M (a pinch of colorful sand)","duration":"Instantaneous","concentration":false,"text":"You launch a dazzling array of flashing, colorful light. Each creature in a 15-ft Cone originating from you must succeed on a Constitution saving throw or have the Blinded condition until the end of your next turn.","save":"con","componentsShort":"V, S, M","effect":{"text":"Launch a dazzling array of flashing, colorful light"}},{"id":"command","name":"Command","level":1,"school":"Enchantment","classes":["bard","cleric","paladin"],"time":"Action","range":"60 ft","components":"V","duration":"Instantaneous","concentration":false,"text":"You speak a one-word command to a creature you can see within range. The target must succeed on a Wisdom saving throw or follow the command on its next turn. Choose the command from these options:\nApproach. The target moves toward you by the shortest and most direct route, ending its turn if it moves within 5 ft of you.\nDrop. The target drops whatever it is holding and then ends its turn.\nFlee. The target spends its turn moving away from you by the fastest available means.\nGrovel. The target has the Prone condition and then ends its turn.\nHalt. On its turn, the target doesn’t move and takes no action or Bonus Action.\nUsing a Higher-Level Spell Slot. You can affect one additional creature for each spell slot level above 1.","save":"wis","higher":"You can affect one additional creature for each spell slot level above 1.","componentsShort":"V","effect":{"text":"One-word command (approach, drop, flee, grovel, halt)"}},{"id":"commune","name":"Commune","level":5,"school":"Divination","classes":["cleric"],"time":"1 minute","range":"Self","components":"V, S, M (incense)","duration":"1 minute","concentration":false,"text":"You contact a deity or a divine proxy and ask up to three questions that can be answered with yes or no. You must ask your questions before the spell ends. You receive a correct answer for each question.\nDivine beings aren’t necessarily omniscient, so you might receive “unclear” as an answer if a question pertains to information that lies beyond the deity’s knowledge. In a case where a one-word answer could be misleading or contrary to the deity’s interests, the GM might offer a short phrase as an answer instead.\nIf you cast the spell more than once before finishing a Long Rest, there is a cumulative 25 percent chance for each casting after the first that you get no answer.","ritual":true,"componentsShort":"V, S, M","effect":{"text":"Ask your god three yes-or-no questions"}},{"id":"commune-with-nature","name":"Commune with Nature","level":5,"school":"Divination","classes":["druid","ranger"],"time":"1 minute","range":"Self","components":"V, S","duration":"Instantaneous","concentration":false,"text":"You commune with nature spirits and gain knowledge of the surrounding area. In the outdoors, the spell gives you knowledge of the area within 3 miles of you. In caves and other natural underground settings, the radius is limited to 300 ft. The spell doesn’t function where nature has been replaced by construction, such as in castles and settlements.\nChoose three of the following facts; you learn those facts as they pertain to the spell’s area:\n• Locations of settlements • Locations of portals to other planes of existence • Location of one Challenge Rating 10+ creature (GM’s choice) that is a Celestial, an Elemental, a Fey, a Fiend, or an Undead • The most prevalent kind of plant, mineral, or Beast (you choose which to learn) • Locations of bodies of water\nFor example, you could determine the location of a powerful monster in the area, the locations of bodies of water, and the locations of any towns.","ritual":true,"componentsShort":"V, S","effect":{"text":"Commune with nature spirits and gain knowledge of the…"}},{"id":"comprehend-languages","name":"Comprehend Languages","level":1,"school":"Divination","classes":["bard","sorcerer","warlock","wizard"],"time":"Action","range":"Self","components":"V, S, M (a pinch of soot and salt)","duration":"1 hour","concentration":false,"text":"For the duration, you understand the literal meaning of any language that you hear or see signed. You also understand any written language that you see, but you must be touching the surface on which the words are written. It takes about 1 minute to read one page of text. This spell doesn’t decode symbols or secret messages.","ritual":true,"componentsShort":"V, S, M","effect":{"text":"For the duration, you understand the literal meaning of any…"}},{"id":"compulsion","name":"Compulsion","level":4,"school":"Enchantment","classes":["bard"],"time":"Action","range":"30 ft","components":"V, S","duration":"Up to 1 minute","concentration":true,"text":"Each creature of your choice that you can see within range must succeed on a Wisdom saving throw or have the Charmed condition until the spell ends. For the duration, you can take a Bonus Action to designate a direction that is horizontal to you. Each Charmed target must use as much of its movement as possible to move in that direction on its next turn, taking the safest route. After moving in this way, a target repeats the save, ending the spell on itself on a success.","concDuration":"1 min","save":"wis","componentsShort":"V, S","effect":{"text":"Each creature of your choice that you can see within range…"}},{"id":"cone-of-cold","name":"Cone of Cold","level":5,"school":"Evocation","classes":["druid","sorcerer","wizard"],"time":"Action","range":"Self","components":"V, S, M (a small crystal or glass cone)","duration":"Instantaneous","concentration":false,"text":"You unleash a blast of cold air. Each creature in a 60-ft Cone originating from you makes a Constitution saving throw, taking 8d8 Cold damage on a failed save or half as much damage on a successful one. A creature killed by this spell becomes a frozen statue until it thaws.\nUsing a Higher-Level Spell Slot. The damage increases by 1d8 for each spell slot level above 5.","save":"con","effect":{"dice":"8d8","type":"cold","addMod":false},"higher":"The damage increases by 1d8 for each spell slot level above 5.","upcast":{"dice":"1d8"},"componentsShort":"V, S, M"},{"id":"confusion","name":"Confusion","level":4,"school":"Enchantment","classes":["bard","druid","sorcerer","wizard"],"time":"Action","range":"90 ft","components":"V, S, M (three nut shells)","duration":"Up to 1 minute","concentration":true,"text":"Each creature in a 10-ft-radius Sphere centered on a point you choose within range must succeed on a Wisdom saving throw, or that target can’t take Bonus Actions or Reactions and must roll 1d10 at the start of each of its turns to determine its behavior for that turn, consulting the table below.\n1d10 Behavior for the Turn The target doesn’t take an action, and it uses all its movement to move. Roll 1d4 for the direction: 1, north; 2, east; 3, south; or 4, west.\n2–6\nThe target doesn’t move or take actions.\n7–8\nThe target doesn’t move, and it takes the Attack action to make one melee attack against a random creature within reach. If none are within reach, the target takes no action.\n9–10 The target chooses its behavior.\nAt the end of each of its turns, an affected target repeats the save, ending the spell on itself on a success.\nUsing a Higher-Level Spell Slot. The Sphere’s radius increases by 5 ft for each spell slot level above 4.","concDuration":"1 min","save":"wis","higher":"The Sphere’s radius increases by 5 ft for each spell slot level above 4.","componentsShort":"V, S, M","effect":{"text":"Each creature in a 10-ft-radius Sphere centered on a point…"}},{"id":"conjure-animals","name":"Conjure Animals","level":3,"school":"Conjuration","classes":["druid","ranger"],"time":"Action","range":"60 ft","components":"V, S","duration":"Up to 10 minutes","concentration":true,"text":"You conjure nature spirits that appear as a Large pack of spectral, intangible animals in an unoccupied space you can see within range. The pack lasts for the duration, and you choose the spirits’ animal form, such as wolves, serpents, or birds.\nYou have Advantage on Strength saving throws while you’re within 5 ft of the pack, and when you move on your turn, you can also move the pack up to 30 ft to an unoccupied space you can see.\nWhenever the pack moves within 10 ft of a creature you can see and whenever a creature you can see enters a space within 10 ft of the pack or ends its turn there, you can force that creature to make a Dexterity saving throw. On a failed save, the creature takes 3d10 Slashing damage. A creature makes this save only once per turn.\nUsing a Higher-Level Spell Slot. The damage increases by 1d10 for each spell slot level above 3.","concDuration":"10 min","save":"str","effect":{"dice":"3d10","type":"slashing"},"higher":"The damage increases by 1d10 for each spell slot level above 3.","upcast":{"dice":"1d10"},"componentsShort":"V, S"},{"id":"conjure-celestial","name":"Conjure Celestial","level":7,"school":"Conjuration","classes":["cleric"],"time":"Action","range":"90 ft","components":"V, S","duration":"Up to 10 minutes","concentration":true,"text":"You conjure a spirit from the Upper Planes, which manifests as a pillar of light in a 10-ft-radius, 40-ft-high Cylinder centered on a point within range. For each creature you can see in the Cylinder, choose which of these lights shines on it:\nHealing Light. The target regains Hit Points equal to 4d12 plus your spellcasting ability modifier.\nSearing Light. The target makes a Dexterity saving throw, taking 6d12 Radiant damage on a failed save or half as much damage on a successful one.\nUntil the spell ends, Bright Light fills the Cylinder, and when you move on your turn, you can also move the Cylinder up to 30 ft.\nWhenever the Cylinder moves into the space of a creature you can see and whenever a creature you can see enters the Cylinder or ends its turn there, you can bathe it in one of the lights. A creature can be affected by this spell only once per turn.\nUsing a Higher-Level Spell Slot. The healing and damage increase by 1d12 for each spell slot level above 7.","concDuration":"10 min","save":"dex","effect":{"dice":"4d12","type":"healing","addMod":true},"higher":"The healing and damage increase by 1d12 for each spell slot level above 7.","upcast":{"dice":"1d12"},"componentsShort":"V, S"},{"id":"conjure-elemental","name":"Conjure Elemental","level":5,"school":"Conjuration","classes":["druid","wizard"],"time":"Action","range":"60 ft","components":"V, S","duration":"Up to 10 minutes","concentration":true,"text":"You conjure a Large, intangible spirit from the Elemental Planes that appears in an unoccupied space within range. Choose the spirit’s element, which determines its damage type: air (Lightning), earth (Thunder), fire (Fire), or water (Cold). The spirit lasts for the duration.\nWhenever a creature you can see enters the spirit’s space or starts its turn within 5 ft of the spirit, you can force that creature to make a Dexterity saving throw if the spirit has no creature Restrained. On failed save, the target takes 8d8 damage of the spirit’s type, and the target has the Restrained condition until the spell ends. At the start of each of its turns, the Restrained target repeats the save.\nOn a failed save, the target takes 4d8 damage of the spirit’s type. On a successful save, the target isn’t Restrained by the spirit.\nUsing a Higher-Level Spell Slot. The damage increases by 1d8 for each spell slot level above 5.","concDuration":"10 min","save":"dex","higher":"The damage increases by 1d8 for each spell slot level above 5.","componentsShort":"V, S","effect":{"text":"Conjure a Large, intangible spirit from the Elemental Planes…"}},{"id":"conjure-fey","name":"Conjure Fey","level":6,"school":"Conjuration","classes":["druid"],"time":"Action","range":"60 ft","components":"V, S","duration":"Up to 10 minutes","concentration":true,"text":"You conjure a Medium spirit from the Feywild in an unoccupied space you can see within range.\nThe spirit lasts for the duration, and it looks like a Fey creature of your choice. When the spirit appears, you can make one melee spell attack against a creature within 5 ft of it. On a hit, the target takes Psychic damage equal to 3d12 plus your spellcasting ability modifier, and the target has the Frightened condition until the start of your next turn, with both you and the spirit as the source of the fear.\nAs a Bonus Action on your later turns, you can teleport the spirit to an unoccupied space you can see within 30 ft of the space it left and make the attack against a creature within 5 ft of it.\nUsing a Higher-Level Spell Slot. The damage increases by 1d12 for each spell slot level above 6.","concDuration":"10 min","attack":"melee","higher":"The damage increases by 1d12 for each spell slot level above 6.","componentsShort":"V, S","effect":{"text":"Conjure a Medium spirit from the Feywild in an unoccupied…"}},{"id":"conjure-minor-elementals","name":"Conjure Minor Elementals","level":4,"school":"Conjuration","classes":["druid","wizard"],"time":"Action","range":"Self","components":"V, S","duration":"Up to 10 minutes","concentration":true,"text":"You conjure spirits from the Elemental Planes that flit around you in a 15-ft Emanation for the duration. Until the spell ends, any attack you make deals an extra 2d8 damage when you hit a creature in the Emanation. This damage is Acid, Cold, Fire, or Lightning (your choice when you make the attack). In addition, the ground in the Emanation is Difficult Terrain for your enemies.\nUsing a Higher-Level Spell Slot. The damage increases by 1d8 for each spell slot level above 4.","concDuration":"10 min","higher":"The damage increases by 1d8 for each spell slot level above 4.","componentsShort":"V, S","effect":{"text":"Conjure spirits from the Elemental Planes that flit around…"}},{"id":"conjure-woodland-beings","name":"Conjure Woodland Beings","level":4,"school":"Conjuration","classes":["druid","ranger"],"time":"Action","range":"Self","components":"V, S","duration":"Up to 10 minutes","concentration":true,"text":"You conjure nature spirits that flit around you in a 10-ft Emanation for the duration. Whenever the Emanation enters the space of a creature you can see and whenever a creature you can see enters the Emanation or ends its turn there, you can force that creature to make a Wisdom saving throw. The creature takes 5d8 Force damage on a failed save or half as much damage on a successful one. A creature makes this save only once per turn.\nIn addition, you can take the Disengage action as a Bonus Action for the spell’s duration.\nUsing a Higher-Level Spell Slot. The damage increases by 1d8 for each spell slot level above 4.","concDuration":"10 min","save":"wis","effect":{"dice":"5d8","type":"force"},"higher":"The damage increases by 1d8 for each spell slot level above 4.","upcast":{"dice":"1d8"},"componentsShort":"V, S"},{"id":"contact-other-plane","name":"Contact Other Plane","level":5,"school":"Divination","classes":["warlock","wizard"],"time":"1 minute","range":"Self","components":"V","duration":"1 minute","concentration":false,"text":"You mentally contact a demigod, the spirit of a longdead sage, or some other knowledgeable entity from another plane. Contacting this otherworldly intelligence can break your mind. When you cast this spell, make a DC 15 Intelligence saving throw.\nOn a successful save, you can ask the entity up to five questions. You must ask your questions before the spell ends. The GM answers each question with one word, such as “yes,” “no,” “maybe,” “never,” “irrelevant,” or “unclear” (if the entity doesn’t know the answer to the question). If a one-word answer would be misleading, the GM might instead offer a short phrase as an answer.\nOn a failed save, you take 6d6 Psychic damage and have the Incapacitated condition until you finish a Long Rest. A Greater Restoration spell cast on you ends this effect.","ritual":true,"save":"int","effect":{"dice":"6d6","type":"psychic"},"componentsShort":"V"},{"id":"contagion","name":"Contagion","level":5,"school":"Necromancy","classes":["cleric","druid"],"time":"Action","range":"Touch","components":"V, S","duration":"7 days","concentration":false,"text":"Your touch inflicts a magical contagion. The target must succeed on a Constitution saving throw or take 11d8 Necrotic damage and have the Poisoned condition. Also, choose one ability when you cast the spell. While Poisoned, the target has Disadvantage on saving throws made with the chosen ability. The target must repeat the saving throw at the end of each of its turns until it gets three successes or failures. If the target succeeds on three of these saves, the spell ends on the target. If the target fails three of the saves, the spell lasts for 7 days on it.\nWhenever the Poisoned target receives an effect that would end the Poisoned condition, the target must succeed on a Constitution saving throw, or the Poisoned condition doesn’t end on it.","save":"con","effect":{"dice":"11d8","type":"necrotic"},"componentsShort":"V, S"},{"id":"contingency","name":"Contingency","level":6,"school":"Abjuration","classes":["wizard"],"time":"10 minutes","range":"Self","components":"V, S, M (a gem-encrusted statuette of yourself worth 1,500+ GP)","duration":"10 days","concentration":false,"text":"Choose a spell of level 5 or lower that you can cast, that has a casting time of an action, and that can target you. You cast that spell—called the contingent spell—as part of casting Contingency, expending spell slots for both, but the contingent spell doesn’t come into effect. Instead, it takes effect when a certain trigger occurs. You describe that trigger when you cast the two spells. For example, a Contingency cast with Water Breathing might stipulate that Water Breathing comes into effect when you are engulfed in water or a similar liquid.\nThe contingent spell takes effect immediately after the trigger occurs for the first time, whether or not you want it to, and then Contingency ends.\nThe contingent spell takes effect only on you, even if it can normally target others. You can use only one Contingency spell at a time. If you cast this spell again, the effect of another Contingency spell on you ends. Also, Contingency ends on you if its material component is ever not on your person.","componentsShort":"V, S, M","effect":{"text":"Choose a spell of level 5 or lower that you can cast, that…"}},{"id":"continual-flame","name":"Continual Flame","level":2,"school":"Evocation","classes":["cleric","druid","wizard"],"time":"Action","range":"Touch","components":"V, S, M (ruby dust worth 50+ GP, which the spell consumes)","duration":"Until dispelled","concentration":false,"text":"A flame springs from an object that you touch. The effect casts Bright Light in a 20-ft radius and Dim Light for an additional 20 ft. It looks like a regular flame, but it creates no heat and consumes no fuel.\nThe flame can be covered or hidden but not smothered or quenched.","componentsShort":"V, S, M","effect":{"text":"A flame springs from an object that you touch"}},{"id":"control-water","name":"Control Water","level":4,"school":"Transmutation","classes":["cleric","druid","wizard"],"time":"Action","range":"300 ft","components":"V, S, M (a mixture of water and dust)","duration":"Up to 10 minutes","concentration":true,"text":"Until the spell ends, you control any water inside an area you choose that is a Cube up to 100 ft on a side, using one of the following effects. As a Magic action on your later turns, you can repeat the same effect or choose a different one.\nFlood. You cause the water level of all standing water in the area to rise by as much as 20 ft. If you choose an area in a large body of water, you instead create a 20-ft tall wave that travels from one side of the area to the other and then crashes. Any Huge or smaller vehicles in the wave’s path are carried with it to the other side. Any Huge or smaller vehicles struck by the wave have a 25 percent chance of capsizing.\nThe water level remains elevated until the spell ends or you choose a different effect. If this effect produced a wave, the wave repeats on the start of your next turn while the flood effect lasts.\nPart Water. You part water in the area and create a trench. The trench extends across the spell’s area, and the separated water forms a wall to either side. The trench remains until the spell ends or you choose a different effect. The water then slowly fills in the trench over the course of the next round until the normal water level is restored.\nRedirect Flow. You cause flowing water in the area to move in a direction you choose, even if the water has to flow over obstacles, up walls, or in other unlikely directions. The water in the area moves as you direct it, but once it moves beyond the spell’s area, it resumes its flow based on the terrain.\nThe water continues to move in the direction you chose until the spell ends or you choose a different effect.\nWhirlpool. You cause a whirlpool to form in the center of the area, which must be at least 50 ft square and 25 ft deep. The whirlpool lasts until you choose a different effect or the spell ends. The whirlpool is 5 ft wide at the base, up to 50 ft wide at the top, and 25 ft tall. Any creature in the water and within 25 ft of the whirlpool is pulled 10 ft toward it. When a creature enters the whirlpool for the first time on a turn or ends its turn there, it makes a Strength saving throw. On a failed save, the creature takes 2d8 Bludgeoning damage. On a successful save, the creature takes half as much damage. A creature can swim away from the whirlpool only if it first takes an action to pull away and succeeds on a Strength (Athletics) check against your spell save DC.","concDuration":"10 min","save":"str","effect":{"dice":"2d8","type":"bludgeoning"},"componentsShort":"V, S, M"},{"id":"control-weather","name":"Control Weather","level":8,"school":"Transmutation","classes":["cleric","druid","wizard"],"time":"10 minutes","range":"Self","components":"V, S, M (burning incense)","duration":"Up to 8 hours","concentration":true,"text":"You take control of the weather within 5 miles of you for the duration. You must be outdoors to cast this spell, and it ends early if you go indoors. When you cast the spell, you change the current weather conditions, which are determined by the GM. You can change precipitation, temperature, and wind. It takes 1d4 × 10 minutes for the new conditions to take effect. Once they do so, you can change the conditions again. When the spell ends, the weather gradually returns to normal. When you change the weather conditions, find a current condition on the following tables and change its stage by one, up or down. When changing the wind, you can change its direction.\nPrecipitation Stage\nCondition Clear Light clouds Overcast or ground fog Rain, hail, or snow Torrential rain, driving hail, or blizzard\nTemperature\nWind\nStage\nCondition\nStage Heat wave Calm Hot Moderate wind Warm Strong wind Cool Gale Cold Storm Freezing\nCondition","concDuration":"8 hours","componentsShort":"V, S, M","effect":{"text":"Take control of the weather within 5 miles of you for the…"}},{"id":"counterspell","name":"Counterspell","level":3,"school":"Abjuration","classes":["sorcerer","warlock","wizard"],"time":"Reaction","range":"60 ft","components":"S","duration":"Instantaneous","concentration":false,"text":"You attempt to interrupt a creature in the process of casting a spell. The creature makes a Constitution saving throw. On a failed save, the spell dissipates with no effect, and the action, Bonus Action, or Reaction used to cast it is wasted. If that spell was cast with a spell slot, the slot isn’t expended.","trigger":"when you see a creature within 60 ft of yourself casting a spell with Verbal, Somatic, or Material components","save":"con","componentsShort":"S","effect":{"text":"The spell fails on a failed CON save"}},{"id":"create-food-and-water","name":"Create Food and Water","level":3,"school":"Conjuration","classes":["cleric","paladin"],"time":"Action","range":"30 ft","components":"V, S","duration":"Instantaneous","concentration":false,"text":"You create 45 pounds of food and 30 gallons of fresh water on the ground or in containers within range—both useful in fending off the hazards of malnutrition and dehydration. The food is bland but nourishing and looks like a food of your choice, and the water is clean. The food spoils after 24 hours if uneaten.","componentsShort":"V, S","effect":{"text":"Create 45 pounds of food and 30 gallons of fresh water on the…"}},{"id":"create-or-destroy-water","name":"Create or Destroy Water","level":1,"school":"Transmutation","classes":["cleric","druid"],"time":"Action","range":"30 ft","components":"V, S, M (a mix of water and sand)","duration":"Instantaneous","concentration":false,"text":"You do one of the following:\nCreate Water. You create up to 10 gallons of clean water within range in an open container. Alternatively, the water falls as rain in a 30-ft Cube within range, extinguishing exposed flames there.\nDestroy Water. You destroy up to 10 gallons of water in an open container within range. Alternatively, you destroy fog in a 30-ft Cube within range.\nUsing a Higher-Level Spell Slot. You create or destroy 10 additional gallons of water, or the size of the Cube increases by 5 ft, for each spell slot level above 1.","higher":"You create or destroy 10 additional gallons of water, or the size of the Cube increases by 5 ft, for each spell slot level above 1.","componentsShort":"V, S, M","effect":{"text":"Do one of the following:"}},{"id":"create-undead","name":"Create Undead","level":6,"school":"Necromancy","classes":["cleric","warlock","wizard"],"time":"1 minute","range":"10 ft","components":"V, S, M (one 150+ GP black onyx stone for each corpse)","duration":"Instantaneous","concentration":false,"text":"You can cast this spell only at night. Choose up to three corpses of Medium or Small Humanoids within range. Each one becomes a Ghoul under your control (see “Monsters” for its stat block).\nAs a Bonus Action on each of your turns, you can mentally command any creature you animated with this spell if the creature is within 120 ft of you (if you control multiple creatures, you can command any of them at the same time, issuing the same command to them). You decide what action the creature will take and where it will move on its next turn, or you can issue a general command, such as to guard a particular place. If you issue no commands, the creature takes the Dodge action and moves only to avoid harm. Once given an order, the creature continues to follow the order until its task is complete.\nThe creature is under your control for 24 hours, after which it stops obeying any command you’ve given it. To maintain control of the creature for another 24 hours, you must cast this spell on the creature before the current 24-hour period ends. This use of the spell reasserts your control over up to three creatures you have animated with this spell rather than animating new ones.\nUsing a Higher-Level Spell Slot. If you use a level 7 spell slot, you can animate or reassert control over four Ghouls. If you use a level 8 spell slot, you can animate or reassert control over five Ghouls or two Ghasts or Wights. If you use a level 9 spell slot, you can animate or reassert control over six Ghouls, three Ghasts or Wights, or two Mummies.\nSee “Monsters” for these stat blocks.","higher":"If you use a level 7 spell slot, you can animate or reassert control over four Ghouls. If you use a level 8 spell slot, you can animate or reassert control over five Ghouls or two Ghasts or Wights. If you use a level 9 spell slot, you can animate or reassert control over six Ghouls, three Ghasts or Wights, or two Mummies.","componentsShort":"V, S, M","effect":{"text":"Can cast this spell only at night"}},{"id":"creation","name":"Creation","level":5,"school":"Illusion","classes":["sorcerer","wizard"],"time":"1 minute","range":"30 ft","components":"V, S, M (a paintbrush)","duration":"Special","concentration":false,"text":"You pull wisps of shadow material from the Shadowfell to create an object within range. It is either an object of vegetable matter (soft goods, rope, wood, and the like) or mineral matter (stone, crystal, metal, and the like). The object must be no larger than a 5-ft Cube, and the object must be of a form and material that you have seen.\nThe spell’s duration depends on the object’s material, as shown in the Materials table. If the object is composed of multiple materials, use the shortest duration. Using any object created by this spell as another spell’s Material component causes the other spell to fail.\nMaterials Material\nDuration\nVegetable matter 24 hours\nStone or crystal 12 hours\nPrecious metals 1 hour\nGems 10 minutes\nAdamantine or mithral 1 minute\nUsing a Higher-Level Spell Slot. The Cube increases by 5 ft for each spell slot level above 5.","higher":"The Cube increases by 5 ft for each spell slot level above 5.","componentsShort":"V, S, M","effect":{"text":"Pull wisps of shadow material from the Shadowfell to create…"}},{"id":"cure-wounds","name":"Cure Wounds","level":1,"school":"Abjuration","classes":["bard","cleric","druid","paladin","ranger"],"time":"Action","range":"Touch","components":"V, S","duration":"Instantaneous","concentration":false,"text":"A creature you touch regains a number of Hit Points equal to 2d8 plus your spellcasting ability modifier.\nUsing a Higher-Level Spell Slot. The healing increases by 2d8 for each spell slot level above 1.","effect":{"dice":"2d8","type":"healing","addMod":true},"higher":"The healing increases by 2d8 for each spell slot level above 1.","upcast":{"dice":"2d8"},"componentsShort":"V, S"},{"id":"dancing-lights","name":"Dancing Lights","level":0,"school":"Illusion","classes":["bard","sorcerer","wizard"],"time":"Action","range":"120 ft","components":"V, S, M (a bit of phosphorus)","duration":"Up to 1 minute","concentration":true,"text":"You create up to four torch-size lights within range, making them appear as torches, lanterns, or glowing orbs that hover for the duration. Alternatively, you combine the four lights into one glowing Medium form that is vaguely humanlike. Whichever form you choose, each light sheds Dim Light in a 10foot radius.\nAs a Bonus Action, you can move the lights up to 60 ft to a space within range. A light must be within 20 ft of another light created by this spell, and a light vanishes if it exceeds the spell’s range.","concDuration":"1 min","componentsShort":"V, S, M","effect":{"text":"Up to four floating lights"}},{"id":"darkness","name":"Darkness","level":2,"school":"Evocation","classes":["sorcerer","warlock","wizard"],"time":"Action","range":"60 ft","components":"V, M (bat fur and a piece of coal)","duration":"Up to 10 minutes","concentration":true,"text":"For the duration, magical Darkness spreads from a point within range and fills a 15-ft-radius Sphere. Darkvision can’t see through it, and nonmagical light can’t illuminate it.\nAlternatively, you cast the spell on an object that isn’t being worn or carried, causing the Darkness to fill a 15-ft Emanation originating from that object. Covering that object with something opaque, such as a bowl or helm, blocks the Darkness. If any of this spell’s area overlaps with an area of Bright Light or Dim Light created by a spell of level 2 or lower, that other spell is dispelled.","concDuration":"10 min","componentsShort":"V, M","effect":{"text":"15-ft sphere of magical darkness"}},{"id":"darkvision","name":"Darkvision","level":2,"school":"Transmutation","classes":["druid","ranger","sorcerer","wizard"],"time":"Action","range":"Touch","components":"V, S, M (a dried carrot)","duration":"8 hours","concentration":false,"text":"For the duration, a willing creature you touch has Darkvision with a range of 150 ft.","componentsShort":"V, S, M","effect":{"text":"Darkvision 150 ft"}},{"id":"daylight","name":"Daylight","level":3,"school":"Evocation","classes":["cleric","druid","paladin","ranger","sorcerer"],"time":"Action","range":"60 ft","components":"V, S","duration":"1 hour","concentration":false,"text":"For the duration, sunlight spreads from a point within range and fills a 60-ft-radius Sphere. The sunlight’s area is Bright Light and sheds Dim Light for an additional 60 ft.\nAlternatively, you cast the spell on an object that isn’t being worn or carried, causing the sunlight to fill a 60-ft Emanation originating from that object. Covering that object with something opaque, such as a bowl or helm, blocks the sunlight. If any of this spell’s area overlaps with an area of Darkness created by a spell of level 3 or lower, that other spell is dispelled.","componentsShort":"V, S","effect":{"text":"60-ft sphere of sunlight"}},{"id":"death-ward","name":"Death Ward","level":4,"school":"Abjuration","classes":["cleric","paladin"],"time":"Action","range":"Touch","components":"V, S","duration":"8 hours","concentration":false,"text":"You touch a creature and grant it a measure of protection from death. The first time the target would drop to 0 Hit Points before the spell ends, the target instead drops to 1 Hit Point, and the spell ends.\nIf the spell is still in effect when the target is subjected to an effect that would kill it instantly without dealing damage, that effect is negated against the target, and the spell ends.","componentsShort":"V, S","effect":{"text":"Drop to 1 HP instead of 0, once"}},{"id":"delayed-blast-fireball","name":"Delayed Blast Fireball","level":7,"school":"Evocation","classes":["sorcerer","wizard"],"time":"Action","range":"150 ft","components":"V, S, M (a ball of bat guano and sulfur)","duration":"Up to 1 minute","concentration":true,"text":"A beam of yellow light flashes from you, then condenses at a chosen point within range as a glowing bead for the duration. When the spell ends, the bead explodes, and each creature in a 20-ft-radius Sphere centered on that point makes a Dexterity saving throw. A creature takes Fire damage equal to the total accumulated damage on a failed save or half as much damage on a successful one.\nThe spell’s base damage is 12d6, and the damage increases by 1d6 whenever your turn ends and the spell hasn’t ended.\nIf a creature touches the glowing bead before the spell ends, that creature makes a Dexterity saving throw. On a failed save, the spell ends, causing the bead to explode. On a successful save, the creature can throw the bead up to 40 ft. If the thrown bead enters a creature’s space or collides with a solid object, the spell ends, and the bead explodes. When the bead explodes, flammable objects in the explosion that aren’t being worn or carried start burning.\nUsing a Higher-Level Spell Slot. The base damage increases by 1d6 for each spell slot level above 7.","concDuration":"1 min","save":"dex","higher":"The base damage increases by 1d6 for each spell slot level above 7.","componentsShort":"V, S, M","effect":{"dice":"12d6","type":"fire","addMod":false,"text":"12d6 fire, +1d6 per turn held"}},{"id":"demiplane","name":"Demiplane","level":8,"school":"Conjuration","classes":["sorcerer","warlock","wizard"],"time":"Action","range":"60 ft","components":"S","duration":"1 hour","concentration":false,"text":"You create a shadowy Medium door on a flat solid surface that you can see within range. This door can be opened and closed, and it leads to a demiplane that is an empty room 30 ft in each dimension, made of wood or stone (your choice).\nWhen the spell ends, the door vanishes, and any objects inside the demiplane remain there. Any creatures inside also remain unless they opt to be shunted through the door as it vanishes, landing with the Prone condition in the unoccupied spaces closest to the door’s former space.\nEach time you cast this spell, you can create a new demiplane or connect the shadowy door to a demiplane you created with a previous casting of this spell. Additionally, if you know the nature and contents of a demiplane created by a casting of this spell by another creature, you can connect the shadowy door to that demiplane instead.","componentsShort":"S","effect":{"text":"A door to a private 30-ft room"}},{"id":"detect-evil-and-good","name":"Detect Evil and Good","level":1,"school":"Divination","classes":["cleric","paladin"],"time":"Action","range":"Self","components":"V, S","duration":"Up to 10 minutes","concentration":true,"text":"For the duration, you sense the location of any Aberration, Celestial, Elemental, Fey, Fiend, or Undead within 30 ft of yourself. You also sense whether the Hallow spell is active there and, if so, where.\nThe spell is blocked by 1 ft of stone, dirt, or wood; 1 inch of metal; or a thin sheet of lead.","concDuration":"10 min","componentsShort":"V, S","effect":{"text":"For the duration, you sense the location of any Aberration,…"}},{"id":"detect-magic","name":"Detect Magic","level":1,"school":"Divination","classes":["bard","cleric","druid","paladin","ranger","sorcerer","warlock","wizard"],"time":"Action","range":"Self","components":"V, S","duration":"Up to 10 minutes","concentration":true,"text":"For the duration, you sense the presence of magical effects within 30 ft of yourself. If you sense such effects, you can take the Magic action to see a faint aura around any visible creature or object in the area that bears the magic, and if an effect was created by a spell, you learn the spell’s school of magic. The spell is blocked by 1 ft of stone, dirt, or wood; 1 inch of metal; or a thin sheet of lead.","concDuration":"10 min","ritual":true,"componentsShort":"V, S","effect":{"text":"Sense magic within 30 ft"}},{"id":"detect-poison-and-disease","name":"Detect Poison and Disease","level":1,"school":"Divination","classes":["cleric","druid","paladin","ranger"],"time":"Action","range":"Self","components":"V, S, M (a yew leaf)","duration":"Up to 10 minutes","concentration":true,"text":"For the duration, you sense the location of poisons, poisonous or venomous creatures, and magical contagions within 30 ft of yourself. You sense the kind of poison, creature, or contagion in each case. The spell is blocked by 1 ft of stone, dirt, or wood; 1 inch of metal; or a thin sheet of lead.","concDuration":"10 min","ritual":true,"componentsShort":"V, S, M","effect":{"text":"For the duration, you sense the location of poisons,…"}},{"id":"detect-thoughts","name":"Detect Thoughts","level":2,"school":"Divination","classes":["bard","sorcerer","wizard"],"time":"Action","range":"Self","components":"V, S, M (1 Copper Piece)","duration":"Up to 1 minute","concentration":true,"text":"You activate one of the effects below. Until the spell ends, you can activate either effect as a Magic action on your later turns.\nSense Thoughts. You sense the presence of thoughts within 30 ft of yourself that belong to creatures that know languages or are telepathic.\nYou don’t read the thoughts, but you know that a thinking creature is present.\nThe spell is blocked by 1 ft of stone, dirt, or wood; 1 inch of metal; or a thin sheet of lead.\nRead Thoughts. Target one creature you can see within 30 ft of yourself or one creature within 30 ft of yourself that you detected with the Sense Thoughts option. You learn what is most on the target’s mind right now. If the target doesn’t know any languages and isn’t telepathic, you learn nothing.\nAs a Magic action on your next turn, you can try to probe deeper into the target’s mind. If you probe deeper, the target makes a Wisdom saving throw.\nOn a failed save, you discern the target’s reasoning, emotions, and something that looms large in its mind (such as a worry, love, or hate). On a successful save, the spell ends. Either way, the target knows that you are probing into its mind, and until you shift your attention away from the target’s mind, the target can take an action on its turn to make an Intelligence (Arcana) check against your spell save DC, ending the spell on a success.","concDuration":"1 min","save":"wis","componentsShort":"V, S, M","effect":{"text":"Activate one of the effects below"}},{"id":"dimension-door","name":"Dimension Door","level":4,"school":"Conjuration","classes":["bard","sorcerer","warlock","wizard"],"time":"Action","range":"500 ft","components":"V","duration":"Instantaneous","concentration":false,"text":"You teleport to a location within range. You arrive at exactly the spot desired. It can be a place you can see, one you can visualize, or one you can describe by stating distance and direction, such as “200 ft straight downward” or “300 ft upward to the northwest at a 45-degree angle.”\nYou can also teleport one willing creature. The creature must be within 5 ft of you when you teleport, and it teleports to a space within 5 ft of your destination space.\nIf you, the other creature, or both would arrive in a space occupied by a creature or completely filled by one or more objects, you and any creature traveling with you each take 4d6 Force damage, and the teleportation fails.","effect":{"dice":"4d6","type":"force","text":"Teleport up to 500 ft (with one ally)"},"componentsShort":"V"},{"id":"disguise-self","name":"Disguise Self","level":1,"school":"Illusion","classes":["bard","sorcerer","wizard"],"time":"Action","range":"Self","components":"V, S","duration":"1 hour","concentration":false,"text":"You make yourself—including your clothing, armor, weapons, and other belongings on your person— look different until the spell ends. You can seem 1 ft shorter or taller and can appear heavier or lighter. You must adopt a form that has the same basic arrangement of limbs as you have. Otherwise, the extent of the illusion is up to you. The changes wrought by this spell fail to hold up to physical inspection. For example, if you use this spell to add a hat to your outfit, objects pass through the hat, and anyone who touches it would feel nothing.\nTo discern that you are disguised, a creature must take the Study action to inspect your appearance and succeed on an Intelligence (Investigation) check against your spell save DC.","componentsShort":"V, S","effect":{"text":"Change your appearance"}},{"id":"disintegrate","name":"Disintegrate","level":6,"school":"Transmutation","classes":["sorcerer","wizard"],"time":"Action","range":"60 ft","components":"V, S, M (a lodestone and dust)","duration":"Instantaneous","concentration":false,"text":"You launch a green ray at a target you can see within range. The target can be a creature, a nonmagical object, or a creation of magical force, such as the wall created by Wall of Force.\nA creature targeted by this spell makes a Dexterity saving throw. On a failed save, the target takes 10d6 + 40 Force damage. If this damage reduces it to 0 Hit Points, it and everything nonmagical it is wearing and carrying are disintegrated into gray dust. The target can be revived only by a True Resurrection or a Wish spell.\nThis spell automatically disintegrates a Large or smaller nonmagical object or a creation of magical force. If such a target is Huge or larger, this spell disintegrates a 10-ft-Cube portion of it.\nUsing a Higher-Level Spell Slot. The damage increases by 3d6 for each spell slot level above 6.","save":"dex","effect":{"dice":"10d6","type":"force","text":"10d6 + 40 force; dust at 0 HP","addMod":false},"higher":"The damage increases by 3d6 for each spell slot level above 6.","upcast":{"dice":"3d6"},"componentsShort":"V, S, M"},{"id":"dispel-evil-and-good","name":"Dispel Evil and Good","level":5,"school":"Abjuration","classes":["cleric","paladin"],"time":"Action","range":"Self","components":"V, S, M (powdered silver and iron)","duration":"Up to 1 minute","concentration":true,"text":"For the duration, Celestials, Elementals, Fey, Fiends, and Undead have Disadvantage on attack rolls against you. You can end the spell early by using either of the following special functions.\nBreak Enchantment. As a Magic action, you touch a creature that is possessed by or has the Charmed or Frightened condition from one or more creatures of the types above. The target is no longer possessed, Charmed, or Frightened by such creatures.\nDismissal. As a Magic action, you target one creature you can see within 5 ft of you that has one of the creature types above. The target must succeed on a Charisma saving throw or be sent back to its home plane if it isn’t there already. If they aren’t on their home plane, Undead are sent to the Shadowfell, and Fey are sent to the Feywild.","concDuration":"1 min","save":"cha","componentsShort":"V, S, M","effect":{"text":"For the duration, Celestials, Elementals, Fey, Fiends, and…"}},{"id":"dispel-magic","name":"Dispel Magic","level":3,"school":"Abjuration","classes":["bard","cleric","druid","paladin","ranger","sorcerer","warlock","wizard"],"time":"Action","range":"120 ft","components":"V, S","duration":"Instantaneous","concentration":false,"text":"Choose one creature, object, or magical effect within range. Any ongoing spell of level 3 or lower on the target ends. For each ongoing spell of level 4 or higher on the target, make an ability check using your spellcasting ability (DC 10 plus that spell’s level). On a successful check, the spell ends.\nUsing a Higher-Level Spell Slot. You automatically end a spell on the target if the spell’s level is equal to or less than the level of the spell slot you use.","higher":"You automatically end a spell on the target if the spell’s level is equal to or less than the level of the spell slot you use.","componentsShort":"V, S","effect":{"text":"End spells of 3rd level or lower"}},{"id":"dissonant-whispers","name":"Dissonant Whispers","level":1,"school":"Enchantment","classes":["bard"],"time":"Action","range":"60 ft","components":"V","duration":"Instantaneous","concentration":false,"text":"One creature of your choice that you can see within range hears a discordant melody in its mind. The target makes a Wisdom saving throw. On a failed save, it takes 3d6 Psychic damage and must immediately use its Reaction, if available, to move as far away from you as it can, using the safest route. On a successful save, the target takes half as much damage only.\nUsing a Higher-Level Spell Slot. The damage increases by 1d6 for each spell slot level above 1.","save":"wis","effect":{"dice":"3d6","type":"psychic"},"higher":"The damage increases by 1d6 for each spell slot level above 1.","upcast":{"dice":"1d6"},"componentsShort":"V"},{"id":"divination","name":"Divination","level":4,"school":"Divination","classes":["cleric","druid","wizard"],"time":"Action","range":"Self","components":"V, S, M (incense worth 25+ GP, which the spell consumes)","duration":"Instantaneous","concentration":false,"text":"This spell puts you in contact with a god or a god’s servants. You ask one question about a specific goal, event, or activity to occur within 7 days. The GM offers a truthful reply, which might be a short phrase or cryptic rhyme. The spell doesn’t account for circumstances that might change the answer, such as the casting of other spells.\nIf you cast the spell more than once before finishing a Long Rest, there is a cumulative 25 percent chance for each casting after the first that you get no answer.","ritual":true,"componentsShort":"V, S, M","effect":{"text":"This spell puts you in contact with a god or a god’s servants"}},{"id":"divine-favor","name":"Divine Favor","level":1,"school":"Transmutation","classes":["paladin"],"time":"Bonus Action","range":"Self","components":"V, S","duration":"1 minute","concentration":false,"text":"Until the spell ends, your attacks with weapons deal an extra 1d4 Radiant damage on a hit.","effect":{"dice":"1d4","type":"radiant"},"componentsShort":"V, S"},{"id":"divine-smite","name":"Divine Smite","level":1,"school":"Evocation","classes":["paladin"],"time":"Bonus Action","range":"Self","components":"V","duration":"Instantaneous","concentration":false,"text":"The target takes an extra 2d8 Radiant damage from the attack. The damage increases by 1d8 if the target is a Fiend or an Undead.\nUsing a Higher-Level Spell Slot. The damage increases by 1d8 for each spell slot level above 1.","trigger":"immediately after hitting a target with a Melee weapon or an Unarmed Strike","effect":{"dice":"2d8","type":"radiant"},"higher":"The damage increases by 1d8 for each spell slot level above 1.","upcast":{"dice":"1d8"},"componentsShort":"V"},{"id":"divine-word","name":"Divine Word","level":7,"school":"Evocation","classes":["cleric"],"time":"Bonus Action","range":"30 ft","components":"V","duration":"Instantaneous","concentration":false,"text":"You utter a word imbued with power from the Upper Planes. Each creature of your choice in range makes a Charisma saving throw. On a failed save, a target that has 50 Hit Points or fewer suffers an effect based on its current Hit Points, as shown in the Divine Word Effects table. Regardless of its Hit Points, a Celestial, an Elemental, a Fey, or a Fiend target that fails its save is forced back to its plane of origin (if it isn’t there already) and can’t return to the current plane for 24 hours by any means short of a Wish spell.\nDivine Word Effects Hit Points Effect 0–20\nThe target dies.\n21–30\nThe target has the Blinded, Deafened, and Stunned conditions for 1 hour.\n31–40\nThe target has the Blinded and Deafened conditions for 10 minutes.\n41–50\nThe target has the Deafened condition for 1 minute.","save":"cha","componentsShort":"V","effect":{"text":"Utter a word imbued with power from the Upper Planes"}},{"id":"dominate-beast","name":"Dominate Beast","level":4,"school":"Enchantment","classes":["druid","ranger","sorcerer"],"time":"Action","range":"60 ft","components":"V, S","duration":"Up to 1 minute","concentration":true,"text":"One Beast you can see within range must succeed on a Wisdom saving throw or have the Charmed condition for the duration. The target has Advantage on the save if you or your allies are fighting it. Whenever the target takes damage, it repeats the save, ending the spell on itself on a success.\nYou have a telepathic link with the Charmed target while the two of you are on the same plane of existence. On your turn, you can use this link to issue commands to the target (no action required), such as “Attack that creature,” “Move over there,” or “Fetch that object.” The target does its best to obey on its turn. If it completes an order and doesn’t receive further direction from you, it acts and moves as it likes, focusing on protecting itself.\nYou can command the target to take a Reaction but must take your own Reaction to do so.\nUsing a Higher-Level Spell Slot. Your Concentration can last longer with a spell slot of level 5 (up to 10 minutes), 6 (up to 1 hour), or 7+ (up to 8 hours).","concDuration":"1 min","save":"wis","higher":"Your Concentration can last longer with a spell slot of level 5 (up to 10 minutes), 6 (up to 1 hour), or 7+ (up to 8 hours).","componentsShort":"V, S","effect":{"text":"One Beast you can see within range must succeed on a Wisdom…"}},{"id":"dominate-monster","name":"Dominate Monster","level":8,"school":"Enchantment","classes":["bard","sorcerer","warlock","wizard"],"time":"Action","range":"60 ft","components":"V, S","duration":"Up to 1 hour","concentration":true,"text":"One creature you can see within range must succeed on a Wisdom saving throw or have the Charmed condition for the duration. The target has Advantage on the save if you or your allies are fighting it. Whenever the target takes damage, it repeats the save, ending the spell on itself on a success.\nYou have a telepathic link with the Charmed target while the two of you are on the same plane of existence. On your turn, you can use this link to issue commands to the target (no action required), such as “Attack that creature,” “Move over there,” or “Fetch that object.” The target does its best to obey on its turn. If it completes an order and doesn’t receive further direction from you, it acts and moves as it likes, focusing on protecting itself.\nYou can command the target to take a Reaction but must take your own Reaction to do so.\nUsing a Higher-Level Spell Slot. Your Concentration can last longer with a level 9 spell slot (up to 8 hours).","concDuration":"1 hour","save":"wis","higher":"Your Concentration can last longer with a level 9 spell slot (up to 8 hours).","componentsShort":"V, S","effect":{"text":"Control any creature"}},{"id":"dominate-person","name":"Dominate Person","level":5,"school":"Enchantment","classes":["bard","sorcerer","wizard"],"time":"Action","range":"60 ft","components":"V, S","duration":"Up to 1 minute","concentration":true,"text":"One Humanoid you can see within range must succeed on a Wisdom saving throw or have the Charmed condition for the duration. The target has Advantage on the save if you or your allies are fighting it. Whenever the target takes damage, it repeats the save, ending the spell on itself on a success.\nYou have a telepathic link with the Charmed target while the two of you are on the same plane of existence. On your turn, you can use this link to issue commands to the target (no action required), such as “Attack that creature,” “Move over there,” or “Fetch that object.” The target does its best to obey on its turn. If it completes an order and doesn’t receive further direction from you, it acts and moves as it likes, focusing on protecting itself.\nYou can command the target to take a Reaction but must take your own Reaction to do so.\nUsing a Higher-Level Spell Slot. Your Concentration can last longer with a spell slot of level 6 (up to 10 minutes), 7 (up to 1 hour), or 8+ (up to 8 hours).","concDuration":"1 min","save":"wis","higher":"Your Concentration can last longer with a spell slot of level 6 (up to 10 minutes), 7 (up to 1 hour), or 8+ (up to 8 hours).","componentsShort":"V, S","effect":{"text":"One Humanoid you can see within range must succeed on a…"}},{"id":"dragons-breath","name":"Dragon’s Breath","level":2,"school":"Transmutation","classes":["sorcerer","wizard"],"time":"Bonus Action","range":"Touch","components":"V, S, M (a hot pepper)","duration":"Up to 1 minute","concentration":true,"text":"You touch one willing creature, and choose Acid, Cold, Fire, Lightning, or Poison. Until the spell ends, the target can take a Magic action to exhale a 15-ft Cone. Each creature in that area makes a Dexterity saving throw, taking 3d6 damage of the chosen type on a failed save or half as much damage on a successful one.\nUsing a Higher-Level Spell Slot. The damage increases by 1d6 for each spell slot level above 2.","concDuration":"1 min","save":"dex","higher":"The damage increases by 1d6 for each spell slot level above 2.","componentsShort":"V, S, M","effect":{"dice":"3d6","type":"acid, cold, fire, lightning or poison"}},{"id":"dream","name":"Dream","level":5,"school":"Illusion","classes":["bard","warlock","wizard"],"time":"1 minute","range":"Special","components":"V, S, M (a handful of sand)","duration":"8 hours","concentration":false,"text":"You target a creature you know on the same plane of existence. You or a willing creature you touch enters a trance state to act as a dream messenger.\nWhile in the trance, the messenger is Incapacitated and has a Speed of 0.\nIf the target is asleep, the messenger appears in the target’s dreams and can converse with the target as long as it remains asleep, through the spell’s duration. The messenger can also shape the dream’s environment, creating landscapes, objects, and other images. The messenger can emerge from the trance at any time, ending the spell. The target recalls the dream perfectly upon waking.\nIf the target is awake when you cast the spell, the messenger knows it and can either end the trance (and the spell) or wait for the target to sleep, at which point the messenger enters its dreams.\nYou can make the messenger terrifying to the target. If you do so, the messenger can deliver a message of no more than ten words, and then the target makes a Wisdom saving throw. On a failed save, the target gains no benefit from its rest, and it takes 3d6 Psychic damage when it wakes up.","save":"wis","effect":{"dice":"3d6","type":"psychic"},"componentsShort":"V, S, M"},{"id":"druidcraft","name":"Druidcraft","level":0,"school":"Transmutation","classes":["druid"],"time":"Action","range":"30 ft","components":"V, S","duration":"Instantaneous","concentration":false,"text":"Whispering to the spirits of nature, you create one of the following effects within range.\nWeather Sensor. You create a Tiny, harmless sensory effect that predicts what the weather will be at your location for the next 24 hours. The effect might manifest as a golden orb for clear skies, a cloud for rain, falling snowflakes for snow, and so on. This effect persists for 1 round.\nBloom. You instantly make a flower blossom, a seed pod open, or a leaf bud bloom.\nSensory Effect. You create a harmless sensory effect, such as falling leaves, spectral dancing fairies, a gentle breeze, the sound of an animal, or the faint odor of skunk. The effect must fit in a 5-ft Cube.\nFire Play. You light or snuff out a candle, a torch, or a campfire.","componentsShort":"V, S","effect":{"text":"Minor nature effect"}},{"id":"earthquake","name":"Earthquake","level":8,"school":"Transmutation","classes":["cleric","druid","sorcerer"],"time":"Action","range":"500 ft","components":"V, S, M (a fractured rock)","duration":"Up to 1 minute","concentration":true,"text":"Choose a point on the ground that you can see within range. For the duration, an intense tremor rips through the ground in a 100-ft-radius circle centered on that point. The ground there is Difficult Terrain.\nWhen you cast this spell and at the end of each of your turns for the duration, each creature on the ground in the area makes a Dexterity saving throw.\nOn a failed save, a creature has the Prone condition, and its Concentration is broken.\nYou can also cause the effects below.\nFissures. A total of 1d6 fissures open in the spell’s area at the end of the turn you cast it. You choose the fissures’ locations, which can’t be under structures. Each fissure is 1d10 × 10 ft deep and 10 ft wide, and it extends from one edge of the spell’s area to another edge. A creature in the same space as a fissure must succeed on a Dexterity saving throw or fall in. A creature that successfully saves moves with the fissure’s edge as it opens.\nStructures. The tremor deals 50 Bludgeoning damage to any structure in contact with the ground in the area when you cast the spell and at the end of each of your turns until the spell ends. If a structure drops to 0 Hit Points, it collapses.\nA creature within a distance from a collapsing structure equal to half the structure’s height makes a Dexterity saving throw. On a failed save, the creature takes 12d6 Bludgeoning damage, has the Prone condition, and is buried in the rubble, requiring a DC 20 Strength (Athletics) check as an action to escape. On a successful save, the creature takes half as much damage only.","concDuration":"1 min","save":"dex","effect":{"dice":"12d6","type":"bludgeoning","text":"Fissures, collapsing structures, Prone"},"componentsShort":"V, S, M"},{"id":"eldritch-blast","name":"Eldritch Blast","level":0,"school":"Evocation","classes":["warlock"],"time":"Action","range":"120 ft","components":"V, S","duration":"Instantaneous","concentration":false,"text":"You hurl a beam of crackling energy. Make a ranged spell attack against one creature or object in range. On a hit, the target takes 1d10 Force damage.\nCantrip Upgrade. The spell creates two beams at level 5, three beams at level 11, and four beams at level 17. You can direct the beams at the same target or at different ones. Make a separate attack roll for each beam.","attack":"ranged","effect":{"dice":"1d10","type":"force"},"componentsShort":"V, S"},{"id":"elementalism","name":"Elementalism","level":0,"school":"Transmutation","classes":["druid","sorcerer","wizard"],"time":"Action","range":"30 ft","components":"V, S","duration":"Instantaneous","concentration":false,"text":"You exert control over the elements, creating one of the following effects within range.\nBeckon Air. You create a breeze strong enough to ripple cloth, stir dust, rustle leaves, and close open doors and shutters, all in a 5-ft Cube. Doors and shutters being held open by someone or something aren’t affected.\nBeckon Earth. You create a thin shroud of dust or sand that covers surfaces in a 5-ft-square area, or you cause a single word to appear in your handwriting in a patch of dirt or sand.\nBeckon Fire. You create a thin cloud of harmless embers and colored, scented smoke in a 5-ft Cube.\nYou choose the color and scent, and the embers can light candles, torches, or lamps in that area. The smoke’s scent lingers for 1 minute.\nBeckon Water. You create a spray of cool mist that lightly dampens creatures and objects in a 5-ft Cube. Alternatively, you create 1 cup of clean water either in an open container or on a surface, and the water evaporates in 1 minute.\nSculpt Element. You cause dirt, sand, fire, smoke, mist, or water that can fit in a 1-ft Cube to assume a crude shape (such as that of a creature) for 1 hour.","componentsShort":"V, S","effect":{"text":"Exert control over the elements, creating one of the…"}},{"id":"enhance-ability","name":"Enhance Ability","level":2,"school":"Transmutation","classes":["bard","cleric","druid","ranger","sorcerer","wizard"],"time":"Action","range":"Touch","components":"V, S, M (fur or a feather)","duration":"Up to 1 hour","concentration":true,"text":"You touch a creature and choose Strength, Dexterity, Intelligence, Wisdom, or Charisma. For the duration, the target has Advantage on ability checks using the chosen ability.\nUsing a Higher-Level Spell Slot. You can target one additional creature for each spell slot level above 2. You can choose a different ability for each target.","concDuration":"1 hour","higher":"You can target one additional creature for each spell slot level above 2. You can choose a different ability for each target.","componentsShort":"V, S, M","effect":{"text":"Advantage on checks with one ability"}},{"id":"enlarge-reduce","name":"Enlarge/Reduce","level":2,"school":"Transmutation","classes":["bard","druid","sorcerer","wizard"],"time":"Action","range":"30 ft","components":"V, S, M (a pinch of powdered iron)","duration":"Up to 1 minute","concentration":true,"text":"For the duration, the spell enlarges or reduces a creature or an object you can see within range (see the chosen effect below). A targeted object must be neither worn nor carried. If the target is an unwilling creature, it can make a Constitution saving throw. On a successful save, the spell has no effect.\nEverything that a targeted creature is wearing and carrying changes size with it. Any item it drops returns to normal size at once. A thrown weapon or piece of ammunition returns to normal size immediately after it hits or misses a target.\nEnlarge. The target’s size increases by one category—from Medium to Large, for example. The target also has Advantage on Strength checks and Strength saving throws. The target’s attacks with its enlarged weapons or Unarmed Strikes deal an extra 1d4 damage on a hit.\nReduce. The target’s size decreases by one category—from Medium to Small, for example. The target also has Disadvantage on Strength checks and Strength saving throws. The target’s attacks with its reduced weapons or Unarmed Strikes deal 1d4 less damage on a hit (this can’t reduce the damage below 1).","concDuration":"1 min","save":"con","componentsShort":"V, S, M","effect":{"text":"For the duration, the spell enlarges or reduces a creature or…"}},{"id":"ensnaring-strike","name":"Ensnaring Strike","level":1,"school":"Conjuration","classes":["ranger"],"time":"Bonus Action","range":"Self","components":"V","duration":"Up to 1 minute","concentration":true,"text":"As you hit the target, grasping vines appear on it, and it makes a Strength saving throw. A Large or larger creature has Advantage on this save. On a failed save, the target has the Restrained condition until the spell ends. On a successful save, the vines shrivel away, and the spell ends.\nWhile Restrained, the target takes 1d6 Piercing damage at the start of each of its turns. The target or a creature within reach of it can take an action to make a Strength (Athletics) check against your spell save DC. On a success, the spell ends.\nUsing a Higher-Level Spell Slot. The damage increases by 1d6 for each spell slot level above 1.","concDuration":"1 min","trigger":"immediately after hitting a creature with a weapon","save":"str","effect":{"dice":"1d6","type":"piercing","text":"Restrained · 1d6 piercing per turn"},"higher":"The damage increases by 1d6 for each spell slot level above 1.","upcast":{"dice":"1d6"},"componentsShort":"V"},{"id":"entangle","name":"Entangle","level":1,"school":"Conjuration","classes":["druid","ranger"],"time":"Action","range":"90 ft","components":"V, S","duration":"Up to 1 minute","concentration":true,"text":"Grasping plants sprout from the ground in a 20-ft square within range. For the duration, these plants turn the ground in the area into Difficult Terrain. They disappear when the spell ends.\nEach creature (other than you) in the area when you cast the spell must succeed on a Strength saving throw or have the Restrained condition until the spell ends. A Restrained creature can take an action to make a Strength (Athletics) check against your spell save DC. On a success, it frees itself from the grasping plants and is no longer Restrained by them.","concDuration":"1 min","save":"str","componentsShort":"V, S","effect":{"text":"Restrained in a 20-ft square"}},{"id":"enthrall","name":"Enthrall","level":2,"school":"Enchantment","classes":["bard","warlock"],"time":"Action","range":"60 ft","components":"V, S","duration":"Up to 1 minute","concentration":true,"text":"You weave a distracting string of words, causing creatures of your choice that you can see within range to make a Wisdom saving throw. Any creature you or your companions are fighting automatically succeeds on this save. On a failed save, a target has a −10 penalty to Wisdom (Perception) checks and Passive Perception until the spell ends.","concDuration":"1 min","save":"wis","componentsShort":"V, S","effect":{"text":"Weave a distracting string of words, causing creatures of…"}},{"id":"etherealness","name":"Etherealness","level":7,"school":"Conjuration","classes":["bard","cleric","sorcerer","warlock","wizard"],"time":"Action","range":"Self","components":"V, S","duration":"Up to 8 hours","concentration":false,"text":"You step into the border regions of the Ethereal Plane, where it overlaps with your current plane. You remain in the Border Ethereal for the duration. During this time, you can move in any direction. If you move up or down, every foot of movement costs an extra foot. You can perceive the plane you left, which looks gray, and you can’t see anything there more than 60 ft away.\nWhile on the Ethereal Plane, you can affect and be affected only by creatures, objects, and effects on that plane. Creatures that aren’t on the Ethereal Plane can’t perceive or interact with you unless a feature gives them the ability to do so.\nWhen the spell ends, you return to the plane you left in the spot that corresponds to your space in the Border Ethereal. If you appear in an occupied space, you are shunted to the nearest unoccupied space and take Force damage equal to twice the number of feet you are moved.\nThis spell ends instantly if you cast it while you are on the Ethereal Plane or a plane that doesn’t border it, such as one of the Outer Planes.\nUsing a Higher-Level Spell Slot. You can target up to three willing creatures (including yourself) for each spell slot level above 7. The creatures must be within 10 ft of you when you cast the spell.","higher":"You can target up to three willing creatures (including yourself) for each spell slot level above 7. The creatures must be within 10 ft of you when you cast the spell.","componentsShort":"V, S","effect":{"text":"Step into the Border Ethereal"}},{"id":"expeditious-retreat","name":"Expeditious Retreat","level":1,"school":"Transmutation","classes":["sorcerer","warlock","wizard"],"time":"Bonus Action","range":"Self","components":"V, S","duration":"Up to 10 minutes","concentration":true,"text":"You take the Dash action, and until the spell ends, you can take that action again as a Bonus Action.","concDuration":"10 min","componentsShort":"V, S","effect":{"text":"Take the Dash action, and until the spell ends, you can take…"}},{"id":"eyebite","name":"Eyebite","level":6,"school":"Necromancy","classes":["bard","sorcerer","warlock","wizard"],"time":"Action","range":"Self","components":"V, S","duration":"Up to 1 minute","concentration":true,"text":"For the duration, your eyes become an inky void.\nOne creature of your choice within 60 ft of you that you can see must succeed on a Wisdom saving throw or be affected by one of the following effects of your choice for the duration.\nOn each of your turns until the spell ends, you can take a Magic action to target another creature but can’t target a creature again if it has succeeded on a save against this casting of the spell.\nAsleep. The target has the Unconscious condition.\nIt wakes up if it takes any damage or if another creature takes an action to shake it awake.\nPanicked. The target has the Frightened condition. On each of its turns, the Frightened target must take the Dash action and move away from you by the safest and shortest route available. If the target moves to a space at least 60 ft away from you where it can’t see you, this effect ends.\nSickened. The target has the Poisoned condition.","concDuration":"1 min","save":"wis","componentsShort":"V, S","effect":{"text":"Asleep, Panicked or Sickened each turn"}},{"id":"fabricate","name":"Fabricate","level":4,"school":"Transmutation","classes":["wizard"],"time":"10 minutes","range":"120 ft","components":"V, S","duration":"Instantaneous","concentration":false,"text":"You convert raw materials into products of the same material. For example, you can fabricate a wooden bridge from a clump of trees, a rope from a patch of hemp, or clothes from flax or wool.\nChoose raw materials that you can see within range. You can fabricate a Large or smaller object (contained within a 10-ft Cube or eight connected 5-ft Cubes) given a sufficient quantity of material. If you’re working with metal, stone, or another mineral substance, however, the fabricated object can be no larger than Medium (contained within a 5-ft Cube). The quality of any fabricated objects is based on the quality of the raw materials.\nCreatures and magic items can’t be created by this spell. You also can’t use it to create items that require a high degree of skill—such as weapons and armor—unless you have proficiency with the type of Artisan’s Tools used to craft such objects.","componentsShort":"V, S","effect":{"text":"Convert raw materials into products of the same material"}},{"id":"faerie-fire","name":"Faerie Fire","level":1,"school":"Evocation","classes":["bard","druid"],"time":"Action","range":"60 ft","components":"V","duration":"Up to 1 minute","concentration":true,"text":"Objects in a 20-ft Cube within range are outlined in blue, green, or violet light (your choice). Each creature in the Cube is also outlined if it fails a Dexterity saving throw. For the duration, objects and affected creatures shed Dim Light in a 10-ft radius and can’t benefit from the Invisible condition. Attack rolls against an affected creature or object have Advantage if the attacker can see it.","concDuration":"1 min","save":"dex","componentsShort":"V","effect":{"text":"Outlined: attacks against it have Advantage"}},{"id":"faithful-hound","name":"Faithful Hound","level":4,"school":"Conjuration","classes":["wizard"],"time":"Action","range":"30 ft","components":"V, S, M (a silver whistle)","duration":"8 hours","concentration":false,"text":"You conjure a phantom watchdog in an unoccupied space that you can see within range. The hound remains for the duration or until the two of you are more than 300 ft apart from each other.\nNo one but you can see the hound, and it is intangible and invulnerable. When a Small or larger creature comes within 30 ft of it without first speaking the password that you specify when you cast this spell, the hound starts barking loudly. The hound has Truesight with a range of 30 ft.\nAt the start of each of your turns, the hound attempts to bite one enemy within 5 ft of it. That enemy must succeed on a Dexterity saving throw or take 4d8 Force damage.\nOn your later turns, you can take a Magic action to move the hound up to 30 ft.","save":"dex","effect":{"dice":"4d8","type":"force"},"componentsShort":"V, S, M"},{"id":"false-life","name":"False Life","level":1,"school":"Necromancy","classes":["sorcerer","wizard"],"time":"Action","range":"Self","components":"V, S, M (a drop of alcohol)","duration":"Instantaneous","concentration":false,"text":"You gain 2d4 + 4 Temporary Hit Points.\nUsing a Higher-Level Spell Slot. You gain 5 additional Temporary Hit Points for each spell slot level above 1.","higher":"You gain 5 additional Temporary Hit Points for each spell slot level above 1.","componentsShort":"V, S, M","effect":{"text":"Gain 2d4 + 4 Temporary Hit Points"}},{"id":"fear","name":"Fear","level":3,"school":"Illusion","classes":["bard","sorcerer","warlock","wizard"],"time":"Action","range":"Self","components":"V, S, M (a white feather)","duration":"Up to 1 minute","concentration":true,"text":"Each creature in a 30-ft Cone must succeed on a Wisdom saving throw or drop whatever it is holding and have the Frightened condition for the duration.\nA Frightened creature takes the Dash action and moves away from you by the safest route on each of its turns unless there is nowhere to move. If the creature ends its turn in a space where it doesn’t have line of sight to you, the creature makes a Wisdom saving throw. On a successful save, the spell ends on that creature.","concDuration":"1 min","save":"wis","componentsShort":"V, S, M","effect":{"text":"Frightened; drops what it holds and flees"}},{"id":"feather-fall","name":"Feather Fall","level":1,"school":"Transmutation","classes":["bard","sorcerer","wizard"],"time":"Reaction","range":"60 ft","components":"V, M (a small feather or piece of down)","duration":"1 minute","concentration":false,"text":"Choose up to five falling creatures within range. A falling creature’s rate of descent slows to 60 ft per round until the spell ends. If a creature lands before the spell ends, the creature takes no damage from the fall, and the spell ends for that creature.","trigger":"when you or a creature you can see within 60 ft of you falls","componentsShort":"V, M","effect":{"text":"Up to 5 falling creatures slow down"}},{"id":"find-familiar","name":"Find Familiar","level":1,"school":"Conjuration","classes":["wizard"],"time":"1 hour","range":"10 ft","components":"V, S, M (burning incense worth 10+ GP, which the spell consumes)","duration":"Instantaneous","concentration":false,"text":"You gain the service of a familiar, a spirit that takes an animal form you choose: Bat, Cat, Frog, Hawk, Lizard, Octopus, Owl, Rat, Raven, Spider, Weasel, or another Beast that has a Challenge Rating of 0.\nAppearing in an unoccupied space within range, the familiar has the statistics of the chosen form (see “Monsters”), though it is a Celestial, Fey, or Fiend (your choice) instead of a Beast. Your familiar acts independently of you, but it obeys your commands.\nTelepathic Connection. While your familiar is within 100 ft of you, you can communicate with it telepathically. Additionally, as a Bonus Action, you can see through the familiar’s eyes and hear what it hears until the start of your next turn, gaining the benefits of any special senses it has.\nFinally, when you cast a spell with a range of touch, your familiar can deliver the touch. Your familiar must be within 100 ft of you, and it must take a Reaction to deliver the touch when you cast the spell.\nCombat. The familiar is an ally to you and your allies. It rolls its own Initiative and acts on its own turn. A familiar can’t attack, but it can take other actions as normal.\nDisappearance of the Familiar. When the familiar drops to 0 Hit Points, it disappears. It reappears after you cast this spell again. As a Magic action, you can temporarily dismiss the familiar to a pocket dimension. Alternatively, you can dismiss it forever.\nAs a Magic action while it is temporarily dismissed, you can cause it to reappear in an unoccupied space within 30 ft of you. Whenever the familiar drops to 0 Hit Points or disappears into the pocket dimension, it leaves behind in its space anything it was wearing or carrying.\nOne Familiar Only. You can’t have more than one familiar at a time. If you cast this spell while you have a familiar, you instead cause it to adopt a new eligible form.","ritual":true,"componentsShort":"V, S, M","effect":{"text":"A spirit animal companion"}},{"id":"find-steed","name":"Find Steed","level":2,"school":"Conjuration","classes":["paladin"],"time":"Action","range":"30 ft","components":"V, S","duration":"Instantaneous","concentration":false,"text":"You summon an otherworldly being that appears as a loyal steed in an unoccupied space of your choice within range. This creature uses the Otherworldly Steed stat block. If you already have a steed from this spell, the steed is replaced by the new one.\nThe steed resembles a Large, rideable animal of your choice, such as a horse, a camel, a dire wolf, or an elk. Whenever you cast the spell, choose the steed’s creature type—Celestial, Fey, or Fiend— which determines certain traits in the stat block.\nCombat. The steed is an ally to you and your allies. In combat, it shares your Initiative count, and it functions as a controlled mount while you ride it (as defined in the rules on mounted combat). If you have the Incapacitated condition, the steed takes its turn immediately after yours and acts independently, focusing on protecting you.\nDisappearance of the Steed. The steed disappears if it drops to 0 Hit Points or if you die. When it disappears, it leaves behind anything it was wearing or carrying. If you cast this spell again, you decide whether you summon the steed that disappeared or a different one.\nUsing a Higher-Level Spell Slot. Use the spell slot’s level for the spell’s level in the stat block.\nOtherworldly Steed Large Celestial, Fey, or Fiend (Your Choice), Neutral AC 10 + 1 per spell level HP 5 + 10 per spell level (the steed has a number of Hit Dice [d10s] equal to the spell’s level) Speed 60 ft., Fly 60 ft. (requires level 4+ spell) MOD SAVE\nMOD SAVE\nMOD SAVE\nStr 18 +4 +4 Int 6 −2 −2\nDex 12 +1 +1 Wis 12 +1 +1\nCon 14 +2 +2 Cha 8 −1 −1\nSenses Passive Perception 11 Languages Telepathy 1 mile (works only with you) CR None (XP 0; PB equals your Proficiency Bonus)\nTraits Life Bond. When you regain Hit Points from a level 1+ spell, the steed regains the same number of Hit Points if you’re within 5 ft of it.\nActions Otherworldly Slam. Melee Attack Roll: Bonus equals your spell attack modifier, reach 5 ft. Hit: 1d8 plus the spell’s level of Radiant (Celestial), Psychic (Fey), or Necrotic (Fiend) damage.\nBonus Actions Fell Glare (Fiend Only; Recharges after a Long Rest).\nWisdom Saving Throw: DC equals your spell save DC, one creature within 60 ft the steed can see. Failure:\nThe target has the Frightened condition until the end of your next turn.\nFey Step (Fey Only; Recharges after a Long Rest). The steed teleports, along with its rider, to an unoccupied space of your choice up to 60 ft away from itself.\nHealing Touch (Celestial Only; Recharges after a Long Rest). One creature within 5 ft of the steed regains a number of Hit Points equal to 2d8 plus the spell’s level.","higher":"Use the spell slot’s level for the spell’s level in the stat block.","componentsShort":"V, S","effect":{"text":"Summon an otherworldly steed"}},{"id":"find-the-path","name":"Find the Path","level":6,"school":"Divination","classes":["bard","cleric","druid"],"time":"1 minute","range":"Self","components":"V, S, M (a set of divination tools—such as cards or runes—worth 100+ GP)","duration":"Up to 1 day","concentration":true,"text":"You magically sense the most direct physical route to a location you name. You must be familiar with the location, and the spell fails if you name a destination on another plane of existence, a moving destination (such as a mobile fortress), or an unspecific destination (such as “a green dragon’s lair”).\nFor the duration, as long as you are on the same plane of existence as the destination, you know how far it is and in what direction it lies. Whenever you face a choice of paths along the way there, you know which path is the most direct.","concDuration":"1 day","componentsShort":"V, S, M","effect":{"text":"Sense the most direct physical route to a location you name"}},{"id":"find-traps","name":"Find Traps","level":2,"school":"Divination","classes":["cleric","druid","ranger"],"time":"Action","range":"120 ft","components":"V, S","duration":"Instantaneous","concentration":false,"text":"You sense any trap within range that is within line of sight. A trap, for the purpose of this spell, includes any object or mechanism that was created to cause damage or other danger. Thus, the spell would sense the Alarm or Glyph of Warding spell or a mechanical pit trap, but it wouldn’t reveal a natural weakness in the floor, an unstable ceiling, or a hidden sinkhole.\nThis spell reveals that a trap is present but not its location. You do learn the general nature of the danger posed by a trap you sense.","componentsShort":"V, S","effect":{"text":"Sense any trap within range that is within line of sight"}},{"id":"finger-of-death","name":"Finger of Death","level":7,"school":"Necromancy","classes":["sorcerer","warlock","wizard"],"time":"Action","range":"60 ft","components":"V, S","duration":"Instantaneous","concentration":false,"text":"You unleash negative energy toward a creature you can see within range. The target makes a Constitution saving throw, taking 7d8 + 30 Necrotic damage on a failed save or half as much damage on a successful one.\nA Humanoid killed by this spell rises at the start of your next turn as a Zombie (see “Monsters”) that follows your verbal orders.","save":"con","effect":{"dice":"7d8","type":"necrotic","text":"7d8 + 30 necrotic; rises as a zombie","addMod":false},"componentsShort":"V, S"},{"id":"fireball","name":"Fireball","level":3,"school":"Evocation","classes":["sorcerer","wizard"],"time":"Action","range":"150 ft","components":"V, S, M (a ball of bat guano and sulfur)","duration":"Instantaneous","concentration":false,"text":"A bright streak flashes from you to a point you choose within range and then blossoms with a low roar into a fiery explosion. Each creature in a 20-ft-radius Sphere centered on that point makes a Dexterity saving throw, taking 8d6 Fire damage on a failed save or half as much damage on a successful one.\nFlammable objects in the area that aren’t being worn or carried start burning.\nUsing a Higher-Level Spell Slot. The damage increases by 1d6 for each spell slot level above 3.","save":"dex","effect":{"dice":"8d6","type":"fire"},"higher":"The damage increases by 1d6 for each spell slot level above 3.","upcast":{"dice":"1d6"},"componentsShort":"V, S, M"},{"id":"fire-bolt","name":"Fire Bolt","level":0,"school":"Evocation","classes":["sorcerer","wizard"],"time":"Action","range":"120 ft","components":"V, S","duration":"Instantaneous","concentration":false,"text":"You hurl a mote of fire at a creature or an object within range. Make a ranged spell attack against the target. On a hit, the target takes 1d10 Fire damage. A flammable object hit by this spell starts burning if it isn’t being worn or carried.\nCantrip Upgrade. The damage increases by 1d10 when you reach levels 5 (2d10), 11 (3d10), and 17 (4d10).","attack":"ranged","effect":{"dice":"1d10","type":"fire"},"componentsShort":"V, S"},{"id":"fire-shield","name":"Fire Shield","level":4,"school":"Evocation","classes":["druid","sorcerer","wizard"],"time":"Action","range":"Self","components":"V, S, M (a bit of phosphorus or a firefly)","duration":"10 minutes","concentration":false,"text":"Wispy flames wreathe your body for the duration, shedding Bright Light in a 10-ft radius and Dim Light for an additional 10 ft.\nThe flames provide you with a warm shield or a chill shield, as you choose. The warm shield grants you Resistance to Cold damage, and the chill shield grants you Resistance to Fire damage.\nIn addition, whenever a creature within 5 ft of you hits you with a melee attack roll, the shield erupts with flame. The attacker takes 2d8 Fire damage from a warm shield or 2d8 Cold damage from a chill shield.","effect":{"dice":"2d8","type":"fire or cold","addMod":false,"text":"Resistance; attackers take 2d8"},"componentsShort":"V, S, M"},{"id":"fire-storm","name":"Fire Storm","level":7,"school":"Evocation","classes":["cleric","druid","sorcerer"],"time":"Action","range":"150 ft","components":"V, S","duration":"Instantaneous","concentration":false,"text":"A storm of fire appears within range. The area of the storm consists of up to ten 10-ft Cubes, which you arrange as you like. Each Cube must be contiguous with at least one other Cube. Each creature in the area makes a Dexterity saving throw, taking 7d10 Fire damage on a failed save or half as much damage on a successful one.\nFlammable objects in the area that aren’t being worn or carried start burning.","save":"dex","effect":{"dice":"7d10","type":"fire","addMod":false},"componentsShort":"V, S"},{"id":"flame-blade","name":"Flame Blade","level":2,"school":"Evocation","classes":["druid","sorcerer"],"time":"Bonus Action","range":"Self","components":"V, S, M (a sumac leaf)","duration":"Up to 10 minutes","concentration":true,"text":"You evoke a fiery blade in your free hand. The blade is similar in size and shape to a scimitar, and it lasts for the duration. If you let go of the blade, it disappears, but you can evoke it again as a Bonus Action. As a Magic action, you can make a melee spell attack with the fiery blade. On a hit, the target takes Fire damage equal to 3d6 plus your spellcasting ability modifier.\nThe flaming blade sheds Bright Light in a 10-ft radius and Dim Light for an additional 10 ft.\nUsing a Higher-Level Spell Slot. The damage increases by 1d6 for each spell slot level above 2.","concDuration":"10 min","attack":"melee","higher":"The damage increases by 1d6 for each spell slot level above 2.","componentsShort":"V, S, M","effect":{"text":"Evoke a fiery blade in your free hand"}},{"id":"flame-strike","name":"Flame Strike","level":5,"school":"Evocation","classes":["cleric"],"time":"Action","range":"60 ft","components":"V, S, M (a pinch of sulfur)","duration":"Instantaneous","concentration":false,"text":"A vertical column of brilliant fire roars down from above. Each creature in a 10-ft-radius, 40-fthigh Cylinder centered on a point within range makes a Dexterity saving throw, taking 5d6 Fire damage and 5d6 Radiant damage on a failed save or half as much damage on a successful one.\nUsing a Higher-Level Spell Slot. The Fire damage and the Radiant damage increase by 1d6 for each spell slot level above 5.","save":"dex","effect":{"dice":"5d6","type":"fire + 5d6 radiant","addMod":false},"higher":"The Fire damage and the Radiant damage increase by 1d6 for each spell slot level above 5.","upcast":{"dice":"1d6"},"componentsShort":"V, S, M"},{"id":"flaming-sphere","name":"Flaming Sphere","level":2,"school":"Conjuration","classes":["druid","sorcerer","wizard"],"time":"Action","range":"60 ft","components":"V, S, M (a ball of wax)","duration":"Up to 1 minute","concentration":true,"text":"You create a 5-ft-diameter sphere of fire in an unoccupied space on the ground within range. It lasts for the duration. Any creature that ends its turn within 5 ft of the sphere makes a Dexterity saving throw, taking 2d6 Fire damage on a failed save or half as much damage on a successful one.\nAs a Bonus Action, you can move the sphere up to 30 ft, rolling it along the ground. If you move the sphere into a creature’s space, that creature makes the save against the sphere, and the sphere stops moving for the turn.\nWhen you move the sphere, you can direct it over barriers up to 5 ft tall and jump it across pits up to 10 ft wide. Flammable objects that aren’t being worn or carried start burning if touched by the sphere, and it sheds Bright Light in a 20-ft radius and Dim Light for an additional 20 ft.\nUsing a Higher-Level Spell Slot. The damage increases by 1d6 for each spell slot level above 2.","concDuration":"1 min","save":"dex","effect":{"dice":"2d6","type":"fire"},"higher":"The damage increases by 1d6 for each spell slot level above 2.","upcast":{"dice":"1d6"},"componentsShort":"V, S, M"},{"id":"flesh-to-stone","name":"Flesh to Stone","level":6,"school":"Transmutation","classes":["druid","sorcerer","wizard"],"time":"Action","range":"60 ft","components":"V, S, M (a cockatrice feather)","duration":"Up to 1 minute","concentration":true,"text":"You attempt to turn one creature that you can see within range into stone. The target makes a Constitution saving throw. On a failed save, it has the Restrained condition for the duration. On a successful save, its Speed is 0 until the start of your next turn.\nConstructs automatically succeed on the save.\nA Restrained target makes another Constitution saving throw at the end of each of its turns. If it successfully saves against this spell three times, the spell ends. If it fails its saves three times, it is turned to stone and has the Petrified condition for the duration. The successes and failures needn’t be consecutive; keep track of both until the target collects three of a kind.\nIf you maintain your Concentration on this spell for the entire possible duration, the target is Petrified until the condition is ended by Greater Restoration or similar magic.","concDuration":"1 min","save":"con","componentsShort":"V, S, M","effect":{"text":"Attempt to turn one creature that you can see within range…"}},{"id":"floating-disk","name":"Floating Disk","level":1,"school":"Conjuration","classes":["wizard"],"time":"Action","range":"30 ft","components":"V, S, M (a drop of mercury)","duration":"1 hour","concentration":false,"text":"This spell creates a circular, horizontal plane of force, 3 ft in diameter and 1 inch thick, that floats 3 ft above the ground in an unoccupied space of your choice that you can see within range. The disk remains for the duration and can hold up to 500 pounds. If more weight is placed on it, the spell ends, and everything on the disk falls to the ground.\nThe disk is immobile while you are within 20 ft of it. If you move more than 20 ft away from it, the disk follows you so that it remains within 20 ft of you. It can move across uneven terrain, up or down stairs, slopes and the like, but it can’t cross an elevation change of 10 ft or more. For example, the disk can’t move across a 10-ft-deep pit, nor could it leave such a pit if it was created at the bottom.\nIf you move more than 100 ft from the disk (typically because it can’t move around an obstacle to follow you), the spell ends.","ritual":true,"componentsShort":"V, S, M","effect":{"text":"This spell creates a circular, horizontal plane of force, 3…"}},{"id":"fly","name":"Fly","level":3,"school":"Transmutation","classes":["sorcerer","warlock","wizard"],"time":"Action","range":"Touch","components":"V, S, M (a feather)","duration":"Up to 10 minutes","concentration":true,"text":"You touch a willing creature. For the duration, the target gains a Fly Speed of 60 ft and can hover. When the spell ends, the target falls if it is still aloft unless it can stop the fall.\nUsing a Higher-Level Spell Slot. You can target one additional creature for each spell slot level above 3.","concDuration":"10 min","higher":"You can target one additional creature for each spell slot level above 3.","componentsShort":"V, S, M","effect":{"text":"Fly Speed 60 ft"}},{"id":"fog-cloud","name":"Fog Cloud","level":1,"school":"Conjuration","classes":["druid","ranger","sorcerer","wizard"],"time":"Action","range":"120 ft","components":"V, S","duration":"Up to 1 hour","concentration":true,"text":"You create a 20-ft-radius Sphere of fog centered on a point within range. The Sphere is Heavily Obscured. It lasts for the duration or until a strong wind (such as one created by Gust of Wind) disperses it.\nUsing a Higher-Level Spell Slot. The fog’s radius increases by 20 ft for each spell slot level above 1.","concDuration":"1 hour","higher":"The fog’s radius increases by 20 ft for each spell slot level above 1.","componentsShort":"V, S","effect":{"text":"20-ft-radius heavily obscured sphere"}},{"id":"forbiddance","name":"Forbiddance","level":6,"school":"Abjuration","classes":["cleric"],"time":"10 minutes","range":"Touch","components":"V, S, M (ruby dust worth 1,000+ GP)","duration":"1 day","concentration":false,"text":"You create a ward against magical travel that protects up to 40,000 square feet of floor space to a height of 30 ft above the floor. For the duration, creatures can’t teleport into the area or use portals, such as those created by the Gate spell, to enter the area. The spell proofs the area against planar travel, and therefore prevents creatures from accessing the area by way of the Astral Plane, the Ethereal Plane, the Feywild, the Shadowfell, or the Plane Shift spell.\nIn addition, the spell damages types of creatures that you choose when you cast it. Choose one or more of the following: Aberrations, Celestials, Elementals, Fey, Fiends, and Undead. When a creature of a chosen type enters the spell’s area for the first time on a turn or ends its turn there, the creature takes 5d10 Radiant or Necrotic damage (your choice when you cast this spell).\nYou can designate a password when you cast the spell. A creature that speaks the password as it enters the area takes no damage from the spell. The spell’s area can’t overlap with the area of another Forbiddance spell. If you cast Forbiddance every day for 30 days in the same location, the spell lasts until it is dispelled, and the Material components are consumed on the last casting.","ritual":true,"componentsShort":"V, S, M","effect":{"text":"Create a ward against magical travel that protects up to…"}},{"id":"forcecage","name":"Forcecage","level":7,"school":"Evocation","classes":["bard","warlock","wizard"],"time":"Action","range":"100 ft","components":"V, S, M (ruby dust worth 1,500+ GP, which the spell consumes)","duration":"Up to 1 hour","concentration":true,"text":"An immobile, Invisible, Cube-shaped prison composed of magical force springs into existence around an area you choose within range. The prison can be a cage or a solid box, as you choose.\nA prison in the shape of a cage can be up to 20 ft on a side and is made from 1/2-inch diameter bars spaced 1/2 inch apart. A prison in the shape of a box can be up to 10 ft on a side, creating a solid barrier that prevents any matter from passing through it and blocking any spells cast into or out from the area.\nWhen you cast the spell, any creature that is completely inside the cage’s area is trapped. Creatures only partially within the area, or those too large to fit inside it, are pushed away from the center of the area until they are completely outside it.\nA creature inside the cage can’t leave it by nonmagical means. If the creature tries to use teleportation or interplanar travel to leave, it must first make a Charisma saving throw. On a successful save, the creature can use that magic to exit the cage. On a failed save, the creature doesn’t exit the cage and wastes the spell or effect. The cage also extends into the Ethereal Plane, blocking ethereal travel.\nThis spell can’t be dispelled by Dispel Magic.","concDuration":"1 hour","save":"cha","componentsShort":"V, S, M","effect":{"text":"An immobile, Invisible, Cube-shaped prison composed of…"}},{"id":"foresight","name":"Foresight","level":9,"school":"Divination","classes":["bard","druid","warlock","wizard"],"time":"1 minute","range":"Touch","components":"V, S, M (a hummingbird feather)","duration":"8 hours","concentration":false,"text":"You touch a willing creature and bestow a limited ability to see into the immediate future. For the duration, the target has Advantage on D20 Tests, and other creatures have Disadvantage on attack rolls against it. The spell ends early if you cast it again.","componentsShort":"V, S, M","effect":{"text":"Advantage on d20 tests; attackers have Disadvantage"}},{"id":"freedom-of-movement","name":"Freedom of Movement","level":4,"school":"Abjuration","classes":["bard","cleric","druid","ranger"],"time":"Action","range":"Touch","components":"V, S, M (a leather strap)","duration":"1 hour","concentration":false,"text":"You touch a willing creature. For the duration, the target’s movement is unaffected by Difficult Terrain, and spells and other magical effects can neither reduce the target’s Speed nor cause the target to have the Paralyzed or Restrained conditions. The target also has a Swim Speed equal to its Speed.\nIn addition, the target can spend 5 ft of movement to automatically escape from nonmagical restraints, such as manacles or a creature imposing the Grappled condition on it.\nUsing a Higher-Level Spell Slot. You can target one additional creature for each spell slot level above 4.","higher":"You can target one additional creature for each spell slot level above 4.","componentsShort":"V, S, M","effect":{"text":"Ignore difficult terrain, paralysis, restraint"}},{"id":"freezing-sphere","name":"Freezing Sphere","level":6,"school":"Evocation","classes":["sorcerer","wizard"],"time":"Action","range":"300 ft","components":"V, S, M (a miniature crystal sphere)","duration":"Instantaneous","concentration":false,"text":"A frigid globe streaks from you to a point of your choice within range, where it explodes in a 60-ft-radius Sphere. Each creature in that area makes a Constitution saving throw, taking 10d6 Cold damage on failed save or half as much damage on a successful one.\nIf the globe strikes a body of water, it freezes the water to a depth of 6 inches over an area 30 ft square. This ice lasts for 1 minute. Creatures that were swimming on the surface of frozen water are trapped in the ice and have the Restrained condition. A trapped creature can take an action to make a Strength (Athletics) check against your spell save DC to break free.\nYou can refrain from firing the globe after completing the spell’s casting. If you do so, a globe about the size of a sling bullet, cool to the touch, appears in your hand. At any time, you or a creature you give the globe to can throw the globe (to a range of 40 ft) or hurl it with a sling (to the sling’s normal range). It shatters on impact, with the same effect as a normal casting of the spell. You can also set the globe down without shattering it. After 1 minute, if the globe hasn’t already shattered, it explodes.\nUsing a Higher-Level Spell Slot. The damage increases by 1d6 for each spell slot level above 6.","save":"con","effect":{"dice":"10d6","type":"cold"},"higher":"The damage increases by 1d6 for each spell slot level above 6.","upcast":{"dice":"1d6"},"componentsShort":"V, S, M"},{"id":"gaseous-form","name":"Gaseous Form","level":3,"school":"Transmutation","classes":["sorcerer","warlock","wizard"],"time":"Action","range":"Touch","components":"V, S, M (a bit of gauze)","duration":"Up to 1 hour","concentration":true,"text":"A willing creature you touch shape-shifts, along with everything it’s wearing and carrying, into a misty cloud for the duration. The spell ends on the target if it drops to 0 Hit Points or if it takes a Magic action to end the spell on itself.\nWhile in this form, the target’s only method of movement is a Fly Speed of 10 ft, and it can hover. The target can enter and occupy the space of another creature. The target has Resistance to Bludgeoning, Piercing, and Slashing damage; it has Immunity to the Prone condition; and it has Advantage on Strength, Dexterity, and Constitution saving throws. The target can pass through narrow openings, but it treats liquids as though they were solid surfaces.\nThe target can’t talk or manipulate objects, and any objects it was carrying or holding can’t be dropped, used, or otherwise interacted with. Finally, the target can’t attack or cast spells.\nUsing a Higher-Level Spell Slot. You can target one additional creature for each spell slot level above 3.","concDuration":"1 hour","save":"con","higher":"You can target one additional creature for each spell slot level above 3.","componentsShort":"V, S, M","effect":{"text":"A willing creature you touch shape-shifts, along with…"}},{"id":"gate","name":"Gate","level":9,"school":"Conjuration","classes":["cleric","sorcerer","warlock","wizard"],"time":"Action","range":"60 ft","components":"V, S, M (a diamond worth 5,000+ GP)","duration":"Up to 1 minute","concentration":true,"text":"You conjure a portal linking an unoccupied space you can see within range to a precise location on a different plane of existence. The portal is a circular opening, which you can make 5 to 20 ft in diameter. You can orient the portal in any direction you choose. The portal lasts for the duration, and the portal’s destination is visible through it.\nThe portal has a front and a back on each plane where it appears. Travel through the portal is possible only by moving through its front. Anything that does so is instantly transported to the other plane, appearing in the unoccupied space nearest to the portal.\nDeities and other planar rulers can prevent portals created by this spell from opening in their presence or anywhere within their domains. When you cast this spell, you can speak the name of a specific creature (a pseudonym, title, or nickname doesn’t work). If that creature is on a plane other than the one you are on, the portal opens next to the named creature and transports it to the nearest unoccupied space on your side of the portal.\nYou gain no special power over the creature, and it is free to act as the GM deems appropriate. It might leave, attack you, or help you.","concDuration":"1 min","componentsShort":"V, S, M","effect":{"text":"Portal to another plane"}},{"id":"geas","name":"Geas","level":5,"school":"Enchantment","classes":["bard","cleric","druid","paladin","wizard"],"time":"1 minute","range":"60 ft","components":"V","duration":"30 days","concentration":false,"text":"You give a verbal command to a creature that you can see within range, ordering it to carry out some service or refrain from an action or a course of activity as you decide. The target must succeed on a Wisdom saving throw or have the Charmed condition for the duration. The target automatically succeeds if it can’t understand your command. While Charmed, the creature takes 5d10 Psychic damage if it acts in a manner directly counter to your command. It takes this damage no more than once each day.\nYou can issue any command you choose, short of an activity that would result in certain death.\nShould you issue a suicidal command, the spell ends.\nA Remove Curse, Greater Restoration, or Wish spell ends this spell.\nUsing a Higher-Level Spell Slot. If you use a level 7 or 8 spell slot, the duration is 365 days. If you use a level 9 spell slot, the spell lasts until it is ended by one of the spells mentioned above.","save":"wis","effect":{"dice":"5d10","type":"psychic","text":"Magical command; 5d10 psychic if disobeyed"},"higher":"If you use a level 7 or 8 spell slot, the duration is 365 days. If you use a level 9 spell slot, the spell lasts until it is ended by one of the spells mentioned above.","componentsShort":"V"},{"id":"gentle-repose","name":"Gentle Repose","level":2,"school":"Necromancy","classes":["cleric","paladin","wizard"],"time":"Action","range":"Touch","components":"V, S, M (2 Copper Pieces, which the spell consumes)","duration":"10 days","concentration":false,"text":"You touch a corpse or other remains. For the duration, the target is protected from decay and can’t become Undead.\nThe spell also effectively extends the time limit on raising the target from the dead, since days spent under the influence of this spell don’t count against the time limit of spells such as Raise Dead.","ritual":true,"componentsShort":"V, S, M","effect":{"text":"Touch a corpse or other remains"}},{"id":"giant-insect","name":"Giant Insect","level":4,"school":"Conjuration","classes":["druid"],"time":"Action","range":"60 ft","components":"V, S","duration":"Up to 10 minutes","concentration":true,"text":"You summon a giant centipede, spider, or wasp (chosen when you cast the spell). It manifests in an unoccupied space you can see within range and uses the Giant Insect stat block. The form you choose determines certain details in its stat block. The creature disappears when it drops to 0 Hit Points or when the spell ends.\nThe creature is an ally to you and your allies. In combat, the creature shares your Initiative count, but it takes its turn immediately after yours. It obeys your verbal commands (no action required by you). If you don’t issue any, it takes the Dodge action and uses its movement to avoid danger.\nUsing a Higher-Level Spell Slot. Use the spell slot’s level for the spell’s level in the stat block.\nGiant Insect\nLarge Beast, Unaligned AC 11 + the spell’s level HP 30 + 10 for each spell level above 4 Speed 40 ft., Climb 40 ft., Fly 40 ft. (Wasp only) MOD SAVE\nMOD SAVE\nMOD SAVE\nStr 17 +3 +3 Int 4 −3 −3\nDex 13 +1 +1 Wis 14 +2 +2\nCon 15 +2 +2 Cha 3 −4 −4\nSenses Darkvision 60 ft.; Passive Perception 12 Languages Understands the languages you know CR None (XP 0; PB equals your Proficiency Bonus)\nTraits Spider Climb. The insect can climb difficult surfaces, including along ceilings, without needing to make an ability check.\nActions Multiattack. The insect makes a number of attacks equal to half this spell’s level (round down).\nPoison Jab. Melee Attack Roll: Bonus equals your spell attack modifier, reach 10 ft. Hit: 1d6 + 3 plus the spell’s level Piercing damage plus 1d4 Poison damage.\nWeb Bolt (Spider Only). Ranged Attack Roll: Bonus equals your spell attack modifier, range 60 ft. Hit: 1d10 + 3 plus the spell’s level Bludgeoning damage, and the target’s Speed is reduced to 0 until the start of the insect’s next turn.\nBonus Actions Venomous Spew (Centipede Only). Constitution Saving Throw: Your spell save DC, one creature the insect can see within 10 ft. Failure: The target has the Poisoned condition until the start of the insect’s next turn.","concDuration":"10 min","higher":"Use the spell slot’s level for the spell’s level in the stat block.","componentsShort":"V, S","effect":{"text":"Summon a giant centipede, spider, or wasp (chosen when you…"}},{"id":"glibness","name":"Glibness","level":8,"school":"Enchantment","classes":["bard","warlock"],"time":"Action","range":"Self","components":"V","duration":"1 hour","concentration":false,"text":"Until the spell ends, when you make a Charisma check, you can replace the number you roll with a 15. Additionally, no matter what you say, magic that would determine if you are telling the truth indicates that you are being truthful.","componentsShort":"V","effect":{"text":"Until the spell ends, when you make a Charisma check, you can…"}},{"id":"globe-of-invulnerability","name":"Globe of Invulnerability","level":6,"school":"Abjuration","classes":["sorcerer","wizard"],"time":"Action","range":"Self","components":"V, S, M (a glass bead)","duration":"Up to 1 minute","concentration":true,"text":"An immobile, shimmering barrier appears in a 10foot Emanation around you and remains for the duration.\nAny spell of level 5 or lower cast from outside the barrier can’t affect anything within it. Such a spell can target creatures and objects within the barrier, but the spell has no effect on them. Similarly, the area within the barrier is excluded from areas of effect created by such spells.\nUsing a Higher-Level Spell Slot. The barrier blocks spells of 1 level higher for each spell slot level above 6.","concDuration":"1 min","higher":"The barrier blocks spells of 1 level higher for each spell slot level above 6.","componentsShort":"V, S, M","effect":{"text":"An immobile, shimmering barrier appears in a 10foot Emanation…"}},{"id":"glyph-of-warding","name":"Glyph of Warding","level":3,"school":"Abjuration","classes":["bard","cleric","wizard"],"time":"1 hour","range":"Touch","components":"V, S, M (powdered diamond worth 200+ GP, which the spell consumes)","duration":"Until dispelled or triggered","concentration":false,"text":"You inscribe a glyph that later unleashes a magical effect. You inscribe it either on a surface (such as a table or a section of floor) or within an object that can be closed (such as a book or chest) to conceal the glyph. The glyph can cover an area no larger than 10 ft in diameter. If the surface or object is moved more than 10 ft from where you cast this spell, the glyph is broken, and the spell ends without being triggered.\nThe glyph is nearly imperceptible and requires a successful Wisdom (Perception) check against your spell save DC to notice.\nWhen you inscribe the glyph, you set its trigger and choose whether it’s an explosive rune or a spell glyph, as explained below.\nSet the Trigger. You decide what triggers the glyph when you cast the spell. For glyphs inscribed on a surface, common triggers include touching or stepping on the glyph, removing another object covering it, or approaching within a certain distance of it. For glyphs inscribed within an object, common triggers include opening that object or seeing the glyph. Once a glyph is triggered, this spell ends.\nYou can refine the trigger so that only creatures of certain types activate it (for example, the glyph could be set to affect Aberrations). You can also set conditions for creatures that don’t trigger the glyph, such as those who say a certain password.\nExplosive Rune. When triggered, the glyph erupts with magical energy in a 20-ft-radius Sphere centered on the glyph. Each creature in the area makes a Dexterity saving throw. A creature takes 5d8 Acid, Cold, Fire, Lightning, or Thunder damage (your choice when you create the glyph) on a failed save or half as much damage on a successful one.\nSpell Glyph. You can store a prepared spell of level 3 or lower in the glyph by casting it as part of creating the glyph. The spell must target a single creature or an area. The spell being stored has no immediate effect when cast in this way.\nWhen the glyph is triggered, the stored spell takes effect. If the spell has a target, it targets the creature that triggered the glyph. If the spell affects an area, the area is centered on that creature. If the spell summons Hostile creatures or creates harmful objects or traps, they appear as close as possible to the intruder and attack it. If the spell requires Concentration, it lasts until the end of its full duration.\nUsing a Higher-Level Spell Slot. The damage of an explosive rune increases by 1d8 for each spell slot level above 3. If you create a spell glyph, you can store any spell of up to the same level as the spell slot you use for the Glyph of Warding.","save":"dex","higher":"The damage of an explosive rune increases by 1d8 for each spell slot level above 3. If you create a spell glyph, you can store any spell of up to the same level as the spell slot you use for the Glyph of Warding.","componentsShort":"V, S, M","effect":{"text":"Inscribe a glyph that later unleashes a magical effect"}},{"id":"goodberry","name":"Goodberry","level":1,"school":"Conjuration","classes":["druid","ranger"],"time":"Action","range":"Self","components":"V, S, M (a sprig of mistletoe)","duration":"24 hours","concentration":false,"text":"Ten berries appear in your hand and are infused with magic for the duration. A creature can take a Bonus Action to eat one berry. Eating a berry restores 1 Hit Point, and the berry provides enough nourishment to sustain a creature for one day.\nUneaten berries disappear when the spell ends.","componentsShort":"V, S, M","effect":{"text":"10 berries, each heals 1 HP"}},{"id":"grease","name":"Grease","level":1,"school":"Conjuration","classes":["sorcerer","wizard"],"time":"Action","range":"60 ft","components":"V, S, M (a bit of pork rind or butter)","duration":"1 minute","concentration":false,"text":"Nonflammable grease covers the ground in a 10foot square centered on a point within range and turns it into Difficult Terrain for the duration.\nWhen the grease appears, each creature standing in its area must succeed on a Dexterity saving throw or have the Prone condition. A creature that enters the area or ends its turn there must also succeed on that save or fall Prone.","save":"dex","componentsShort":"V, S, M","effect":{"text":"Nonflammable grease covers the ground in a 10foot square…"}},{"id":"greater-invisibility","name":"Greater Invisibility","level":4,"school":"Illusion","classes":["bard","sorcerer","wizard"],"time":"Action","range":"Touch","components":"V, S","duration":"Up to 1 minute","concentration":true,"text":"A creature you touch has the Invisible condition until the spell ends.","concDuration":"1 min","componentsShort":"V, S","effect":{"text":"Invisible even while attacking"}},{"id":"greater-restoration","name":"Greater Restoration","level":5,"school":"Abjuration","classes":["bard","cleric","druid","paladin","ranger"],"time":"Action","range":"Touch","components":"V, S, M (diamond dust worth 100+ GP, which the spell consumes)","duration":"Instantaneous","concentration":false,"text":"You touch a creature and magically remove one of the following effects from it:\n• 1 Exhaustion level • The Charmed or Petrified condition • A curse, including the target’s Attunement to a cursed magic item • Any reduction to one of the target’s ability scores • Any reduction to the target’s Hit Point maximum","componentsShort":"V, S, M","effect":{"text":"End exhaustion, charm, petrification, curse"}},{"id":"guardian-of-faith","name":"Guardian of Faith","level":4,"school":"Conjuration","classes":["cleric"],"time":"Action","range":"30 ft","components":"V","duration":"8 hours","concentration":false,"text":"A Large spectral guardian appears and hovers for the duration in an unoccupied space that you can see within range. The guardian occupies that space and is invulnerable, and it appears in a form appropriate for your deity or pantheon. Any enemy that moves to a space within 10 ft of the guardian for the first time on a turn or starts its turn there makes a Dexterity saving throw, taking 20 Radiant damage on a failed save or half as much damage on a successful one. The guardian vanishes when it has dealt a total of 60 damage.","save":"dex","componentsShort":"V","effect":{"dice":"20","type":"radiant","addMod":false,"text":"20 radiant to enemies nearby (60 total)"}},{"id":"guards-and-wards","name":"Guards and Wards","level":6,"school":"Abjuration","classes":["bard","wizard"],"time":"1 hour","range":"Touch","components":"V, S, M (a silver rod worth 10+ GP)","duration":"24 hours","concentration":false,"text":"You create a ward that protects up to 2,500 square feet of floor space. The warded area can be up to 20 ft tall, and you shape it as one 50-ft square, one hundred 5-ft squares that are contiguous, or twenty-five 10-ft squares that are contiguous.\nWhen you cast this spell, you can specify individuals that are unaffected by the spell’s effects. You can also specify a password that, when spoken aloud within 5 ft of the warded area, makes the speaker immune to its effects.\nThe spell creates the effects below within the warded area. Dispel Magic has no effect on Guards and Wards itself, but each of the following effects can be dispelled. If all four are dispelled, Guards and Wards ends. If you cast the spell every day for 365 days on the same area, the spell thereafter lasts until all its effects are dispelled.\nCorridors. Fog fills all the warded corridors, making them Heavily Obscured. In addition, at each intersection or branching passage offering a choice of direction, there is a 50 percent chance that a creature other than you believes it is going in the opposite direction from the one it chooses.\nDoors. All doors in the warded area are magically locked, as if sealed by the Arcane Lock spell. In addition, you can cover up to ten doors with an illusion to make them appear as plain sections of wall.\nStairs. Webs fill all stairs in the warded area from top to bottom, as in the Web spell. These strands regrow in 10 minutes if they are destroyed while Guards and Wards lasts.\nOther Spell Effect. Place one of the following magical effects within the warded area:\n• Dancing Lights in four corridors, with a simple program that the lights repeat as long as Guards and Wards lasts • Magic Mouth in two locations • Stinking Cloud in two locations (the vapors return within 10 minutes if dispersed while Guards and Wards lasts) • Gust of Wind in one corridor or room (the wind blows continuously while the spell lasts) • Suggestion in one 5-ft square; any creature that enters that square receives the suggestion mentally","componentsShort":"V, S, M","effect":{"text":"Create a ward that protects up to 2,500 square feet of floor…"}},{"id":"guidance","name":"Guidance","level":0,"school":"Divination","classes":["cleric","druid"],"time":"Action","range":"Touch","components":"V, S","duration":"Up to 1 minute","concentration":true,"text":"You touch a willing creature and choose a skill. Until the spell ends, the creature adds 1d4 to any ability check using the chosen skill.","concDuration":"1 min","componentsShort":"V, S","effect":{"text":"+1d4 to checks with one skill"}},{"id":"guiding-bolt","name":"Guiding Bolt","level":1,"school":"Evocation","classes":["cleric"],"time":"Action","range":"120 ft","components":"V, S","duration":"1 round","concentration":false,"text":"You hurl a bolt of light toward a creature within range. Make a ranged spell attack against the target. On a hit, it takes 4d6 Radiant damage, and the next attack roll made against it before the end of your next turn has Advantage.\nUsing a Higher-Level Spell Slot. The damage increases by 1d6 for each spell slot level above 1.","attack":"ranged","effect":{"dice":"4d6","type":"radiant"},"higher":"The damage increases by 1d6 for each spell slot level above 1.","upcast":{"dice":"1d6"},"componentsShort":"V, S"},{"id":"gust-of-wind","name":"Gust of Wind","level":2,"school":"Evocation","classes":["druid","ranger","sorcerer","wizard"],"time":"Action","range":"Self","components":"V, S, M (a legume seed)","duration":"Up to 1 minute","concentration":true,"text":"A Line of strong wind 60 ft long and 10 ft wide blasts from you in a direction you choose for the duration. Each creature in the Line must succeed on a Strength saving throw or be pushed 15 ft away from you in a direction following the Line. A creature that ends its turn in the Line must make the same save.\nAny creature in the Line must spend 2 ft of movement for every 1 ft it moves when moving closer to you.\nThe gust disperses gas or vapor, and it extinguishes candles and similar unprotected flames in the area. It causes protected flames, such as those of lanterns, to dance wildly and has a 50 percent chance to extinguish them.\nAs a Bonus Action on your later turns, you can change the direction in which the Line blasts from you.","concDuration":"1 min","save":"str","componentsShort":"V, S, M","effect":{"text":"A Line of strong wind 60 ft long and 10 ft wide blasts from…"}},{"id":"hallow","name":"Hallow","level":5,"school":"Abjuration","classes":["cleric"],"time":"24 hours","range":"Touch","components":"V, S, M (incense worth 1,000+ GP, which the spell consumes)","duration":"Until dispelled","concentration":false,"text":"You touch a point and infuse an area around it with holy or unholy power. The area can have a radius up to 60 ft, and the spell fails if the radius includes an area already under the effect of Hallow. The affected area has the following effects.\nHallowed Ward. Choose any of these creature types: Aberration, Celestial, Elemental, Fey, Fiend, or Undead. Creatures of the chosen types can’t willingly enter the area, and any creature that is possessed by or that has the Charmed or Frightened condition from such creatures isn’t possessed, Charmed, or Frightened by them while in the area.\nExtra Effect. You bind an extra effect to the area from the list below:\nCourage. Creatures of any types you choose can’t gain the Frightened condition while in the area.\nDarkness. Darkness fills the area. Normal light, as well as magical light created by spells of a level lower than this spell, can’t illuminate the area.\nDaylight. Bright light fills the area. Magical Darkness created by spells of a level lower than this spell can’t extinguish the light.\nPeaceful Rest. Dead bodies interred in the area can’t be turned into Undead.\nExtradimensional Interference. Creatures of any types you choose can’t enter or exit the area using teleportation or interplanar travel.\nFear. Creatures of any types you choose have the Frightened condition while in the area.\nResistance. Creatures of any types you choose have Resistance to one damage type of your choice while in the area.\nSilence. No sound can emanate from within the area, and no sound can reach into it.\nTongues. Creatures of any types you choose can communicate with any other creature in the area even if they don’t share a common language.\nVulnerability. Creatures of any types you choose have Vulnerability to one damage type of your choice while in the area.","componentsShort":"V, S, M","effect":{"text":"Touch a point and infuse an area around it with holy or…"}},{"id":"hallucinatory-terrain","name":"Hallucinatory Terrain","level":4,"school":"Illusion","classes":["bard","druid","warlock","wizard"],"time":"10 minutes","range":"300 ft","components":"V, S, M (a mushroom)","duration":"24 hours","concentration":false,"text":"You make natural terrain in a 150-ft Cube in range look, sound, and smell like another sort of natural terrain. Thus, open fields or a road can be made to resemble a swamp, hill, crevasse, or some other difficult or impassable terrain. A pond can be made to seem like a grassy meadow, a precipice like a gentle slope, or a rock-strewn gully like a wide and smooth road. Manufactured structures, equipment, and creatures within the area aren’t changed.\nThe tactile characteristics of the terrain are unchanged, so creatures entering the area are likely to notice the illusion. If the difference isn’t obvious by touch, a creature examining the illusion can take the Study action to make an Intelligence (Investigation) check against your spell save DC to disbelieve it. If a creature discerns that the terrain is illusory, the creature sees a vague image superimposed on the real terrain.","componentsShort":"V, S, M","effect":{"text":"Make natural terrain in a 150-ft Cube in range look, sound,…"}},{"id":"harm","name":"Harm","level":6,"school":"Necromancy","classes":["cleric"],"time":"Action","range":"60 ft","components":"V, S","duration":"Instantaneous","concentration":false,"text":"You unleash virulent magic on a creature you can see within range. The target makes a Constitution saving throw. On a failed save, it takes 14d6 Necrotic damage, and its Hit Point maximum is reduced by an amount equal to the Necrotic damage it took. On a successful save, it takes half as much damage only. This spell can’t reduce a target’s Hit Point maximum below 1.","save":"con","effect":{"dice":"14d6","type":"necrotic"},"componentsShort":"V, S"},{"id":"haste","name":"Haste","level":3,"school":"Transmutation","classes":["sorcerer","wizard"],"time":"Action","range":"30 ft","components":"V, S, M (a shaving of licorice root)","duration":"Up to 1 minute","concentration":true,"text":"Choose a willing creature that you can see within range. Until the spell ends, the target’s Speed is doubled, it gains a +2 bonus to Armor Class, it has Advantage on Dexterity saving throws, and it gains an additional action on each of its turns. That action can be used to take only the Attack (one attack only), Dash, Disengage, Hide, or Utilize action.\nWhen the spell ends, the target is Incapacitated and has a Speed of 0 until the end of its next turn, as a wave of lethargy washes over it.","concDuration":"1 min","save":"dex","componentsShort":"V, S, M","effect":{"text":"Double Speed, +2 AC, extra action"}},{"id":"heal","name":"Heal","level":6,"school":"Abjuration","classes":["cleric","druid"],"time":"Action","range":"60 ft","components":"V, S","duration":"Instantaneous","concentration":false,"text":"Choose a creature that you can see within range.\nPositive energy washes through the target, restoring 70 Hit Points. This spell also ends the Blinded, Deafened, and Poisoned conditions on the target.\nUsing a Higher-Level Spell Slot. The healing increases by 10 for each spell slot level above 6.","higher":"The healing increases by 10 for each spell slot level above 6.","componentsShort":"V, S","effect":{"dice":"70","type":"healing","addMod":false,"text":"Restore 70 HP and end Blinded/Deafened/Poisoned"}},{"id":"healing-word","name":"Healing Word","level":1,"school":"Abjuration","classes":["bard","cleric","druid"],"time":"Bonus Action","range":"60 ft","components":"V","duration":"Instantaneous","concentration":false,"text":"A creature of your choice that you can see within range regains Hit Points equal to 2d4 plus your spellcasting ability modifier.\nUsing a Higher-Level Spell Slot. The healing increases by 2d4 for each spell slot level above 1.","effect":{"dice":"2d4","type":"healing","addMod":true},"higher":"The healing increases by 2d4 for each spell slot level above 1.","upcast":{"dice":"2d4"},"componentsShort":"V"},{"id":"heat-metal","name":"Heat Metal","level":2,"school":"Transmutation","classes":["bard","druid"],"time":"Action","range":"60 ft","components":"V, S, M (a piece of iron and a flame)","duration":"Up to 1 minute","concentration":true,"text":"Choose a manufactured metal object, such as a metal weapon or a suit of Heavy or Medium metal armor, that you can see within range. You cause the object to glow red-hot. Any creature in physical contact with the object takes 2d8 Fire damage when you cast the spell. Until the spell ends, you can take a Bonus Action on each of your later turns to deal this damage again if the object is within range.\nIf a creature is holding or wearing the object and takes the damage from it, the creature must succeed on a Constitution saving throw or drop the object if it can. If it doesn’t drop the object, it has Disadvantage on attack rolls and ability checks until the start of your next turn.\nUsing a Higher-Level Spell Slot. The damage increases by 1d8 for each spell slot level above 2.","concDuration":"1 min","save":"con","effect":{"dice":"2d8","type":"fire"},"higher":"The damage increases by 1d8 for each spell slot level above 2.","upcast":{"dice":"1d8"},"componentsShort":"V, S, M"},{"id":"hellish-rebuke","name":"Hellish Rebuke","level":1,"school":"Evocation","classes":["warlock"],"time":"Reaction","range":"60 ft","components":"V, S","duration":"Instantaneous","concentration":false,"text":"The creature that damaged you is momentarily surrounded by green flames. It makes a Dexterity saving throw, taking 2d10 Fire damage on a failed save or half as much damage on a successful one.\nUsing a Higher-Level Spell Slot. The damage increases by 1d10 for each spell slot level above 1.","trigger":"in response to taking damage from a creature that you can see within 60 ft of yourself","save":"dex","effect":{"dice":"2d10","type":"fire"},"higher":"The damage increases by 1d10 for each spell slot level above 1.","upcast":{"dice":"1d10"},"componentsShort":"V, S"},{"id":"heroes-feast","name":"Heroes’ Feast","level":6,"school":"Conjuration","classes":["bard","cleric","druid"],"time":"10 minutes","range":"Self","components":"V, S, M (a gem-encrusted bowl worth 1,000+ GP, which the spell consumes)","duration":"Instantaneous","concentration":false,"text":"You conjure a feast that appears on a surface in an unoccupied 10-ft Cube next to you. The feast takes 1 hour to consume and disappears at the end of that time, and the beneficial effects don’t set in until this hour is over. Up to twelve creatures can partake of the feast.\nA creature that partakes gains several benefits, which last for 24 hours. The creature has Resistance to Poison damage, and it has Immunity to the Frightened and Poisoned conditions. Its Hit Point maximum also increases by 2d10, and it gains the same number of Hit Points.","componentsShort":"V, S, M","effect":{"text":"Conjure a feast that appears on a surface in an unoccupied…"}},{"id":"heroism","name":"Heroism","level":1,"school":"Enchantment","classes":["bard","paladin"],"time":"Action","range":"Touch","components":"V, S","duration":"Up to 1 minute","concentration":true,"text":"A willing creature you touch is imbued with bravery. Until the spell ends, the creature is immune to the Frightened condition and gains Temporary Hit Points equal to your spellcasting ability modifier at the start of each of its turns.\nUsing a Higher-Level Spell Slot. You can target one additional creature for each spell slot level above 1.","concDuration":"1 min","higher":"You can target one additional creature for each spell slot level above 1.","componentsShort":"V, S","effect":{"text":"Immune to Frightened, temp HP each turn"}},{"id":"hex","name":"Hex","level":1,"school":"Enchantment","classes":["warlock"],"time":"Bonus Action","range":"90 ft","components":"V, S, M (the petrified eye of a newt)","duration":"Up to 1 hour","concentration":true,"text":"You place a curse on a creature that you can see within range. Until the spell ends, you deal an extra 1d6 Necrotic damage to the target whenever you hit it with an attack roll. Also, choose one ability when you cast the spell. The target has Disadvantage on ability checks made with the chosen ability.\nIf the target drops to 0 Hit Points before this spell ends, you can take a Bonus Action on a later turn to curse a new creature.\nUsing a Higher-Level Spell Slot. Your Concentration can last longer with a spell slot of level 2 (up to 4 hours), 3–4 (up to 8 hours), or 5+ (24 hours).","concDuration":"1 hour","effect":{"dice":"1d6","type":"necrotic","text":"+1d6 necrotic on hits"},"higher":"Your Concentration can last longer with a spell slot of level 2 (up to 4 hours), 3–4 (up to 8 hours), or 5+ (24 hours).","componentsShort":"V, S, M"},{"id":"hideous-laughter","name":"Hideous Laughter","level":1,"school":"Enchantment","classes":["bard","warlock","wizard"],"time":"Action","range":"30 ft","components":"V, S, M (a tart and a feather)","duration":"Up to 1 minute","concentration":true,"text":"One creature of your choice that you can see within range makes a Wisdom saving throw. On a failed save, it has the Prone and Incapacitated conditions for the duration. During that time, it laughs uncontrollably if it’s capable of laughter, and it can’t end the Prone condition on itself.\nAt the end of each of its turns and each time it takes damage, it makes another Wisdom saving throw. The target has Advantage on the save if the save is triggered by damage. On a successful save, the spell ends.\nUsing a Higher-Level Spell Slot. You can target one additional creature for each spell slot level above 1.","concDuration":"1 min","save":"wis","higher":"You can target one additional creature for each spell slot level above 1.","componentsShort":"V, S, M","effect":{"text":"One creature of your choice that you can see within range…"}},{"id":"hold-monster","name":"Hold Monster","level":5,"school":"Enchantment","classes":["bard","sorcerer","warlock","wizard"],"time":"Action","range":"90 ft","components":"V, S, M (a straight piece of iron)","duration":"Up to 1 minute","concentration":true,"text":"Choose a creature that you can see within range. The target must succeed on a Wisdom saving throw or have the Paralyzed condition for the duration. At the end of each of its turns, the target repeats the save, ending the spell on itself on a success.\nUsing a Higher-Level Spell Slot. You can target one additional creature for each spell slot level above 5.","concDuration":"1 min","save":"wis","higher":"You can target one additional creature for each spell slot level above 5.","componentsShort":"V, S, M","effect":{"text":"Paralyzed (any creature)"}},{"id":"hold-person","name":"Hold Person","level":2,"school":"Enchantment","classes":["bard","cleric","druid","sorcerer","warlock","wizard"],"time":"Action","range":"60 ft","components":"V, S, M (a straight piece of iron)","duration":"Up to 1 minute","concentration":true,"text":"Choose a Humanoid that you can see within range. The target must succeed on a Wisdom saving throw or have the Paralyzed condition for the duration. At the end of each of its turns, the target repeats the save, ending the spell on itself on a success.\nUsing a Higher-Level Spell Slot. You can target one additional Humanoid for each spell slot level above 2.","concDuration":"1 min","save":"wis","higher":"You can target one additional Humanoid for each spell slot level above 2.","componentsShort":"V, S, M","effect":{"text":"Paralyzed (WIS save each turn)"}},{"id":"holy-aura","name":"Holy Aura","level":8,"school":"Abjuration","classes":["cleric"],"time":"Action","range":"Self","components":"V, S, M (a reliquary worth 1,000+ GP)","duration":"Up to 1 minute","concentration":true,"text":"For the duration, you emit an aura in a 30-ft Emanation. While in the aura, creatures of your choice have Advantage on all saving throws, and other creatures have Disadvantage on attack rolls against them. In addition, when a Fiend or an Undead hits an affected creature with a melee attack roll, the attacker must succeed on a Constitution saving throw or have the Blinded condition until the end of its next turn.","concDuration":"1 min","save":"con","componentsShort":"V, S, M","effect":{"text":"Allies get Advantage on saves; attackers have Disadvantage"}},{"id":"hunters-mark","name":"Hunter’s Mark","level":1,"school":"Divination","classes":["ranger"],"time":"Bonus Action","range":"90 ft","components":"V","duration":"Up to 1 hour","concentration":true,"text":"You magically mark one creature you can see within range as your quarry. Until the spell ends, you deal an extra 1d6 Force damage to the target whenever you hit it with an attack roll. You also have Advantage on any Wisdom (Perception or Survival) check you make to find it.\nIf the target drops to 0 Hit Points before this spell ends, you can take a Bonus Action to move the mark to a new creature you can see within range.\nUsing a Higher-Level Spell Slot. Your Concentration can last longer with a spell slot of level 3–4 (up to 8 hours) or 5+ (up to 24 hours).","concDuration":"1 hour","effect":{"dice":"1d6","type":"force","text":"+1d6 force on hits"},"higher":"Your Concentration can last longer with a spell slot of level 3–4 (up to 8 hours) or 5+ (up to 24 hours).","componentsShort":"V"},{"id":"hypnotic-pattern","name":"Hypnotic Pattern","level":3,"school":"Illusion","classes":["bard","sorcerer","warlock","wizard"],"time":"Action","range":"120 ft","components":"S, M (a pinch of confetti)","duration":"Up to 1 minute","concentration":true,"text":"You create a twisting pattern of colors in a 30-ft Cube within range. The pattern appears for a moment and vanishes. Each creature in the area who can see the pattern must succeed on a Wisdom saving throw or have the Charmed condition for the duration. While Charmed, the creature has the Incapacitated condition and a Speed of 0. The spell ends for an affected creature if it takes any damage or if someone else uses an action to shake the creature out of its stupor.","concDuration":"1 min","save":"wis","componentsShort":"S, M","effect":{"text":"Charmed and Incapacitated"}},{"id":"ice-knife","name":"Ice Knife","level":1,"school":"Conjuration","classes":["druid","sorcerer","wizard"],"time":"Action","range":"60 ft","components":"S, M (a drop of water or a piece of ice)","duration":"Instantaneous","concentration":false,"text":"You create a shard of ice and fling it at one creature within range. Make a ranged spell attack against the target. On a hit, the target takes 1d10 Piercing damage. Hit or miss, the shard then explodes. The target and each creature within 5 ft of it must succeed on a Dexterity saving throw or take 2d6 Cold damage.\nUsing a Higher-Level Spell Slot. The Cold damage increases by 1d6 for each spell slot level above 1.","attack":"ranged","save":"dex","effect":{"dice":"1d10","type":"piercing","second":{"dice":"2d6","type":"cold","save":"dex"}},"higher":"The Cold damage increases by 1d6 for each spell slot level above 1.","upcast":{"dice":"1d6","part":"second"},"componentsShort":"S, M"},{"id":"ice-storm","name":"Ice Storm","level":4,"school":"Evocation","classes":["druid","sorcerer","wizard"],"time":"Action","range":"300 ft","components":"V, S, M (a mitten)","duration":"Instantaneous","concentration":false,"text":"Hail falls in a 20-ft-radius, 40-ft-high Cylinder centered on a point within range. Each creature in the Cylinder makes a Dexterity saving throw. A creature takes 2d10 Bludgeoning damage and 4d6 Cold damage on a failed save or half as much damage on a successful one.\nHailstones turn ground in the Cylinder into Difficult Terrain until the end of your next turn.\nUsing a Higher-Level Spell Slot. The Bludgeoning damage increases by 1d10 for each spell slot level above 4.","save":"dex","effect":{"dice":"2d10","type":"bludgeoning + 4d6 cold","addMod":false},"higher":"The Bludgeoning damage increases by 1d10 for each spell slot level above 4.","upcast":{"dice":"1d10"},"componentsShort":"V, S, M"},{"id":"identify","name":"Identify","level":1,"school":"Divination","classes":["bard","wizard"],"time":"1 minute","range":"Touch","components":"V, S, M (a pearl worth 100+ GP)","duration":"Instantaneous","concentration":false,"text":"You touch an object throughout the spell’s casting.\nIf the object is a magic item or some other magical object, you learn its properties and how to use them, whether it requires Attunement, and how many charges it has, if any. You learn whether any ongoing spells are affecting the item and what they are. If the item was created by a spell, you learn that spell’s name.\nIf you instead touch a creature throughout the casting, you learn which ongoing spells, if any, are currently affecting it.","ritual":true,"componentsShort":"V, S, M","effect":{"text":"Touch an object throughout the spell’s casting"}},{"id":"illusory-script","name":"Illusory Script","level":1,"school":"Illusion","classes":["bard","warlock","wizard"],"time":"1 minute","range":"Touch","components":"S, M (ink worth 10+ GP, which the spell consumes)","duration":"10 days","concentration":false,"text":"You write on parchment, paper, or another suitable material and imbue it with an illusion that lasts for the duration. To you and any creatures you designate when you cast the spell, the writing appears normal, seems to be written in your hand, and conveys whatever meaning you intended when you wrote the text. To all others, the writing appears as if it were written in an unknown or magical script that is unintelligible. Alternatively, the illusion can alter the meaning, handwriting, and language of the text, though the language must be one you know.\nIf the spell is dispelled, the original script and the illusion both disappear.\nA creature that has Truesight can read the hidden message.","ritual":true,"componentsShort":"S, M","effect":{"text":"Write on parchment, paper, or another suitable material and…"}},{"id":"imprisonment","name":"Imprisonment","level":9,"school":"Abjuration","classes":["warlock","wizard"],"time":"1 minute","range":"30 ft","components":"V, S, M (a statuette of the target worth 5,000+ GP)","duration":"Until dispelled","concentration":false,"text":"You create a magical restraint to hold a creature that you can see within range. The target must make a Wisdom saving throw. On a successful save, the target is unaffected, and it is immune to this spell for the next 24 hours. On a failed save, the target is imprisoned. While imprisoned, the target doesn’t need to breathe, eat, or drink, and it doesn’t age. Divination spells can’t locate or perceive the imprisoned target, and the target can’t teleport.\nUntil the spell ends, the target is also affected by one of the following effects of your choice:\nBurial. The target is entombed beneath the earth in a hollow globe of magical force that is just large enough to contain the target. Nothing can pass into or out of the globe.\nChaining. Chains firmly rooted in the ground hold the target in place. The target has the Restrained condition and can’t be moved by any means.\nHedged Prison. The target is trapped in a demiplane that is warded against teleportation and planar travel. The demiplane is your choice of a labyrinth, a cage, a tower, or the like.\nMinimus Containment. The target becomes 1 inch tall and is trapped inside an indestructible gemstone or a similar object. Light can pass through the gemstone (allowing the target to see out and other creatures to see in), but nothing else can pass through by any means.\nSlumber. The target has the Unconscious condition and can’t be awoken.\nEnding the Spell. When you cast the spell, specify a trigger that will end it. The trigger can be as simple or as elaborate as you choose, but the GM must agree that it has a high likelihood of happening within the next decade. The trigger must be an observable action, such as someone making a particular offering at the temple of your god, saving your true love, or defeating a specific monster.\nA Dispel Magic spell can end the spell only if it is cast with a level 9 spell slot, targeting either the prison or the component used to create it.","save":"wis","componentsShort":"V, S, M","effect":{"text":"Create a magical restraint to hold a creature that you can…"}},{"id":"incendiary-cloud","name":"Incendiary Cloud","level":8,"school":"Conjuration","classes":["druid","sorcerer","wizard"],"time":"Action","range":"150 ft","components":"V, S","duration":"Up to 1 minute","concentration":true,"text":"A swirling cloud of embers and smoke fills a 20-ft-radius Sphere centered on a point within range. The cloud’s area is Heavily Obscured. It lasts for the duration or until a strong wind (like that created by Gust of Wind) disperses it.\nWhen the cloud appears, each creature in it makes a Dexterity saving throw, taking 10d8 Fire damage on a failed save or half as much damage on a successful one. A creature must also make this save when the Sphere moves into its space and when it enters the Sphere or ends its turn there. A creature makes this save only once per turn.\nThe cloud moves 10 ft away from you in a direction you choose at the start of each of your turns.","concDuration":"1 min","save":"dex","effect":{"dice":"10d8","type":"fire"},"componentsShort":"V, S"},{"id":"inflict-wounds","name":"Inflict Wounds","level":1,"school":"Necromancy","classes":["cleric"],"time":"Action","range":"Touch","components":"V, S","duration":"Instantaneous","concentration":false,"text":"A creature you touch makes a Constitution saving throw, taking 2d10 Necrotic damage on a failed save or half as much damage on a successful one.\nUsing a Higher-Level Spell Slot. The damage increases by 1d10 for each spell slot level above 1.","save":"con","effect":{"dice":"2d10","type":"necrotic"},"higher":"The damage increases by 1d10 for each spell slot level above 1.","upcast":{"dice":"1d10"},"componentsShort":"V, S"},{"id":"insect-plague","name":"Insect Plague","level":5,"school":"Conjuration","classes":["cleric","druid","sorcerer"],"time":"Action","range":"300 ft","components":"V, S, M (a locust)","duration":"Up to 10 minutes","concentration":true,"text":"Swarming locusts fill a 20-ft-radius Sphere centered on a point you choose within range. The Sphere remains for the duration, and its area is Lightly Obscured and Difficult Terrain.\nWhen the swarm appears, each creature in it makes a Constitution saving throw, taking 4d10 Piercing damage on a failed save or half as much damage on a successful one. A creature also makes this save when it enters the spell’s area for the first time on a turn or ends its turn there. A creature makes this save only once per turn.\nUsing a Higher-Level Spell Slot. The damage increases by 1d10 for each spell slot level above 5.","concDuration":"10 min","save":"con","effect":{"dice":"4d10","type":"piercing","addMod":false},"higher":"The damage increases by 1d10 for each spell slot level above 5.","upcast":{"dice":"1d10"},"componentsShort":"V, S, M"},{"id":"instant-summons","name":"Instant Summons","level":6,"school":"Conjuration","classes":["wizard"],"time":"1 minute","range":"Touch","components":"V, S, M (a sapphire worth 1,000+ GP)","duration":"Until dispelled","concentration":false,"text":"You touch the sapphire used in the casting and an object weighing 10 pounds or less whose longest dimension is 6 ft or less. The spell leaves an Invisible mark on that object and invisibly inscribes the object’s name on the sapphire. Each time you cast this spell, you must use a different sapphire.\nThereafter, you can take a Magic action to speak the object’s name and crush the sapphire. The object instantly appears in your hand regardless of physical or planar distances, and the spell ends.\nIf another creature is holding or carrying the object, crushing the sapphire doesn’t transport it, but instead you learn who that creature is and where that creature is currently located.","ritual":true,"componentsShort":"V, S, M","effect":{"text":"Touch the sapphire used in the casting and an object weighing…"}},{"id":"irresistible-dance","name":"Irresistible Dance","level":6,"school":"Enchantment","classes":["bard","wizard"],"time":"Action","range":"30 ft","components":"V","duration":"Up to 1 minute","concentration":true,"text":"One creature that you can see within range must make a Wisdom saving throw. On a successful save, the target dances comically until the end of its next turn, during which it must spend all its movement to dance in place.\nOn a failed save, the target has the Charmed condition for the duration. While Charmed, the target dances comically, must use all its movement to dance in place, and has Disadvantage on Dexterity saving throws and attack rolls, and other creatures have Advantage on attack rolls against it. On each of its turns, the target can take an action to collect itself and repeat the save, ending the spell on itself on a success.","concDuration":"1 min","save":"wis","componentsShort":"V","effect":{"text":"One creature that you can see within range must make a Wisdom…"}},{"id":"invisibility","name":"Invisibility","level":2,"school":"Illusion","classes":["bard","sorcerer","warlock","wizard"],"time":"Action","range":"Touch","components":"V, S, M (an eyelash in gum arabic)","duration":"Up to 1 hour","concentration":true,"text":"A creature you touch has the Invisible condition until the spell ends. The spell ends early immediately after the target makes an attack roll, deals damage, or casts a spell.\nUsing a Higher-Level Spell Slot. You can target one additional creature for each spell slot level above 2.","concDuration":"1 hour","higher":"You can target one additional creature for each spell slot level above 2.","componentsShort":"V, S, M","effect":{"text":"Invisible until it attacks or casts"}},{"id":"jump","name":"Jump","level":1,"school":"Transmutation","classes":["druid","ranger","sorcerer","wizard"],"time":"Bonus Action","range":"Touch","components":"V, S, M (a grasshopper’s hind leg)","duration":"1 minute","concentration":false,"text":"You touch a willing creature. Once on each of its turns until the spell ends, that creature can jump up to 30 ft by spending 10 ft of movement.\nUsing a Higher-Level Spell Slot. You can target one additional creature for each spell slot level above 1.","higher":"You can target one additional creature for each spell slot level above 1.","componentsShort":"V, S, M","effect":{"text":"Touch a willing creature"}},{"id":"knock","name":"Knock","level":2,"school":"Transmutation","classes":["bard","sorcerer","wizard"],"time":"Action","range":"60 ft","components":"V","duration":"Instantaneous","concentration":false,"text":"Choose an object that you can see within range. The object can be a door, a box, a chest, a set of manacles, a padlock, or another object that contains a mundane or magical means that prevents access.\nA target that is held shut by a mundane lock or that is stuck or barred becomes unlocked, unstuck, or unbarred. If the object has multiple locks, only one of them is unlocked.\nIf the target is held shut by Arcane Lock, that spell is suppressed for 10 minutes, during which time the target can be opened and closed.\nWhen you cast the spell, a loud knock, audible up to 300 ft away, emanates from the target.","componentsShort":"V","effect":{"text":"Choose an object that you can see within range"}},{"id":"legend-lore","name":"Legend Lore","level":5,"school":"Divination","classes":["bard","cleric","wizard"],"time":"10 minutes","range":"Self","components":"V, S, M (incense worth 250+ GP, which the spell consumes, and four ivory strips worth 50+ GP each)","duration":"Instantaneous","concentration":false,"text":"Name or describe a famous person, place, or object.\nThe spell brings to your mind a brief summary of the significant lore about that famous thing, as described by the GM.\nThe lore might consist of important details, amusing revelations, or even secret lore that has never been widely known. The more information you already know about the thing, the more precise and detailed the information you receive is. That information is accurate but might be couched in figurative language or poetry, as determined by the GM. If the famous thing you chose isn’t actually famous, you hear sad musical notes played on a trombone, and the spell fails.","componentsShort":"V, S, M","effect":{"text":"Learn legends about a person, place or thing"}},{"id":"lesser-restoration","name":"Lesser Restoration","level":2,"school":"Abjuration","classes":["bard","cleric","druid","paladin","ranger"],"time":"Bonus Action","range":"Touch","components":"V, S","duration":"Instantaneous","concentration":false,"text":"You touch a creature and end one condition on it: Blinded, Deafened, Paralyzed, or Poisoned.","componentsShort":"V, S","effect":{"text":"End Blinded, Deafened, Paralyzed or Poisoned"}},{"id":"levitate","name":"Levitate","level":2,"school":"Transmutation","classes":["sorcerer","wizard"],"time":"Action","range":"60 ft","components":"V, S, M (a metal spring)","duration":"Up to 10 minutes","concentration":true,"text":"One creature or loose object of your choice that you can see within range rises vertically up to 20 ft and remains suspended there for the duration. The spell can levitate an object that weighs up to 500 pounds. An unwilling creature that succeeds on a Constitution saving throw is unaffected.\nThe target can move only by pushing or pulling against a fixed object or surface within reach (such as a wall or a ceiling), which allows it to move as if it were climbing. You can change the target’s altitude by up to 20 ft in either direction on your turn. If you are the target, you can move up or down as part of your move. Otherwise, you can take a Magic action to move the target, which must remain within the spell’s range.\nWhen the spell ends, the target floats gently to the ground if it is still aloft.","concDuration":"10 min","save":"con","componentsShort":"V, S, M","effect":{"text":"One creature or loose object of your choice that you can see…"}},{"id":"light","name":"Light","level":0,"school":"Evocation","classes":["bard","cleric","sorcerer","wizard"],"time":"Action","range":"Touch","components":"V, M (a firefly or phosphorescent moss)","duration":"1 hour","concentration":false,"text":"You touch one Large or smaller object that isn’t being worn or carried by someone else. Until the spell ends, the object sheds Bright Light in a 20-ft radius and Dim Light for an additional 20 ft. The light can be colored as you like.\nCovering the object with something opaque blocks the light. The spell ends if you cast it again.","componentsShort":"V, M","effect":{"text":"Object sheds light"}},{"id":"lightning-bolt","name":"Lightning Bolt","level":3,"school":"Evocation","classes":["sorcerer","wizard"],"time":"Action","range":"Self","components":"V, S, M (a bit of fur and a crystal rod)","duration":"Instantaneous","concentration":false,"text":"A stroke of lightning forming a 100-ft-long, 5-ft-wide Line blasts out from you in a direction you choose. Each creature in the Line makes a Dexterity saving throw, taking 8d6 Lightning damage on a failed save or half as much damage on a successful one.\nUsing a Higher-Level Spell Slot. The damage increases by 1d6 for each spell slot level above 3.","save":"dex","effect":{"dice":"8d6","type":"lightning"},"higher":"The damage increases by 1d6 for each spell slot level above 3.","upcast":{"dice":"1d6"},"componentsShort":"V, S, M"},{"id":"locate-animals-or-plants","name":"Locate Animals or Plants","level":2,"school":"Divination","classes":["bard","druid","ranger"],"time":"Action","range":"Self","components":"V, S, M (fur from a bloodhound)","duration":"Instantaneous","concentration":false,"text":"Describe or name a specific kind of Beast, Plant creature, or nonmagical plant. You learn the direction and distance to the closest creature or plant of that kind within 5 miles, if any are present.","ritual":true,"componentsShort":"V, S, M","effect":{"text":"Describe or name a specific kind of Beast, Plant creature, or…"}},{"id":"locate-creature","name":"Locate Creature","level":4,"school":"Divination","classes":["bard","cleric","druid","paladin","ranger","wizard"],"time":"Action","range":"Self","components":"V, S, M (fur from a bloodhound)","duration":"Up to 1 hour","concentration":true,"text":"Describe or name a creature that is familiar to you.\nYou sense the direction to the creature’s location if that creature is within 1,000 ft of you. If the creature is moving, you know the direction of its movement.\nThe spell can locate a specific creature known to you or the nearest creature of a specific kind (such as a human or a unicorn) if you have seen such a creature up close—within 30 ft—at least once.\nIf the creature you described or named is in a different form, such as under the effects of a Flesh to Stone or Polymorph spell, this spell doesn’t locate the creature.\nThis spell can’t locate a creature if any thickness of lead blocks a direct path between you and the creature.","concDuration":"1 hour","componentsShort":"V, S, M","effect":{"text":"Describe or name a creature that is familiar to you"}},{"id":"locate-object","name":"Locate Object","level":2,"school":"Divination","classes":["bard","cleric","druid","paladin","ranger","wizard"],"time":"Action","range":"Self","components":"V, S, M (a forked twig)","duration":"Up to 10 minutes","concentration":true,"text":"Describe or name an object that is familiar to you. You sense the direction to the object’s location if that object is within 1,000 ft of you. If the object is in motion, you know the direction of its movement. The spell can locate a specific object known to you if you have seen it up close—within 30 ft—at least once. Alternatively, the spell can locate the nearest object of a particular kind, such as a certain kind of apparel, jewelry, furniture, tool, or weapon. This spell can’t locate an object if any thickness of lead blocks a direct path between you and the object.","concDuration":"10 min","componentsShort":"V, S, M","effect":{"text":"Describe or name an object that is familiar to you"}},{"id":"longstrider","name":"Longstrider","level":1,"school":"Transmutation","classes":["bard","druid","ranger","wizard"],"time":"Action","range":"Touch","components":"V, S, M (a pinch of dirt)","duration":"1 hour","concentration":false,"text":"You touch a creature. The target’s Speed increases by 10 ft until the spell ends.\nUsing a Higher-Level Spell Slot. You can target one additional creature for each spell slot level above 1.","higher":"You can target one additional creature for each spell slot level above 1.","componentsShort":"V, S, M","effect":{"text":"Touch a creature"}},{"id":"mage-armor","name":"Mage Armor","level":1,"school":"Abjuration","classes":["sorcerer","wizard"],"time":"Action","range":"Touch","components":"V, S, M (a piece of cured leather)","duration":"8 hours","concentration":false,"text":"You touch a willing creature who isn’t wearing armor. Until the spell ends, the target’s base AC becomes 13 plus its Dexterity modifier. The spell ends early if the target dons armor.","componentsShort":"V, S, M","effect":{"text":"AC becomes 13 + DEX"}},{"id":"mage-hand","name":"Mage Hand","level":0,"school":"Conjuration","classes":["bard","sorcerer","warlock","wizard"],"time":"Action","range":"30 ft","components":"V, S","duration":"1 minute","concentration":false,"text":"A spectral, floating hand appears at a point you choose within range. The hand lasts for the duration. The hand vanishes if it is ever more than 30 ft away from you or if you cast this spell again.\nWhen you cast the spell, you can use the hand to manipulate an object, open an unlocked door or container, stow or retrieve an item from an open container, or pour the contents out of a vial.\nAs a Magic action on your later turns, you can control the hand thus again. As part of that action, you can move the hand up to 30 ft.\nThe hand can’t attack, activate magic items, or carry more than 10 pounds.","componentsShort":"V, S","effect":{"text":"Spectral hand"}},{"id":"magic-circle","name":"Magic Circle","level":3,"school":"Abjuration","classes":["cleric","paladin","warlock","wizard"],"time":"1 minute","range":"10 ft","components":"V, S, M (salt and powdered silver worth 100+ GP, which the spell consumes)","duration":"1 hour","concentration":false,"text":"You create a 10-ft-radius, 20-ft-tall Cylinder of magical energy centered on a point on the ground that you can see within range. Glowing runes appear wherever the Cylinder intersects with the floor or other surface.\nChoose one or more of the following types of creatures: Celestials, Elementals, Fey, Fiends, or Undead. The circle affects a creature of the chosen type in the following ways:\n• The creature can’t willingly enter the Cylinder by nonmagical means. If the creature tries to use teleportation or interplanar travel to do so, it must first succeed on a Charisma saving throw.\n• The creature has Disadvantage on attack rolls against targets within the Cylinder.\n• Targets within the Cylinder can’t be possessed by or gain the Charmed or Frightened condition from the creature.\nEach time you cast this spell, you can cause its magic to operate in the reverse direction, preventing a creature of the specified type from leaving the Cylinder and protecting targets outside it.\nUsing a Higher-Level Spell Slot. The duration increases by 1 hour for each spell slot level above 3.","save":"cha","higher":"The duration increases by 1 hour for each spell slot level above 3.","componentsShort":"V, S, M","effect":{"text":"Create a 10-ft-radius, 20-ft-tall Cylinder of magical energy…"}},{"id":"magic-jar","name":"Magic Jar","level":6,"school":"Necromancy","classes":["wizard"],"time":"1 minute","range":"Self","components":"V, S, M (a gem, crystal, or reliquary worth 500+ GP)","duration":"Until dispelled","concentration":false,"text":"Your body falls into a catatonic state as your soul leaves it and enters the container you used for the spell’s Material component. While your soul inhabits the container, you are aware of your surroundings as if you were in the container’s space. You can’t move or take Reactions. The only action you can take is to project your soul up to 100 ft out of the container, either returning to your living body (and ending the spell) or attempting to possess a Humanoid’s body.\nYou can attempt to possess any Humanoid within 100 ft of you that you can see (creatures warded by a Protection from Evil and Good or Magic Circle spell can’t be possessed). The target makes a Charisma saving throw. On a failed save, your soul enters the target’s body, and the target’s soul becomes trapped in the container. On a successful save, the target resists your efforts to possess it, and you can’t attempt to possess it again for 24 hours.\nOnce you possess a creature’s body, you control it.\nYour Hit Points, Hit Point Dice, Strength, Dexterity, Constitution, Speed, and senses are replaced by the creature’s. You otherwise keep your game statistics.\nMeanwhile, the possessed creature’s soul can perceive from the container using its own senses, but it can’t move and it is Incapacitated.\nWhile possessing a body, you can take a Magic action to return from the host body to the container if it is within 100 ft of you, returning the host creature’s soul to its body. If the host body dies while you’re in it, the creature dies, and you make a Charisma saving throw against your own spellcasting DC. On a success, you return to the container if it is within 100 ft of you. Otherwise, you die.\nIf the container is destroyed or the spell ends, your soul returns to your body. If your body is more than 100 ft away from you or if your body is dead, you die. If another creature’s soul is in the container when it is destroyed, the creature’s soul returns to its body if the body is alive and within 100 ft. Otherwise, that creature dies.\nWhen the spell ends, the container is destroyed.","save":"cha","componentsShort":"V, S, M","effect":{"text":"Your body falls into a catatonic state as your soul leaves it…"}},{"id":"magic-missile","name":"Magic Missile","level":1,"school":"Evocation","classes":["sorcerer","wizard"],"time":"Action","range":"120 ft","components":"V, S","duration":"Instantaneous","concentration":false,"text":"You create three glowing darts of magical force.\nEach dart strikes a creature of your choice that you can see within range. A dart deals 1d4 + 1 Force damage to its target. The darts all strike simultaneously, and you can direct them to hit one creature or several.\nUsing a Higher-Level Spell Slot. The spell creates one more dart for each spell slot level above 1.","effect":{"dice":"3d4","type":"force","text":"3 darts · 1d4 + 1 force each"},"higher":"The spell creates one more dart for each spell slot level above 1.","componentsShort":"V, S"},{"id":"magic-mouth","name":"Magic Mouth","level":2,"school":"Illusion","classes":["bard","wizard"],"time":"1 minute","range":"30 ft","components":"V, S, M (jade dust worth 10+ GP, which the spell consumes)","duration":"Until dispelled","concentration":false,"text":"You implant a message within an object in range—a message that is uttered when a trigger condition is met. Choose an object that you can see and that isn’t being worn or carried by another creature. Then speak the message, which must be 25 words or fewer, though it can be delivered over as long as 10 minutes. Finally, determine the circumstance that will trigger the spell to deliver your message.\nWhen that trigger occurs, a magical mouth appears on the object and recites the message in your voice and at the same volume you spoke. If the object you chose has a mouth or something that looks like a mouth (for example, the mouth of a statue), the magical mouth appears there, so the words appear to come from the object’s mouth. When you cast this spell, you can have the spell end after it delivers its message, or it can remain and repeat its message whenever the trigger occurs.\nThe trigger can be as general or as detailed as you like, though it must be based on visual or audible conditions that occur within 30 ft of the object.\nFor example, you could instruct the mouth to speak when any creature moves within 30 ft of the object or when a silver bell rings within 30 ft of it.","ritual":true,"componentsShort":"V, S, M","effect":{"text":"Implant a message within an object in range—a message that is…"}},{"id":"magic-weapon","name":"Magic Weapon","level":2,"school":"Transmutation","classes":["paladin","ranger","sorcerer","wizard"],"time":"Bonus Action","range":"Touch","components":"V, S","duration":"1 hour","concentration":false,"text":"You touch a nonmagical weapon. Until the spell ends, that weapon becomes a magic weapon with a +1 bonus to attack rolls and damage rolls. The spell ends early if you cast it again.\nUsing a Higher-Level Spell Slot. The bonus increases to +2 with a level 3–5 spell slot. The bonus increases to +3 with a level 6+ spell slot.","higher":"The bonus increases to +2 with a level 3–5 spell slot. The bonus increases to +3 with a level 6+ spell slot.","componentsShort":"V, S","effect":{"text":"Weapon becomes +1"}},{"id":"magnificent-mansion","name":"Magnificent Mansion","level":7,"school":"Conjuration","classes":["bard","wizard"],"time":"1 minute","range":"300 ft","components":"V, S, M (a miniature door worth 15+ GP)","duration":"24 hours","concentration":false,"text":"You conjure a shimmering door in range that lasts for the duration. The door leads to an extradimensional dwelling and is 5 ft wide and 10 ft tall. You and any creature you designate when you cast the spell can enter the extradimensional dwelling as long as the door remains open. You can open or close it (no action required) if you are within 30 ft of it. While closed, the door is imperceptible.\nBeyond the door is a magnificent foyer with numerous chambers beyond. The dwelling’s atmosphere is clean, fresh, and warm.\nYou can create any floor plan you like for the dwelling, but it can’t exceed 50 contiguous 10-ft Cubes. The place is furnished and decorated as you choose. It contains sufficient food to serve a ninecourse banquet for up to 100 people. Furnishings and other objects created by this spell dissipate into smoke if removed from it.\nA staff of 100 near-transparent servants attends all who enter. You determine the appearance of these servants and their attire. They are invulnerable and obey your commands. Each servant can perform tasks that a human could perform, but they can’t attack or take any action that would directly harm another creature. Thus the servants can fetch things, clean, mend, fold clothes, light fires, serve food, pour wine, and so on. The servants can’t leave the dwelling.\nWhen the spell ends, any creatures or objects left inside the extradimensional space are expelled into the unoccupied spaces nearest to the entrance.","componentsShort":"V, S, M","effect":{"text":"Conjure a shimmering door in range that lasts for the duration"}},{"id":"major-image","name":"Major Image","level":3,"school":"Illusion","classes":["bard","sorcerer","warlock","wizard"],"time":"Action","range":"120 ft","components":"V, S, M (a bit of fleece)","duration":"Up to 10 minutes","concentration":true,"text":"You create the image of an object, a creature, or some other visible phenomenon that is no larger than a 20-ft Cube. The image appears at a spot that you can see within range and lasts for the duration. It seems real, including sounds, smells, and temperature appropriate to the thing depicted, but it can’t deal damage or cause conditions.\nIf you are within range of the illusion, you can take a Magic action to cause the image to move to any other spot within range. As the image changes location, you can alter its appearance so that its movements appear natural for the image. For example, if you create an image of a creature and move it, you can alter the image so that it appears to be walking. Similarly, you can cause the illusion to make different sounds at different times, even making it carry on a conversation, for example. Physical interaction with the image reveals it to be an illusion, for things can pass through it. A creature that takes a Study action to examine the image can determine that it is an illusion with a successful Intelligence (Investigation) check against your spell save DC. If a creature discerns the illusion for what it is, the creature can see through the image, and its other sensory qualities become faint to the creature.\nUsing a Higher-Level Spell Slot. The spell lasts until dispelled, without requiring Concentration, if cast with a level 4+ spell slot.","concDuration":"10 min","higher":"The spell lasts until dispelled, without requiring Concentration, if cast with a level 4+ spell slot.","componentsShort":"V, S, M","effect":{"text":"Create the image of an object, a creature, or some other…"}},{"id":"mass-cure-wounds","name":"Mass Cure Wounds","level":5,"school":"Abjuration","classes":["bard","cleric","druid"],"time":"Action","range":"60 ft","components":"V, S","duration":"Instantaneous","concentration":false,"text":"A wave of healing energy washes out from a point you can see within range. Choose up to six creatures in a 30-ft-radius Sphere centered on that point. Each target regains Hit Points equal to 5d8 plus your spellcasting ability modifier.\nUsing a Higher-Level Spell Slot. The healing increases by 1d8 for each spell slot level above 5.","effect":{"dice":"5d8","type":"healing","addMod":true,"text":"Up to 6 creatures in a 30-ft sphere"},"higher":"The healing increases by 1d8 for each spell slot level above 5.","upcast":{"dice":"1d8"},"componentsShort":"V, S"},{"id":"mass-heal","name":"Mass Heal","level":9,"school":"Abjuration","classes":["cleric"],"time":"Action","range":"60 ft","components":"V, S","duration":"Instantaneous","concentration":false,"text":"A flood of healing energy flows from you into creatures around you. You restore up to 700 Hit Points, divided as you choose among any number of creatures that you can see within range. Creatures healed by this spell also have the Blinded, Deafened, and Poisoned conditions removed from them.","componentsShort":"V, S","effect":{"text":"Share 700 HP of healing"}},{"id":"mass-healing-word","name":"Mass Healing Word","level":3,"school":"Abjuration","classes":["bard","cleric"],"time":"Bonus Action","range":"60 ft","components":"V","duration":"Instantaneous","concentration":false,"text":"Up to six creatures of your choice that you can see within range regain Hit Points equal to 2d4 plus your spellcasting ability modifier.\nUsing a Higher-Level Spell Slot. The healing increases by 1d4 for each spell slot level above 3.","effect":{"dice":"2d4","type":"healing","addMod":true},"higher":"The healing increases by 1d4 for each spell slot level above 3.","upcast":{"dice":"1d4"},"componentsShort":"V"},{"id":"mass-suggestion","name":"Mass Suggestion","level":6,"school":"Enchantment","classes":["bard","sorcerer","wizard"],"time":"Action","range":"60 ft","components":"V, M (a snake’s tongue)","duration":"24 hours","concentration":false,"text":"You suggest a course of activity—described in no more than 25 words—to twelve or fewer creatures you can see within range that can hear and understand you. The suggestion must sound achievable and not involve anything that would obviously deal damage to any of the targets or their allies. For example, you could say, “Walk to the village down that road, and help the villagers there harvest crops until sunset.” Or you could say, “Now is not the time for violence. Drop your weapons, and dance! Stop in an hour.”\nEach target must succeed on a Wisdom saving throw or have the Charmed condition for the duration or until you or your allies deal damage to the target. Each Charmed target pursues the suggestion to the best of its ability. The suggested activity can continue for the entire duration, but if the suggested activity can be completed in a shorter time, the spell ends for a target upon completing it.\nUsing a Higher-Level Spell Slot. The duration is longer with a spell slot of level 7 (10 days), 8 (30 days), or 9 (366 days).","save":"wis","higher":"The duration is longer with a spell slot of level 7 (10 days), 8 (30 days), or 9 (366 days).","componentsShort":"V, M","effect":{"text":"Up to 12 creatures follow a suggestion"}},{"id":"maze","name":"Maze","level":8,"school":"Conjuration","classes":["wizard"],"time":"Action","range":"60 ft","components":"V, S","duration":"Up to 10 minutes","concentration":true,"text":"You banish a creature that you can see within range into a labyrinthine demiplane. The target remains there for the duration or until it escapes the maze.\nThe target can take a Study action to try to escape. When it does so, it makes a DC 20 Intelligence (Investigation) check. If it succeeds, it escapes, and the spell ends.\nWhen the spell ends, the target reappears in the space it left or, if that space is occupied, in the nearest unoccupied space.","concDuration":"10 min","componentsShort":"V, S","effect":{"text":"Banish a creature that you can see within range into a…"}},{"id":"meld-into-stone","name":"Meld into Stone","level":3,"school":"Transmutation","classes":["cleric","druid","ranger"],"time":"Action","range":"Touch","components":"V, S","duration":"8 hours","concentration":false,"text":"You step into a stone object or surface large enough to fully contain your body, merging yourself and your equipment with the stone for the duration.\nYou must touch the stone to do so. Nothing of your presence remains visible or otherwise detectable by nonmagical senses.\nWhile merged with the stone, you can’t see what occurs outside it, and any Wisdom (Perception) checks you make to hear sounds outside it are made with Disadvantage. You remain aware of the passage of time and can cast spells on yourself while merged in the stone. You can use 5 ft of movement to leave the stone where you entered it, which ends the spell. You otherwise can’t move.\nMinor physical damage to the stone doesn’t harm you, but its partial destruction or a change in its shape (to the extent that you no longer fit within it) expels you and deals 6d6 Force damage to you. The stone’s complete destruction (or transmutation into a different substance) expels you and deals 50 Force damage to you. If expelled, you move into an unoccupied space closest to where you first entered and have the Prone condition.","ritual":true,"effect":{"dice":"6d6","type":"force"},"componentsShort":"V, S"},{"id":"mending","name":"Mending","level":0,"school":"Transmutation","classes":["bard","cleric","druid","sorcerer","wizard"],"time":"1 minute","range":"Touch","components":"V, S, M (two lodestones)","duration":"Instantaneous","concentration":false,"text":"This spell repairs a single break or tear in an object you touch, such as a broken chain link, two halves of a broken key, a torn cloak, or a leaking wineskin. As long as the break or tear is no larger than 1 ft in any dimension, you mend it, leaving no trace of the former damage.\nThis spell can physically repair a magic item, but it can’t restore magic to such an object.","componentsShort":"V, S, M","effect":{"text":"This spell repairs a single break or tear in an object you…"}},{"id":"message","name":"Message","level":0,"school":"Transmutation","classes":["bard","druid","sorcerer","wizard"],"time":"Action","range":"120 ft","components":"S, M (a copper wire)","duration":"1 round","concentration":false,"text":"You point toward a creature within range and whisper a message. The target (and only the target) hears the message and can reply in a whisper that only you can hear.\nYou can cast this spell through solid objects if you are familiar with the target and know it is beyond the barrier. Magical silence; 1 ft of stone, metal, or wood; or a thin sheet of lead blocks the spell.","componentsShort":"S, M","effect":{"text":"Whispered message and reply"}},{"id":"meteor-swarm","name":"Meteor Swarm","level":9,"school":"Evocation","classes":["sorcerer","wizard"],"time":"Action","range":"1 mile","components":"V, S","duration":"Instantaneous","concentration":false,"text":"Blazing orbs of fire plummet to the ground at four different points you can see within range. Each creature in a 40-ft-radius Sphere centered on each of those points makes a Dexterity saving throw. A creature takes 20d6 Fire damage and 20d6 Bludgeoning damage on a failed save or half as much damage on a successful one. A creature in the area of more than one fiery Sphere is affected only once.\nA nonmagical object that isn’t being worn or carried also takes the damage if it’s in the spell’s area, and the object starts burning if it’s flammable.","save":"dex","effect":{"dice":"20d6","type":"fire + 20d6 bludgeoning","addMod":false,"text":"20d6 fire + 20d6 bludgeoning, four 40-ft spheres"},"componentsShort":"V, S"},{"id":"mind-blank","name":"Mind Blank","level":8,"school":"Abjuration","classes":["bard","wizard"],"time":"Action","range":"Touch","components":"V, S","duration":"24 hours","concentration":false,"text":"Until the spell ends, one willing creature you touch has Immunity to Psychic damage and the Charmed condition. The target is also unaffected by anything that would sense its emotions or alignment, read its thoughts, or magically detect its location, and no spell—not even Wish—can gather information about the target, observe it remotely, or control its mind.","componentsShort":"V, S","effect":{"text":"Until the spell ends, one willing creature you touch has…"}},{"id":"mind-spike","name":"Mind Spike","level":2,"school":"Divination","classes":["sorcerer","warlock","wizard"],"time":"Action","range":"120 ft","components":"S","duration":"Up to 1 hour","concentration":true,"text":"You drive a spike of psionic energy into the mind of one creature you can see within range. The target makes a Wisdom saving throw, taking 3d8 Psychic damage on a failed save or half as much damage on a successful one. On a failed save, you also always know the target’s location until the spell ends, but only while the two of you are on the same plane of existence. While you have this knowledge, the target can’t become hidden from you, and if it has the Invisible condition, it gains no benefit from that condition against you.\nUsing a Higher-Level Spell Slot. The damage increases by 1d8 for each spell slot level above 2.","concDuration":"1 hour","save":"wis","effect":{"dice":"3d8","type":"psychic"},"higher":"The damage increases by 1d8 for each spell slot level above 2.","upcast":{"dice":"1d8"},"componentsShort":"S"},{"id":"minor-illusion","name":"Minor Illusion","level":0,"school":"Illusion","classes":["bard","sorcerer","warlock","wizard"],"time":"Action","range":"30 ft","components":"S, M (a bit of fleece)","duration":"1 minute","concentration":false,"text":"You create a sound or an image of an object within range that lasts for the duration. See the descriptions below for the effects of each. The illusion ends if you cast this spell again.\nIf a creature takes a Study action to examine the sound or image, the creature can determine that it is an illusion with a successful Intelligence (Investigation) check against your spell save DC. If a creature discerns the illusion for what it is, the illusion becomes faint to the creature.\nSound. If you create a sound, its volume can range from a whisper to a scream. It can be your voice, someone else’s voice, a lion’s roar, a beating of drums, or any other sound you choose. The sound continues unabated throughout the duration, or you can make discrete sounds at different times before the spell ends.\nImage. If you create an image of an object—such as a chair, muddy footprints, or a small chest—it must be no larger than a 5-ft Cube. The image can’t create sound, light, smell, or any other sensory effect. Physical interaction with the image reveals it to be an illusion, since things can pass through it.","componentsShort":"S, M","effect":{"text":"Sound or image"}},{"id":"mirage-arcane","name":"Mirage Arcane","level":7,"school":"Illusion","classes":["bard","druid","wizard"],"time":"10 minutes","range":"Sight","components":"V, S","duration":"10 days","concentration":false,"text":"You make terrain in an area up to 1 mile square look, sound, smell, and even feel like some other sort of terrain. Open fields or a road could be made to resemble a swamp, hill, crevasse, or some other rough or impassable terrain. A pond can be made to seem like a grassy meadow, a precipice like a gentle slope, or a rock-strewn gully like a wide and smooth road.\nSimilarly, you can alter the appearance of structures or add them where none are present. The spell doesn’t disguise, conceal, or add creatures.\nThe illusion includes audible, visual, tactile, and olfactory elements, so it can turn clear ground into Difficult Terrain (or vice versa) or otherwise impede movement through the area. Any piece of the illusory terrain (such as a rock or stick) that is removed from the spell’s area disappears immediately.\nCreatures with Truesight can see through the illusion to the terrain’s true form; however, all other elements of the illusion remain, so while the creature is aware of the illusion’s presence, the creature can still physically interact with the illusion.","componentsShort":"V, S","effect":{"text":"Make terrain in an area up to 1 mile square look, sound,…"}},{"id":"mirror-image","name":"Mirror Image","level":2,"school":"Illusion","classes":["bard","sorcerer","warlock","wizard"],"time":"Action","range":"Self","components":"V, S","duration":"1 minute","concentration":false,"text":"Three illusory duplicates of yourself appear in your space. Until the spell ends, the duplicates move with you and mimic your actions, shifting position so it’s impossible to track which image is real.\nEach time a creature hits you with an attack roll during the spell’s duration, roll a d6 for each of your remaining duplicates. If any of the d6s rolls a 3 or higher, one of the duplicates is hit instead of you, and the duplicate is destroyed. The duplicates otherwise ignore all other damage and effects. The spell ends when all three duplicates are destroyed. A creature is unaffected by this spell if it has the Blinded condition, Blindsight, or Truesight.","componentsShort":"V, S","effect":{"text":"3 illusory duplicates"}},{"id":"mislead","name":"Mislead","level":5,"school":"Illusion","classes":["bard","warlock","wizard"],"time":"Action","range":"Self","components":"S","duration":"Up to 1 hour","concentration":true,"text":"You gain the Invisible condition at the same time that an illusory double of you appears where you are standing. The double lasts for the duration, but the invisibility ends immediately after you make an attack roll, deal damage, or cast a spell.\nAs a Magic action, you can move the illusory double up to twice your Speed and make it gesture, speak, and behave in whatever way you choose. It is intangible and invulnerable.\nYou can see through its eyes and hear through its ears as if you were located where it is.","concDuration":"1 hour","componentsShort":"S","effect":{"text":"Gain the Invisible condition at the same time that an…"}},{"id":"misty-step","name":"Misty Step","level":2,"school":"Conjuration","classes":["sorcerer","warlock","wizard"],"time":"Bonus Action","range":"Self","components":"V","duration":"Instantaneous","concentration":false,"text":"Briefly surrounded by silvery mist, you teleport up to 30 ft to an unoccupied space you can see.","componentsShort":"V","effect":{"text":"Teleport 30 ft"}},{"id":"modify-memory","name":"Modify Memory","level":5,"school":"Enchantment","classes":["bard","wizard"],"time":"Action","range":"30 ft","components":"V, S","duration":"Up to 1 minute","concentration":true,"text":"You attempt to reshape another creature’s memories. One creature that you can see within range makes a Wisdom saving throw. If you are fighting the creature, it has Advantage on the save. On a failed save, the target has the Charmed condition for the duration. While Charmed in this way, the target also has the Incapacitated condition and is unaware of its surroundings, though it can hear you. If it takes any damage or is targeted by another spell, this spell ends, and no memories are modified.\nWhile this charm lasts, you can affect the target’s memory of an event that it experienced within the last 24 hours and that lasted no more than 10 minutes. You can permanently eliminate all memory of the event, allow the target to recall the event with perfect clarity, change its memory of the event’s details, or create a memory of some other event. You must speak to the target to describe how its memories are affected, and it must be able to understand your language for the modified memories to take root. Its mind fills in any gaps in the details of your description. If the spell ends before you finish describing the modified memories, the creature’s memory isn’t altered. Otherwise, the modified memories take hold when the spell ends.\nA modified memory doesn’t necessarily affect how a creature behaves, particularly if the memory contradicts the creature’s natural inclinations, alignment, or beliefs. An illogical modified memory, such as a false memory of how much the creature enjoyed swimming in acid, is dismissed as a bad dream. The GM might deem a modified memory too nonsensical to affect a creature.\nA Remove Curse or Greater Restoration spell cast on the target restores the creature’s true memory.\nUsing a Higher-Level Spell Slot. You can alter the target’s memories of an event that took place up to 7 days ago (level 6 spell slot), 30 days ago (level 7 spell slot), 365 days ago (level 8 spell slot), or any time in the creature’s past (level 9 spell slot).","concDuration":"1 min","save":"wis","higher":"You can alter the target’s memories of an event that took place up to 7 days ago (level 6 spell slot), 30 days ago (level 7 spell slot), 365 days ago (level 8 spell slot), or any time in the creature’s past (level 9 spell slot).","componentsShort":"V, S","effect":{"text":"Attempt to reshape another creature’s memories"}},{"id":"moonbeam","name":"Moonbeam","level":2,"school":"Evocation","classes":["druid"],"time":"Action","range":"120 ft","components":"V, S, M (a moonseed leaf)","duration":"Up to 1 minute","concentration":true,"text":"A silvery beam of pale light shines down in a 5-ft-radius, 40-ft-high Cylinder centered on a point within range. Until the spell ends, Dim Light fills the Cylinder, and you can take a Magic action on later turns to move the Cylinder up to 60 ft.\nWhen the Cylinder appears, each creature in it makes a Constitution saving throw. On a failed save, a creature takes 2d10 Radiant damage, and if the creature is shape-shifted (as a result of the Polymorph spell, for example), it reverts to its true form and can’t shape-shift until it leaves the Cylinder.\nOn a successful save, a creature takes half as much damage only. A creature also makes this save when the spell’s area moves into its space and when it enters the spell’s area or ends its turn there. A creature makes this save only once per turn.\nUsing a Higher-Level Spell Slot. The damage increases by 1d10 for each spell slot level above 2.","concDuration":"1 min","save":"con","effect":{"dice":"2d10","type":"radiant"},"higher":"The damage increases by 1d10 for each spell slot level above 2.","upcast":{"dice":"1d10"},"componentsShort":"V, S, M"},{"id":"move-earth","name":"Move Earth","level":6,"school":"Transmutation","classes":["druid","sorcerer","wizard"],"time":"Action","range":"120 ft","components":"V, S, M (a miniature shovel)","duration":"Up to 2 hours","concentration":true,"text":"Choose an area of terrain no larger than 40 ft on a side within range. You can reshape dirt, sand, or clay in the area in any manner you choose for the duration. You can raise or lower the area’s elevation, create or fill in a trench, erect or flatten a wall, or form a pillar. The extent of any such changes can’t exceed half the area’s largest dimension. For example, if you affect a 40-ft square, you can create a pillar up to 20 ft high, raise or lower the square’s elevation by up to 20 ft, dig a trench up to 20 ft deep, and so on. It takes 10 minutes for these changes to complete. Because the terrain’s transformation occurs slowly, creatures in the area can’t usually be trapped or injured by the ground’s movement.\nAt the end of every 10 minutes you spend concentrating on the spell, you can choose a new area of terrain to affect within range.\nThis spell can’t manipulate natural stone or stone construction. Rocks and structures shift to accommodate the new terrain. If the way you shape the terrain would make a structure unstable, it might collapse.\nSimilarly, this spell doesn’t directly affect plant growth. The moved earth carries any plants along with it.","concDuration":"2 hours","componentsShort":"V, S, M","effect":{"text":"Choose an area of terrain no larger than 40 ft on a side…"}},{"id":"nondetection","name":"Nondetection","level":3,"school":"Abjuration","classes":["bard","ranger","wizard"],"time":"Action","range":"Touch","components":"V, S, M (a pinch of diamond dust worth 25+ GP, which the spell consumes)","duration":"8 hours","concentration":false,"text":"For the duration, you hide a target that you touch from Divination spells. The target can be a willing creature, or it can be a place or an object no larger than 10 ft in any dimension. The target can’t be targeted by any Divination spell or perceived through magical scrying sensors.","componentsShort":"V, S, M","effect":{"text":"For the duration, you hide a target that you touch from…"}},{"id":"passwall","name":"Passwall","level":5,"school":"Transmutation","classes":["wizard"],"time":"Action","range":"30 ft","components":"V, S, M (a pinch of sesame seeds)","duration":"1 hour","concentration":false,"text":"A passage appears at a point that you can see on a wooden, plaster, or stone surface (such as a wall, ceiling, or floor) within range and lasts for the duration. You choose the opening’s dimensions: up to 5 ft wide, 8 ft tall, and 20 ft deep. The passage creates no instability in a structure surrounding it.\nWhen the opening disappears, any creatures or objects still in the passage created by the spell are safely ejected to an unoccupied space nearest to the surface on which you cast the spell.","componentsShort":"V, S, M","effect":{"text":"A passage appears at a point that you can see on a wooden,…"}},{"id":"pass-without-trace","name":"Pass without Trace","level":2,"school":"Abjuration","classes":["druid","ranger"],"time":"Action","range":"Self","components":"V, S, M (ashes from burned mistletoe)","duration":"Up to 1 hour","concentration":true,"text":"You radiate a concealing aura in a 30-ft Emanation for the duration. While in the aura, you and each creature you choose have a +10 bonus to Dexterity (Stealth) checks and leave no tracks.","concDuration":"1 hour","componentsShort":"V, S, M","effect":{"text":"+10 to DEX (Stealth) for allies near you"}},{"id":"phantasmal-force","name":"Phantasmal Force","level":2,"school":"Illusion","classes":["bard","sorcerer","wizard"],"time":"Action","range":"60 ft","components":"V, S, M (a bit of fleece)","duration":"Up to 1 minute","concentration":true,"text":"You attempt to craft an illusion in the mind of a creature you can see within range. The target makes an Intelligence saving throw. On a failed save, you create a phantasmal object, creature, or other phenomenon that is no larger than a 10-ft Cube and that is perceivable only to the target for the duration. The phantasm includes sound, temperature, and other stimuli.\nThe target can take a Study action to examine the phantasm with an Intelligence (Investigation) check against your spell save DC. If the check succeeds, the target realizes that the phantasm is an illusion, and the spell ends.\nWhile affected by the spell, the target treats the phantasm as if it were real and rationalizes any illogical outcomes from interacting with it. For example, if the target steps through a phantasmal bridge and survives the fall, it believes the bridge exists and something else caused it to fall.\nAn affected target can even take damage from the illusion if the phantasm represents a dangerous creature or hazard. On each of your turns, such a phantasm can deal 2d8 Psychic damage to the target if it is in the phantasm’s area or within 5 ft of the phantasm. The target perceives the damage as a type appropriate to the illusion.","concDuration":"1 min","save":"int","effect":{"dice":"2d8","type":"psychic"},"componentsShort":"V, S, M"},{"id":"phantasmal-killer","name":"Phantasmal Killer","level":4,"school":"Illusion","classes":["bard","wizard"],"time":"Action","range":"120 ft","components":"V, S","duration":"Up to 1 minute","concentration":true,"text":"You tap into the nightmares of a creature you can see within range and create an illusion of its deepest fears, visible only to that creature. The target makes a Wisdom saving throw. On a failed save, the target takes 4d10 Psychic damage and has Disadvantage on ability checks and attack rolls for the duration. On a successful save, the target takes half as much damage, and the spell ends.\nFor the duration, the target makes a Wisdom saving throw at the end of each of its turns. On a failed save, it takes the Psychic damage again. On a successful save, the spell ends.\nUsing a Higher-Level Spell Slot. The damage increases by 1d10 for each spell slot level above 4.","concDuration":"1 min","save":"wis","effect":{"dice":"4d10","type":"psychic"},"higher":"The damage increases by 1d10 for each spell slot level above 4.","upcast":{"dice":"1d10"},"componentsShort":"V, S"},{"id":"phantom-steed","name":"Phantom Steed","level":3,"school":"Illusion","classes":["wizard"],"time":"1 minute","range":"30 ft","components":"V, S","duration":"1 hour","concentration":false,"text":"A Large, quasi-real, horselike creature appears on the ground in an unoccupied space of your choice within range. You decide the creature’s appearance, and it is equipped with a saddle, bit, and bridle. Any of the equipment created by the spell vanishes in a puff of smoke if it is carried more than 10 ft away from the steed.\nFor the duration, you or a creature you choose can ride the steed. The steed uses the Riding Horse stat block (see “Monsters”), except it has a Speed of 100 ft and can travel 13 miles in an hour. When the spell ends, the steed gradually fades, giving the rider 1 minute to dismount. The spell ends early if the steed takes any damage.","ritual":true,"componentsShort":"V, S","effect":{"text":"A Large, quasi-real, horselike creature appears on the ground…"}},{"id":"planar-ally","name":"Planar Ally","level":6,"school":"Conjuration","classes":["cleric"],"time":"10 minutes","range":"60 ft","components":"V, S","duration":"Instantaneous","concentration":false,"text":"You beseech an otherworldly entity for aid. The being must be known to you: a god, a demon prince, or some other being of cosmic power. That entity sends a Celestial, an Elemental, or a Fiend loyal to it to aid you, making the creature appear in an unoccupied space within range. If you know a specific creature’s name, you can speak that name when you cast this spell to request that creature, though you might get a different creature anyway (GM’s choice).\nWhen the creature appears, it is under no compulsion to behave a particular way. You can ask it to perform a service in exchange for payment, but it isn’t obliged to do so. The requested task could range from simple (fly us across the chasm, or help us fight a battle) to complex (spy on our enemies, or protect us during our foray into the dungeon). You must be able to communicate with the creature to bargain for its services.\nPayment can take a variety of forms. A Celestial might require a sizable donation of gold or magic items to an allied temple, while a Fiend might demand a living sacrifice or a gift of treasure. Some creatures might exchange their service for a quest undertaken by you.\nA task that can be measured in minutes requires a payment worth 100 GP per minute. A task measured in hours requires 1,000 GP per hour. And a task measured in days (up to 10 days) requires 10,000 GP per day. The GM can adjust these payments based on the circumstances under which you cast the spell. If the task is aligned with the creature’s ethos, the payment might be halved or even waived.\nNonhazardous tasks typically require only half the suggested payment, while especially dangerous tasks might require a greater gift. Creatures rarely accept tasks that seem suicidal.\nAfter the creature completes the task, or when the agreed-upon duration of service expires, the creature returns to its home plane after reporting back to you if possible. If you are unable to agree on a price for the creature’s service, the creature immediately returns to its home plane.","componentsShort":"V, S","effect":{"text":"Beseech an otherworldly entity for aid"}},{"id":"planar-binding","name":"Planar Binding","level":5,"school":"Abjuration","classes":["bard","cleric","druid","warlock","wizard"],"time":"1 hour","range":"60 ft","components":"V, S, M (a jewel worth 1,000+ GP, which the spell consumes)","duration":"24 hours","concentration":false,"text":"You attempt to bind a Celestial, an Elemental, a Fey, or a Fiend to your service. The creature must be within range for the entire casting of the spell.\n(Typically, the creature is first summoned into the center of the inverted version of the Magic Circle spell to trap it while this spell is cast.) At the completion of the casting, the target must succeed on a Charisma saving throw or be bound to serve you for the duration. If the creature was summoned or created by another spell, that spell’s duration is extended to match the duration of this spell. A bound creature must follow your commands to the best of its ability. You might command the creature to accompany you on an adventure, to guard a location, or to deliver a message. If the creature is Hostile, it strives to twist your commands to achieve its own objectives. If the creature carries out your commands completely before the spell ends, it travels to you to report this fact if you are on the same plane of existence. If you are on a different plane, it returns to the place where you bound it and remains there until the spell ends.\nUsing a Higher-Level Spell Slot. The duration increases with a spell slot of level 6 (10 days), 7 (30 days), 8 (180 days), and 9 (366 days).","save":"cha","higher":"The duration increases with a spell slot of level 6 (10 days), 7 (30 days), 8 (180 days), and 9 (366 days).","componentsShort":"V, S, M","effect":{"text":"Attempt to bind a Celestial, an Elemental, a Fey, or a Fiend…"}},{"id":"plane-shift","name":"Plane Shift","level":7,"school":"Conjuration","classes":["cleric","druid","sorcerer","warlock","wizard"],"time":"Action","range":"Touch","components":"V, S, M (a forked, metal rod worth 250+ GP and attuned to a plane of existence)","duration":"Instantaneous","concentration":false,"text":"You and up to eight willing creatures who link hands in a circle are transported to a different plane of existence. You can specify a target destination in general terms, such as a specific city on the Elemental Plane of Fire or palace on the second level of the Nine Hells, and you appear in or near that destination, as determined by the GM.\nAlternatively, if you know the sigil sequence of a teleportation circle on another plane of existence, this spell can take you to that circle. If the teleportation circle is too small to hold all the creatures you transported, they appear in the closest unoccupied spaces next to the circle.","componentsShort":"V, S, M","effect":{"text":"Travel to another plane (up to 9 creatures)"}},{"id":"plant-growth","name":"Plant Growth","level":3,"school":"Transmutation","classes":["bard","druid","ranger"],"time":"Action (Overgrowth) or 8 hours (Enrichment)","range":"150 ft","components":"V, S","duration":"Instantaneous","concentration":false,"text":"This spell channels vitality into plants. The casting time you use determines whether the spell has the Overgrowth or the Enrichment effect below.\nOvergrowth. Choose a point within range. All normal plants in a 100-ft-radius Sphere centered on that point become thick and overgrown. A creature moving through that area must spend 4 ft of movement for every 1 ft it moves. You can exclude one or more areas of any size within the spell’s area from being affected.\nEnrichment. All plants in a half-mile radius centered on a point within range become enriched for 365 days. The plants yield twice the normal amount of food when harvested. They can benefit from only one Plant Growth per year.","componentsShort":"V, S","effect":{"text":"This spell channels vitality into plants"}},{"id":"poison-spray","name":"Poison Spray","level":0,"school":"Necromancy","classes":["druid","sorcerer","warlock","wizard"],"time":"Action","range":"30 ft","components":"V, S","duration":"Instantaneous","concentration":false,"text":"You spray toxic mist at a creature within range. Make a ranged spell attack against the target. On a hit, the target takes 1d12 Poison damage.\nCantrip Upgrade. The damage increases by 1d12 when you reach levels 5 (2d12), 11 (3d12), and 17 (4d12).","attack":"ranged","effect":{"dice":"1d12","type":"poison"},"componentsShort":"V, S"},{"id":"polymorph","name":"Polymorph","level":4,"school":"Transmutation","classes":["bard","druid","sorcerer","wizard"],"time":"Action","range":"60 ft","components":"V, S, M (a caterpillar cocoon)","duration":"Up to 1 hour","concentration":true,"text":"You attempt to transform a creature that you can see within range into a Beast. The target must succeed on a Wisdom saving throw or shape-shift into a Beast form for the duration. That form can be any Beast you choose that has a Challenge Rating equal to or less than the target’s (or the target’s level if it doesn’t have a Challenge Rating). The target’s game statistics are replaced by the stat block of the chosen Beast, but the target retains its alignment, personality, creature type, Hit Points, and Hit Point Dice. See the “Animals” section of “Monsters” for a sample of Beast stat blocks.\nThe target gains a number of Temporary Hit Points equal to the Hit Points of the Beast form.\nThese Temporary Hit Points vanish if any remain when the spell ends. The spell ends early on the target if it has no Temporary Hit Points left. The target is limited in the actions it can perform by the anatomy of its new form, and it can’t speak or cast spells.\nThe target’s gear melds into the new form. The creature can’t use or otherwise benefit from any of that equipment.","concDuration":"1 hour","save":"wis","componentsShort":"V, S, M","effect":{"text":"Turn a creature into a Beast"}},{"id":"power-word-heal","name":"Power Word Heal","level":9,"school":"Enchantment","classes":["bard","cleric"],"time":"Action","range":"60 ft","components":"V","duration":"Instantaneous","concentration":false,"text":"A wave of healing energy washes over one creature you can see within range. The target regains all its Hit Points. If the creature has the Charmed, Frightened, Paralyzed, Poisoned, or Stunned condition, the condition ends. If the creature has the Prone condition, it can use its Reaction to stand up.","componentsShort":"V","effect":{"text":"A wave of healing energy washes over one creature you can see…"}},{"id":"power-word-kill","name":"Power Word Kill","level":9,"school":"Enchantment","classes":["bard","sorcerer","warlock","wizard"],"time":"Action","range":"60 ft","components":"V","duration":"Instantaneous","concentration":false,"text":"You compel one creature you can see within range to die. If the target has 100 Hit Points or fewer, it dies. Otherwise, it takes 12d12 Psychic damage.","effect":{"dice":"12d12","type":"psychic","addMod":false,"text":"Dies at 100 HP or fewer, else 12d12"},"componentsShort":"V"},{"id":"power-word-stun","name":"Power Word Stun","level":8,"school":"Enchantment","classes":["bard","sorcerer","warlock","wizard"],"time":"Action","range":"60 ft","components":"V","duration":"Instantaneous","concentration":false,"text":"You overwhelm the mind of one creature you can see within range. If the target has 150 Hit Points or fewer, it has the Stunned condition. Otherwise, its Speed is 0 until the start of your next turn.\nThe Stunned target makes a Constitution saving throw at the end of each of its turns, ending the condition on itself on a success.","save":"con","componentsShort":"V","effect":{"text":"Stunned (150 HP or fewer)"}},{"id":"prayer-of-healing","name":"Prayer of Healing","level":2,"school":"Abjuration","classes":["cleric","paladin"],"time":"10 minutes","range":"30 ft","components":"V","duration":"Instantaneous","concentration":false,"text":"Up to five creatures of your choice who remain within range for the spell’s entire casting gain the benefits of a Short Rest and also regain 2d8 Hit Points. A creature can’t be affected by this spell again until that creature finishes a Long Rest.\nUsing a Higher-Level Spell Slot. The healing increases by 1d8 for each spell slot level above 2.","higher":"The healing increases by 1d8 for each spell slot level above 2.","componentsShort":"V","effect":{"dice":"2d8","addMod":true,"type":"healing"}},{"id":"prestidigitation","name":"Prestidigitation","level":0,"school":"Transmutation","classes":["bard","sorcerer","warlock","wizard"],"time":"Action","range":"10 ft","components":"V, S","duration":"Up to 1 hour","concentration":false,"text":"You create a magical effect within range. Choose the effect from the options below. If you cast this spell multiple times, you can have up to three of its non-instantaneous effects active at a time.\nSensory Effect. You create an instantaneous, harmless sensory effect, such as a shower of sparks, a puff of wind, faint musical notes, or an odd odor.\nFire Play. You instantaneously light or snuff out a candle, a torch, or a small campfire.\nClean or Soil. You instantaneously clean or soil an object no larger than 1 cubic foot.\nMinor Sensation. You chill, warm, or flavor up to 1 cubic foot of nonliving material for 1 hour.\nMagic Mark. You make a color, a small mark, or a symbol appear on an object or a surface for 1 hour.\nMinor Creation. You create a nonmagical trinket or an illusory image that can fit in your hand. It lasts until the end of your next turn. A trinket can deal no damage and has no monetary worth.","componentsShort":"V, S","effect":{"text":"Minor magical trick"}},{"id":"prismatic-spray","name":"Prismatic Spray","level":7,"school":"Evocation","classes":["bard","sorcerer","wizard"],"time":"Action","range":"Self","components":"V, S","duration":"Instantaneous","concentration":false,"text":"Eight rays of light flash from you in a 60-ft Cone.\nEach creature in the Cone makes a Dexterity saving throw. For each target, roll 1d8 to determine which color ray affects it, consulting the Prismatic Rays table.\nPrismatic Rays 1d8 Ray Red. Failed Save: 12d6 Fire damage. Successful Save: Half as much damage.\nOrange. Failed Save: 12d6 Acid damage. Successful Save: Half as much damage.\nYellow. Failed Save: 12d6 Lightning damage. Successful Save: Half as much damage.\nGreen. Failed Save: 12d6 Poison damage. Successful Save: Half as much damage.\n1d8 Ray Blue. Failed Save: 12d6 Cold damage. Successful Save: Half as much damage.\nIndigo. Failed Save: The target has the Restrained condition and makes a Constitution saving throw at the end of each of its turns. If it successfully saves three times, the condition ends. If it fails three times, it has the Petrified condition until it is freed by an effect like the Greater Restoration spell. The successes and failures needn’t be consecutive; keep track of both until the target collects three of a kind.\nViolet. Failed Save: The target has the Blinded condition and makes a Wisdom saving throw at the start of your next turn. On a successful save, the condition ends. On a failed save, the condition ends, and the creature teleports to another plane of existence (GM’s choice).\nSpecial. The target is struck by two rays. Roll twice, rerolling any 8.","save":"dex","effect":{"dice":"12d6","type":"fire"},"componentsShort":"V, S"},{"id":"prismatic-wall","name":"Prismatic Wall","level":9,"school":"Abjuration","classes":["bard","wizard"],"time":"Action","range":"60 ft","components":"V, S","duration":"10 minutes","concentration":false,"text":"A shimmering, multicolored plane of light forms a vertical opaque wall—up to 90 ft long, 30 ft high, and 1 inch thick—centered on a point within range. Alternatively, you shape the wall into a globe up to 30 ft in diameter centered on a point within range. The wall lasts for the duration. If you position the wall in a space occupied by a creature, the spell ends instantly without effect.\nThe wall sheds Bright Light within 100 ft and Dim Light for an additional 100 ft. You and creatures you designate when you cast the spell can pass through and be near the wall without harm. If another creature that can see the wall moves within 20 ft of it or starts its turn there, the creature must succeed on a Constitution saving throw or have the Blinded condition for 1 minute.\nThe wall consists of seven layers, each with a different color. When a creature reaches into or passes through the wall, it does so one layer at a time through all the layers. Each layer forces the creature to make a Dexterity saving throw or be affected by that layer’s properties as described in the Prismatic Layers table.\nThe wall, which has AC 10, can be destroyed one layer at a time, in order from red to violet, by means specific to each layer. If a layer is destroyed, it is gone for the duration. Antimagic Field has no effect on the wall, and Dispel Magic can affect only the violet layer.\nPrismatic Layers Order\nEffects Red. Failed Save: 12d6 Fire damage. Successful Save: Half as much damage. Additional Effects:\nNonmagical ranged attacks can’t pass through this layer, which is destroyed if it takes at least 25 Cold damage.\nOrange. Failed Save: 12d6 Acid damage. Successful Save: Half as much damage. Additional Effects: Magical ranged attacks can’t pass through this layer, which is destroyed by a strong wind (such as the one created by Gust of Wind).\nYellow. Failed Save: 12d6 Lightning damage.\nSuccessful Save: Half as much damage. Additional Effects: The layer is destroyed if it takes at least 60 Force damage.\nGreen. Failed Save: 12d6 Poison damage. Successful Save: Half as much damage. Additional Effects: A Passwall spell, or another spell of equal or greater level that can open a portal on a solid surface, destroys this layer.\nBlue. Failed Save: 12d6 Cold damage. Successful Save: Half as much damage. Additional Effects: The layer is destroyed if it takes at least 25 Fire damage.\nIndigo. Failed Save: The target has the Restrained condition and makes a Constitution saving throw at the end of each of its turns. If it successfully saves three times, the condition ends. If it fails three times, it has the Petrified condition until it is freed by an effect like the Greater Restoration spell. The successes and failures needn’t be consecutive; keep track of both until the target collects three of a kind.\nAdditional Effects: Spells can’t be cast through this layer, which is destroyed by Bright Light shed by the Daylight spell.\nViolet. Failed Save: The target has the Blinded condition and makes a Wisdom saving throw at the start of your next turn. On a successful save, the condition ends. On a failed save, the condition ends, and the creature teleports to another plane of existence (GM’s choice).\nAdditional Effects: This layer is destroyed by Dispel Magic.","save":"con","effect":{"dice":"12d6","type":"fire"},"componentsShort":"V, S"},{"id":"private-sanctum","name":"Private Sanctum","level":4,"school":"Abjuration","classes":["wizard"],"time":"10 minutes","range":"120 ft","components":"V, S, M (a thin sheet of lead)","duration":"24 hours","concentration":false,"text":"You make an area within range magically secure.\nThe area is a Cube that can be as small as 5 ft to as large as 100 ft on each side. The spell lasts for the duration.\nWhen you cast the spell, you decide what sort of security the spell provides, choosing any of the following properties:\n• Sound can’t pass through the barrier at the edge of the warded area.\n• The barrier of the warded area appears dark and foggy, preventing vision (including Darkvision) through it.\n• Sensors created by Divination spells can’t appear inside the protected area or pass through the barrier at its perimeter. • Creatures in the area can’t be targeted by Divination spells. • Nothing can teleport into or out of the warded area.\n• Planar travel is blocked within the warded area.\nCasting this spell on the same spot every day for 365 days makes the spell last until dispelled.\nUsing a Higher-Level Spell Slot. You can increase the size of the Cube by 100 ft for each spell slot level above 4.","higher":"You can increase the size of the Cube by 100 ft for each spell slot level above 4.","componentsShort":"V, S, M","effect":{"text":"Make an area within range magically secure"}},{"id":"produce-flame","name":"Produce Flame","level":0,"school":"Conjuration","classes":["druid"],"time":"Bonus Action","range":"Self","components":"V, S","duration":"10 minutes","concentration":false,"text":"A flickering flame appears in your hand and remains there for the duration. While there, the flame emits no heat and ignites nothing, and it sheds Bright Light in a 20-ft radius and Dim Light for an additional 20 ft. The spell ends if you cast it again.\nUntil the spell ends, you can take a Magic action to hurl fire at a creature or an object within 60 ft of you. Make a ranged spell attack. On a hit, the target takes 1d8 Fire damage.\nCantrip Upgrade. The damage increases by 1d8 when you reach levels 5 (2d8), 11 (3d8), and 17 (4d8).","attack":"ranged","effect":{"dice":"1d8","type":"fire"},"componentsShort":"V, S"},{"id":"programmed-illusion","name":"Programmed Illusion","level":6,"school":"Illusion","classes":["bard","wizard"],"time":"Action","range":"120 ft","components":"V, S, M (jade dust worth 25+ GP)","duration":"Until dispelled","concentration":false,"text":"You create an illusion of an object, a creature, or some other visible phenomenon within range that activates when a specific trigger occurs. The illusion is imperceptible until then. It must be no larger than a 30-ft Cube, and you decide when you cast the spell how the illusion behaves and what sounds it makes. This scripted performance can last up to 5 minutes.\nWhen the trigger you specify occurs, the illusion springs into existence and performs in the manner you described. Once the illusion finishes performing, it disappears and remains dormant for 10 minutes, after which the illusion can be activated again. The trigger can be as general or as detailed as you like, though it must be based on visual or audible phenomena that occur within 30 ft of the area.\nFor example, you could create an illusion of yourself to appear and warn off others who attempt to open a trapped door.\nPhysical interaction with the image reveals it to be illusory, since things can pass through it. A creature that takes the Study action to examine the image can determine that it is an illusion with a successful Intelligence (Investigation) check against your spell save DC. If a creature discerns the illusion for what it is, the creature can see through the image, and any noise it makes sounds hollow to the creature.","componentsShort":"V, S, M","effect":{"text":"Create an illusion of an object, a creature, or some other…"}},{"id":"project-image","name":"Project Image","level":7,"school":"Illusion","classes":["bard","wizard"],"time":"Action","range":"500 miles","components":"V, S, M (a statuette of yourself worth 5+ GP)","duration":"Up to 1 day","concentration":true,"text":"You create an illusory copy of yourself that lasts for the duration. The copy can appear at any location within range that you have seen before, regardless of intervening obstacles. The illusion looks and sounds like you, but it is intangible. If the illusion takes any damage, it disappears, and the spell ends.\nYou can see through the illusion’s eyes and hear through its ears as if you were in its space. As a Magic action, you can move it up to 60 ft and make it gesture, speak, and behave in whatever way you choose. It mimics your mannerisms perfectly.\nPhysical interaction with the image reveals it to be illusory, since things can pass through it. A creature that takes the Study action to examine the image can determine that it is an illusion with a successful Intelligence (Investigation) check against your spell save DC. If a creature discerns the illusion for what it is, the creature can see through the image, and any noise it makes sounds hollow to the creature.","concDuration":"1 day","componentsShort":"V, S, M","effect":{"text":"Create an illusory copy of yourself that lasts for the duration"}},{"id":"protection-from-energy","name":"Protection from Energy","level":3,"school":"Abjuration","classes":["cleric","druid","ranger","sorcerer","wizard"],"time":"Action","range":"Touch","components":"V, S","duration":"Up to 1 hour","concentration":true,"text":"For the duration, the willing creature you touch has Resistance to one damage type of your choice: Acid, Cold, Fire, Lightning, or Thunder.","concDuration":"1 hour","componentsShort":"V, S","effect":{"text":"For the duration, the willing creature you touch has…"}},{"id":"protection-from-evil-and-good","name":"Protection from Evil and Good","level":1,"school":"Abjuration","classes":["cleric","druid","paladin","warlock","wizard"],"time":"Action","range":"Touch","components":"V, S, M (a flask of Holy Water worth 25+ GP, which the spell consumes)","duration":"Concentration up to 10 minutes","concentration":true,"text":"Until the spell ends, one willing creature you touch is protected against creatures that are Aberrations, Celestials, Elementals, Fey, Fiends, or Undead.\nThe protection grants several benefits. Creatures of those types have Disadvantage on attack rolls against the target. The target also can’t be possessed by or gain the Charmed or Frightened conditions from them. If the target is already possessed, Charmed, or Frightened by such a creature, the target has Advantage on any new saving throw against the relevant effect.","concDuration":"10 min","componentsShort":"V, S, M","effect":{"text":"Protection from aberrations, fiends, undead and more"}},{"id":"protection-from-poison","name":"Protection from Poison","level":2,"school":"Abjuration","classes":["cleric","druid","paladin","ranger"],"time":"Action","range":"Touch","components":"V, S","duration":"1 hour","concentration":false,"text":"You touch a creature and end the Poisoned condition on it. For the duration, the target has Advantage on saving throws to avoid or end the Poisoned condition, and it has Resistance to Poison damage.","componentsShort":"V, S","effect":{"text":"Touch a creature and end the Poisoned condition on it"}},{"id":"purify-food-and-drink","name":"Purify Food and Drink","level":1,"school":"Transmutation","classes":["cleric","druid","paladin"],"time":"Action","range":"10 ft","components":"V, S","duration":"Instantaneous","concentration":false,"text":"You remove poison and rot from nonmagical food and drink in a 5-ft-radius Sphere centered on a point within range.","ritual":true,"componentsShort":"V, S","effect":{"text":"Remove poison and rot from nonmagical food and drink in a…"}},{"id":"raise-dead","name":"Raise Dead","level":5,"school":"Necromancy","classes":["bard","cleric","paladin"],"time":"1 hour","range":"Touch","components":"V, S, M (a diamond worth 500+ GP, which the spell consumes)","duration":"Instantaneous","concentration":false,"text":"With a touch, you revive a dead creature if it has been dead no longer than 10 days and it wasn’t Undead when it died.\nThe creature returns to life with 1 Hit Point. This spell also neutralizes any poisons that affected the creature at the time of death.\nThis spell closes all mortal wounds, but it doesn’t restore missing body parts. If the creature is lacking body parts or organs integral for its survival— its head, for instance—the spell automatically fails.\nComing back from the dead is an ordeal. The target takes a −4 penalty to D20 Tests. Every time the target finishes a Long Rest, the penalty is reduced by 1 until it becomes 0.","componentsShort":"V, S, M","effect":{"text":"Return a creature dead up to 10 days"}},{"id":"ray-of-enfeeblement","name":"Ray of Enfeeblement","level":2,"school":"Necromancy","classes":["warlock","wizard"],"time":"Action","range":"60 ft","components":"V, S","duration":"Up to 1 minute","concentration":true,"text":"A beam of enervating energy shoots from you toward a creature within range. The target must make a Constitution saving throw. On a successful save, the target has Disadvantage on the next attack roll it makes until the start of your next turn.\nOn a failed save, the target has Disadvantage on Strength-based D20 Tests for the duration. During that time, it also subtracts 1d8 from all its damage rolls. The target repeats the save at the end of each of its turns, ending the spell on a success.","concDuration":"1 min","save":"con","componentsShort":"V, S","effect":{"text":"A beam of enervating energy shoots from you toward a creature…"}},{"id":"ray-of-frost","name":"Ray of Frost","level":0,"school":"Evocation","classes":["sorcerer","wizard"],"time":"Action","range":"60 ft","components":"V, S","duration":"Instantaneous","concentration":false,"text":"A frigid beam of blue-white light streaks toward a creature within range. Make a ranged spell attack against the target. On a hit, it takes 1d8 Cold damage, and its Speed is reduced by 10 ft until the start of your next turn.\nCantrip Upgrade. The damage increases by 1d8 when you reach levels 5 (2d8), 11 (3d8), and 17 (4d8).","attack":"ranged","effect":{"dice":"1d8","type":"cold"},"componentsShort":"V, S"},{"id":"regenerate","name":"Regenerate","level":7,"school":"Transmutation","classes":["bard","cleric","druid"],"time":"1 minute","range":"Touch","components":"V, S, M (a prayer wheel)","duration":"1 hour","concentration":false,"text":"A creature you touch regains 4d8 + 15 Hit Points. For the duration, the target regains 1 Hit Point at the start of each of its turns, and any severed body parts regrow after 2 minutes.","componentsShort":"V, S, M","effect":{"dice":"4d8","type":"healing","addMod":false,"text":"4d8 + 15 HP, then 1 HP per turn; regrow limbs"}},{"id":"ray-of-sickness","name":"Ray of Sickness","level":1,"school":"Necromancy","classes":["sorcerer","wizard"],"time":"Action","range":"60 ft","components":"V, S","duration":"Instantaneous","concentration":false,"text":"You shoot a greenish ray at a creature within range.\nMake a ranged spell attack against the target. On a hit, the target takes 2d8 Poison damage and has the Poisoned condition until the end of your next turn.\nUsing a Higher-Level Spell Slot. The damage increases by 1d8 for each spell slot level above 1.","attack":"ranged","effect":{"dice":"2d8","type":"poison"},"higher":"The damage increases by 1d8 for each spell slot level above 1.","upcast":{"dice":"1d8"},"componentsShort":"V, S"},{"id":"reincarnate","name":"Reincarnate","level":5,"school":"Necromancy","classes":["druid"],"time":"1 hour","range":"Touch","components":"V, S, M (rare oils worth 1,000+ GP, which the spell consumes)","duration":"Instantaneous","concentration":false,"text":"You touch a dead Humanoid or a piece of one. If the creature has been dead no longer than 10 days, the spell forms a new body for it and calls the soul to enter that body. Roll 1d10 and consult the table below to determine the body’s species, or the GM chooses another playable species.\n1d10\nSpecies 1d10\nSpecies Roll again.\nGoliath Dragonborn Halfling Dwarf Human Elf Orc Gnome Tiefling\nThe reincarnated creature makes any choices that a species’ description offers, and the creature recalls its former life. It retains the capabilities it had in its original form, except it loses the traits of its previous species and gains the traits of its new one.","componentsShort":"V, S, M","effect":{"text":"Touch a dead Humanoid or a piece of one"}},{"id":"remove-curse","name":"Remove Curse","level":3,"school":"Abjuration","classes":["cleric","paladin","warlock","wizard"],"time":"Action","range":"Touch","components":"V, S","duration":"Instantaneous","concentration":false,"text":"At your touch, all curses affecting one creature or object end. If the object is a cursed magic item, its curse remains, but the spell breaks its owner’s Attunement to the object so it can be removed or discarded.","componentsShort":"V, S","effect":{"text":"End all curses on a creature or object"}},{"id":"resilient-sphere","name":"Resilient Sphere","level":4,"school":"Abjuration","classes":["wizard"],"time":"Action","range":"30 ft","components":"V, S, M (a glass sphere)","duration":"Up to 1 minute","concentration":true,"text":"A shimmering sphere encloses a Large or smaller creature or object within range. An unwilling creature must succeed on a Dexterity saving throw or be enclosed for the duration.\nNothing—not physical objects, energy, or other spell effects—can pass through the barrier, in or out, though a creature in the sphere can breathe there. The sphere is immune to all damage, and a creature or object inside can’t be damaged by attacks or effects originating from outside, nor can a creature inside the sphere damage anything outside it.\nThe sphere is weightless and just large enough to contain the creature or object inside. An enclosed creature can take an action to push against the sphere’s walls and thus roll the sphere at up to half the creature’s Speed. Similarly, the globe can be picked up and moved by other creatures.\nA Disintegrate spell targeting the globe destroys it without harming anything inside.","concDuration":"1 min","save":"dex","componentsShort":"V, S, M","effect":{"text":"A shimmering sphere encloses a Large or smaller creature or…"}},{"id":"resistance","name":"Resistance","level":0,"school":"Abjuration","classes":["cleric","druid"],"time":"Action","range":"Touch","components":"V, S","duration":"Up to 1 minute","concentration":true,"text":"You touch a willing creature and choose a damage type: Acid, Bludgeoning, Cold, Fire, Lightning, Necrotic, Piercing, Poison, Radiant, Slashing, or Thunder. When the creature takes damage of the chosen type before the spell ends, the creature reduces the total damage taken by 1d4. A creature can benefit from this spell only once per turn.","concDuration":"1 min","componentsShort":"V, S","effect":{"text":"Reduce damage of one type by 1d4"}},{"id":"resurrection","name":"Resurrection","level":7,"school":"Necromancy","classes":["bard","cleric"],"time":"1 hour","range":"Touch","components":"V, S, M (a diamond worth 1,000+ GP, which the spell consumes)","duration":"Instantaneous","concentration":false,"text":"With a touch, you revive a dead creature that has been dead for no more than a century, didn’t die of old age, and wasn’t Undead when it died.\nThe creature returns to life with all its Hit Points.\nThis spell also neutralizes any poisons that affected the creature at the time of death. This spell closes all mortal wounds and restores any missing body parts.\nComing back from the dead is an ordeal. The target takes a −4 penalty to D20 Tests. Every time the target finishes a Long Rest, the penalty is reduced by 1 until it becomes 0.\nCasting this spell to revive a creature that has been dead for 365 days or longer taxes you. Until you finish a Long Rest, you can’t cast spells again, and you have Disadvantage on D20 Tests.","componentsShort":"V, S, M","effect":{"text":"Return a creature dead up to a century"}},{"id":"reverse-gravity","name":"Reverse Gravity","level":7,"school":"Transmutation","classes":["druid","sorcerer","wizard"],"time":"Action","range":"100 ft","components":"V, S, M (a lodestone and iron filings)","duration":"Up to 1 minute","concentration":true,"text":"This spell reverses gravity in a 50-ft-radius, 100foot high Cylinder centered on a point within range. All creatures and objects in that area that aren’t anchored to the ground fall upward and reach the top of the Cylinder. A creature can make a Dexterity saving throw to grab a fixed object it can reach, thus avoiding the fall upward.\nIf a ceiling or an anchored object is encountered in this upward fall, creatures and objects strike it just as they would during a downward fall. If an affected creature or object reaches the Cylinder’s top without striking anything, it hovers there for the duration. When the spell ends, affected objects and creatures fall downward.","concDuration":"1 min","save":"dex","componentsShort":"V, S, M","effect":{"text":"This spell reverses gravity in a 50-ft-radius, 100foot high…"}},{"id":"revivify","name":"Revivify","level":3,"school":"Necromancy","classes":["cleric","druid","paladin","ranger"],"time":"Action","range":"Touch","components":"V, S, M (a diamond worth 300+ GP, which the spell consumes)","duration":"Instantaneous","concentration":false,"text":"You touch a creature that has died within the last minute. That creature revives with 1 Hit Point. This spell can’t revive a creature that has died of old age, nor does it restore any missing body parts.","componentsShort":"V, S, M","effect":{"text":"Return a creature dead under 1 minute (1 HP)"}},{"id":"rope-trick","name":"Rope Trick","level":2,"school":"Transmutation","classes":["wizard"],"time":"Action","range":"Touch","components":"V, S, M (a segment of rope)","duration":"1 hour","concentration":false,"text":"You touch a rope. One end of it hovers upward until the rope hangs perpendicular to the ground or the rope reaches a ceiling. At the rope’s upper end, an Invisible 3-ft-by-5-ft portal opens to an extra­ dimensional space that lasts until the spell ends. That space can be reached by climbing the rope, which can be pulled into or dropped out of it. The space can hold up to eight Medium or smaller creatures. Attacks, spells, and other effects can’t pass into or out of the space, but creatures inside it can see through the portal. Anything inside the space drops out when the spell ends.","componentsShort":"V, S, M","effect":{"text":"Touch a rope"}},{"id":"sacred-flame","name":"Sacred Flame","level":0,"school":"Evocation","classes":["cleric"],"time":"Action","range":"60 ft","components":"V, S","duration":"Instantaneous","concentration":false,"text":"Flame-like radiance descends on a creature that you can see within range. The target must succeed on a Dexterity saving throw or take 1d8 Radiant damage. The target gains no benefit from Half Cover or Three-Quarters Cover for this save.\nCantrip Upgrade. The damage increases by 1d8 when you reach levels 5 (2d8), 11 (3d8), and 17 (4d8).","save":"dex","effect":{"dice":"1d8","type":"radiant"},"componentsShort":"V, S"},{"id":"sanctuary","name":"Sanctuary","level":1,"school":"Abjuration","classes":["cleric"],"time":"Bonus Action","range":"30 ft","components":"V, S, M (a shard of glass from a mirror)","duration":"1 minute","concentration":false,"text":"You ward a creature within range. Until the spell ends, any creature who targets the warded creature with an attack roll or a damaging spell must succeed on a Wisdom saving throw or either choose a new target or lose the attack or spell. This spell doesn’t protect the warded creature from areas of effect. The spell ends if the warded creature makes an attack roll, casts a spell, or deals damage.","save":"wis","componentsShort":"V, S, M","effect":{"text":"Attackers must pass a WIS save"}},{"id":"scorching-ray","name":"Scorching Ray","level":2,"school":"Evocation","classes":["sorcerer","wizard"],"time":"Action","range":"120 ft","components":"V, S","duration":"Instantaneous","concentration":false,"text":"You hurl three fiery rays. You can hurl them at one target within range or at several. Make a ranged spell attack for each ray. On a hit, the target takes 2d6 Fire damage.\nUsing a Higher-Level Spell Slot. You create one additional ray for each spell slot level above 2.","attack":"ranged","effect":{"dice":"2d6","type":"fire","text":"3 rays · 2d6 fire each"},"higher":"You create one additional ray for each spell slot level above 2.","componentsShort":"V, S"},{"id":"scrying","name":"Scrying","level":5,"school":"Divination","classes":["bard","cleric","druid","warlock","wizard"],"time":"10 minutes","range":"Self","components":"V, S, M (a focus worth 1,000+ GP, such as a crystal ball, mirror, or water-filled font)","duration":"Up to 10 minutes","concentration":true,"text":"You can see and hear a creature you choose that is on the same plane of existence as you. The target makes a Wisdom saving throw, which is modified (see the tables below) by how well you know the target and the sort of physical connection you have to it. The target doesn’t know what it is making the save against, only that it feels uneasy. Your Knowledge of the Target Is …\nSave Modifier\nSecondhand (heard of the target)\n+5\nFirsthand (met the target)\n+0\nExtensive (know the target well)\n−5\nYou Have the Target’s …\nSave Modifier\nPicture or other likeness\n−2\nGarment or other possession\n−4\nBody part, lock of hair, or bit of nail\n−10\nOn a successful save, the target isn’t affected, and you can’t use this spell on it again for 24 hours. On a failed save, the spell creates an Invisible, intangible sensor within 10 ft of the target. You can see and hear through the sensor as if you were there. The sensor moves with the target, remaining within 10 ft of it for the duration. If something can see the sensor, it appears as a luminous orb about the size of your fist.\nInstead of targeting a creature, you can target a location you have seen. When you do so, the sensor appears at that location and doesn’t move.","concDuration":"10 min","save":"wis","componentsShort":"V, S, M","effect":{"text":"Can see and hear a creature you choose that is on the same…"}},{"id":"searing-smite","name":"Searing Smite","level":1,"school":"Evocation","classes":["paladin"],"time":"Bonus Action","range":"Self","components":"V","duration":"1 minute","concentration":false,"text":"As you hit the target, it takes an extra 1d6 Fire damage from the attack. At the start of each of its turns until the spell ends, the target takes 1d6 Fire damage and then makes a Constitution saving throw. On a failed save, the spell continues. On a successful save, the spell ends.\nUsing a Higher-Level Spell Slot. All the damage increases by 1d6 for each spell slot level above 1.","trigger":"immediately after hitting a target with a Melee weapon or an Unarmed Strike","save":"con","effect":{"dice":"1d6","type":"fire"},"higher":"All the damage increases by 1d6 for each spell slot level above 1.","upcast":{"dice":"1d6"},"componentsShort":"V"},{"id":"secret-chest","name":"Secret Chest","level":4,"school":"Conjuration","classes":["wizard"],"time":"Action","range":"Touch","components":"V, S, M (a chest, 3 feet by 2 feet by 2 feet, constructed from rare materials worth 5,000+ GP, and a Tiny replica of the chest made from the same materials worth 50+ GP)","duration":"Until dispelled","concentration":false,"text":"You hide a chest and all its contents on the Ethereal Plane. You must touch the chest and the miniature replica that serve as Material components for the spell. The chest can contain up to 12 cubic feet of nonliving material (3 ft by 2 ft by 2 ft). While the chest remains on the Ethereal Plane, you can take a Magic action and touch the replica to recall the chest. It appears in an unoccupied space on the ground within 5 ft of you. You can send the chest back to the Ethereal Plane by taking a Magic action to touch the chest and the replica. After 60 days, there is a cumulative 5 percent chance at the end of each day that the spell ends. The spell also ends if you cast this spell again or if the Tiny replica chest is destroyed. If the spell ends and the larger chest is on the Ethereal Plane, the chest remains there for you or someone else to find.","componentsShort":"V, S, M","effect":{"text":"Hide a chest and all its contents on the Ethereal Plane"}},{"id":"see-invisibility","name":"See Invisibility","level":2,"school":"Divination","classes":["bard","sorcerer","wizard"],"time":"Action","range":"Self","components":"V, S, M (a pinch of talc)","duration":"1 hour","concentration":false,"text":"For the duration, you see creatures and objects that have the Invisible condition as if they were visible, and you can see into the Ethereal Plane. Creatures and objects there appear ghostly.","componentsShort":"V, S, M","effect":{"text":"For the duration, you see creatures and objects that have the…"}},{"id":"seeming","name":"Seeming","level":5,"school":"Illusion","classes":["bard","sorcerer","wizard"],"time":"Action","range":"30 ft","components":"V, S","duration":"8 hours","concentration":false,"text":"You give an illusory appearance to each creature of your choice that you can see within range. An unwilling target can make a Charisma saving throw, and if it succeeds, it is unaffected by this spell.\nYou can give the same appearance or different ones to the targets. The spell can change the appearance of the targets’ bodies and equipment. You can make each creature seem 1 ft shorter or taller and appear heavier or lighter. A target’s new appearance must have the same basic arrangement of limbs as the target, but the extent of the illusion is otherwise up to you. The spell lasts for the duration.\nThe changes wrought by this spell fail to hold up to physical inspection. For example, if you use this spell to add a hat to a creature’s outfit, objects pass through the hat.\nA creature that takes the Study action to examine a target can make an Intelligence (Investigation) check against your spell save DC. If it succeeds, it becomes aware that the target is disguised.","save":"cha","componentsShort":"V, S","effect":{"text":"Give an illusory appearance to each creature of your choice…"}},{"id":"sending","name":"Sending","level":3,"school":"Divination","classes":["bard","cleric","wizard"],"time":"Action","range":"Unlimited","components":"V, S, M (a copper wire)","duration":"Instantaneous","concentration":false,"text":"You send a short message of 25 words or fewer to a creature you have met or a creature described to you by someone who has met it. The target hears the message in its mind, recognizes you as the sender if it knows you, and can answer in a like manner immediately. The spell enables targets to understand the meaning of your message.\nYou can send the message across any distance and even to other planes of existence, but if the target is on a different plane than you, there is a 5 percent chance that the message doesn’t arrive. You know if the delivery fails.\nUpon receiving your message, a creature can block your ability to reach it again with this spell for 8 hours. If you try to send another message during that time, you learn that you are blocked, and the spell fails.","componentsShort":"V, S, M","effect":{"text":"Send a short message of 25 words or fewer to a creature you…"}},{"id":"sequester","name":"Sequester","level":7,"school":"Transmutation","classes":["wizard"],"time":"Action","range":"Touch","components":"V, S, M (gem dust worth 5,000+ GP, which the spell consumes)","duration":"Until dispelled","concentration":false,"text":"With a touch, you magically sequester an object or a willing creature. For the duration, the target has the Invisible condition and can’t be targeted by Divination spells, detected by magic, or viewed remotely with magic.\nIf the target is a creature, it enters a state of suspended animation; it has the Unconscious condition, doesn’t age, and doesn’t need food, water, or air.\nYou can set a condition for the spell to end early.\nThe condition can be anything you choose, but it must occur or be visible within 1 mile of the target.\nExamples include “after 1,000 years” or “when the tarrasque awakens.” This spell also ends if the target takes any damage.","componentsShort":"V, S, M","effect":{"text":"With a touch, you magically sequester an object or a willing…"}},{"id":"shapechange","name":"Shapechange","level":9,"school":"Transmutation","classes":["druid","wizard"],"time":"Action","range":"Self","components":"V, S, M (a jade circlet worth 1,500+ GP)","duration":"Up to 1 hour","concentration":true,"text":"You shape-shift into another creature for the duration or until you take a Magic action to shape-shift into a different eligible form. The new form must be of a creature that has a Challenge Rating no higher than your level or Challenge Rating. You must have seen the sort of creature before, and it can’t be a Construct or an Undead.\nWhen you cast the spell, you gain a number of Temporary Hit Points equal to the Hit Points of the first form into which you shape-shift. These Temporary Hit Points vanish if any remain when the spell ends.\nYour game statistics are replaced by the stat block of the chosen form, but you retain your creature type; alignment; personality; Intelligence, Wisdom, and Charisma scores; Hit Points; Hit Point Dice; proficiencies; and ability to communicate. If you have the Spellcasting feature, you retain it too.\nUpon shape-shifting, you determine whether your equipment drops to the ground or changes in size and shape to fit the new form while you’re in it.","concDuration":"1 hour","componentsShort":"V, S, M","effect":{"text":"Become any creature you have seen"}},{"id":"shatter","name":"Shatter","level":2,"school":"Evocation","classes":["bard","sorcerer","wizard"],"time":"Action","range":"60 ft","components":"V, S, M (a chip of mica)","duration":"Instantaneous","concentration":false,"text":"A loud noise erupts from a point of your choice within range. Each creature in a 10-ft-radius Sphere centered there makes a Constitution saving throw, taking 3d8 Thunder damage on a failed save or half as much damage on a successful one. A Construct has Disadvantage on the save.\nA nonmagical object that isn’t being worn or carried also takes the damage if it’s in the spell’s area.\nUsing a Higher-Level Spell Slot. The damage increases by 1d8 for each spell slot level above 2.","save":"con","effect":{"dice":"3d8","type":"thunder"},"higher":"The damage increases by 1d8 for each spell slot level above 2.","upcast":{"dice":"1d8"},"componentsShort":"V, S, M"},{"id":"shield","name":"Shield","level":1,"school":"Abjuration","classes":["sorcerer","wizard"],"time":"Reaction","range":"Self","components":"V, S","duration":"1 round","concentration":false,"text":"An imperceptible barrier of magical force protects you. Until the start of your next turn, you have a +5 bonus to AC, including against the triggering attack, and you take no damage from Magic Missile.","trigger":"when you are hit by an attack roll or targeted by the Magic Missile spell","componentsShort":"V, S","effect":{"text":"+5 AC until your next turn"}},{"id":"shield-of-faith","name":"Shield of Faith","level":1,"school":"Abjuration","classes":["cleric","paladin"],"time":"Bonus Action","range":"60 ft","components":"V, S, M (a prayer scroll)","duration":"Up to 10 minutes","concentration":true,"text":"A shimmering field surrounds a creature of your choice within range, granting it a +2 bonus to AC for the duration.","concDuration":"10 min","componentsShort":"V, S, M","effect":{"text":"+2 AC"}},{"id":"shillelagh","name":"Shillelagh","level":0,"school":"Transmutation","classes":["druid"],"time":"Bonus Action","range":"Self","components":"V, S, M (mistletoe)","duration":"1 minute","concentration":false,"text":"A Club or Quarterstaff you are holding is imbued with nature’s power. For the duration, you can use your spellcasting ability instead of Strength for the attack and damage rolls of melee attacks using that weapon, and the weapon’s damage die becomes a d8. If the attack deals damage, it can be Force damage or the weapon’s normal damage type (your choice).\nThe spell ends early if you cast it again or if you let go of the weapon.\nCantrip Upgrade. The damage die changes when you reach levels 5 (d10), 11 (d12), and 17 (2d6).","componentsShort":"V, S, M","effect":{"text":"Club or staff: d8 damage, use your spell ability"}},{"id":"shining-smite","name":"Shining Smite","level":2,"school":"Transmutation","classes":["paladin"],"time":"Bonus Action","range":"Self","components":"V","duration":"Up to 1 minute","concentration":true,"text":"The target hit by the strike takes an extra 2d6 Radiant damage from the attack. Until the spell ends, the target sheds Bright Light in a 5-ft radius, attack rolls against it have Advantage, and it can’t benefit from the Invisible condition.\nUsing a Higher-Level Spell Slot. The damage increases by 1d6 for each spell slot level above 2.","concDuration":"1 min","trigger":"immediately after hitting a creature with a Melee weapon or an Unarmed Strike","effect":{"dice":"2d6","type":"radiant"},"higher":"The damage increases by 1d6 for each spell slot level above 2.","upcast":{"dice":"1d6"},"componentsShort":"V"},{"id":"shocking-grasp","name":"Shocking Grasp","level":0,"school":"Evocation","classes":["sorcerer","wizard"],"time":"Action","range":"Touch","components":"V, S","duration":"Instantaneous","concentration":false,"text":"Lightning springs from you to a creature that you try to touch. Make a melee spell attack against the target. On a hit, the target takes 1d8 Lightning damage, and it can’t make Opportunity Attacks until the start of its next turn.\nCantrip Upgrade. The damage increases by 1d8 when you reach levels 5 (2d8), 11 (3d8), and 17 (4d8).","attack":"melee","effect":{"dice":"1d8","type":"lightning"},"componentsShort":"V, S"},{"id":"silence","name":"Silence","level":2,"school":"Illusion","classes":["bard","cleric","ranger"],"time":"Action","range":"120 ft","components":"V, S","duration":"Up to 10 minutes","concentration":true,"text":"For the duration, no sound can be created within or pass through a 20-ft-radius Sphere centered on a point you choose within range. Any creature or object entirely inside the Sphere has Immunity to Thunder damage, and creatures have the Deafened condition while entirely inside it. Casting a spell that includes a Verbal component is impossible there.","concDuration":"10 min","ritual":true,"componentsShort":"V, S","effect":{"text":"20-ft sphere of silence"}},{"id":"silent-image","name":"Silent Image","level":1,"school":"Illusion","classes":["bard","sorcerer","wizard"],"time":"Action","range":"60 ft","components":"V, S, M (a bit of fleece)","duration":"Up to 10 minutes","concentration":true,"text":"You create the image of an object, a creature, or some other visible phenomenon that is no larger than a 15-ft Cube. The image appears at a spot within range and lasts for the duration. The image is purely visual; it isn’t accompanied by sound, smell, or other sensory effects.\nAs a Magic action, you can cause the image to move to any spot within range. As the image changes location, you can alter its appearance so that its movements appear natural for the image.\nFor example, if you create an image of a creature and move it, you can alter the image so that it appears to be walking.\nPhysical interaction with the image reveals it to be an illusion, since things can pass through it. A creature that takes a Study action to examine the image can determine that it is an illusion with a successful Intelligence (Investigation) check against your spell save DC. If a creature discerns the illusion for what it is, the creature can see through the image.","concDuration":"10 min","componentsShort":"V, S, M","effect":{"text":"Create the image of an object, a creature, or some other…"}},{"id":"simulacrum","name":"Simulacrum","level":7,"school":"Illusion","classes":["wizard"],"time":"12 hours","range":"Touch","components":"V, S, M (powdered ruby worth 1,500+ GP, which the spell consumes)","duration":"Until dispelled","concentration":false,"text":"You create a simulacrum of one Beast or Humanoid that is within 10 ft of you for the entire casting of the spell. You finish the casting by touching both the creature and a pile of ice or snow that is the same size as that creature, and the pile turns into the simulacrum, which is a creature. It uses the game statistics of the original creature at the time of casting, except it is a Construct, its Hit Point maximum is half as much, and it can’t cast this spell.\nThe simulacrum is Friendly to you and creatures you designate. It obeys your commands and acts on your turn in combat. The simulacrum can’t gain levels, and it can’t take Short or Long Rests.\nIf the simulacrum takes damage, the only way to restore its Hit Points is to repair it as you take a Long Rest, during which you expend components worth 100 GP per Hit Point restored. The simulacrum must stay within 5 ft of you for the repair. The simulacrum lasts until it drops to 0 Hit Points, at which point it reverts to snow and melts away. If you cast this spell again, any simulacrum you created with this spell is instantly destroyed.","componentsShort":"V, S, M","effect":{"text":"Create a simulacrum of one Beast or Humanoid that is within…"}},{"id":"sleep","name":"Sleep","level":1,"school":"Enchantment","classes":["bard","sorcerer","wizard"],"time":"Action","range":"60 ft","components":"V, S, M (a pinch of sand or rose petals)","duration":"Up to 1 minute","concentration":true,"text":"Each creature of your choice in a 5-ft-radius Sphere centered on a point within range must succeed on a Wisdom saving throw or have the Incapacitated condition until the end of its next turn, at which point it must repeat the save. If the target fails the second save, the target has the Unconscious condition for the duration. The spell ends on a target if it takes damage or someone within 5 ft of it takes an action to shake it out of the spell’s effect.\nCreatures that don’t sleep, such as elves, or that have Immunity to the Exhaustion condition automatically succeed on saves against this spell.","concDuration":"1 min","save":"wis","componentsShort":"V, S, M","effect":{"text":"Incapacitated, then Unconscious"}},{"id":"sleet-storm","name":"Sleet Storm","level":3,"school":"Conjuration","classes":["druid","sorcerer","wizard"],"time":"Action","range":"150 ft","components":"V, S, M (a miniature umbrella)","duration":"Up to 1 minute","concentration":true,"text":"Until the spell ends, sleet falls in a 40-ft-tall, 20-ft-radius Cylinder centered on a point you choose within range. The area is Heavily Obscured, and exposed flames in the area are doused. Ground in the Cylinder is Difficult Terrain. When a creature enters the Cylinder for the first time on a turn or starts its turn there, it must succeed on a Dexterity saving throw or have the Prone condition and lose Concentration.","concDuration":"1 min","save":"dex","componentsShort":"V, S, M","effect":{"text":"Difficult terrain; fall Prone; breaks concentration"}},{"id":"slow","name":"Slow","level":3,"school":"Transmutation","classes":["bard","sorcerer","wizard"],"time":"Action","range":"120 ft","components":"V, S, M (a drop of molasses)","duration":"Up to 1 minute","concentration":true,"text":"You alter time around up to six creatures of your choice in a 40-ft Cube within range. Each target must succeed on a Wisdom saving throw or be affected by this spell for the duration. An affected target’s Speed is halved, it takes a −2 penalty to AC and Dexterity saving throws, and it can’t take Reactions. On its turns, it can take either an action or a Bonus Action, not both, and it can make only one attack if it takes the Attack action. If it casts a spell with a Somatic component, there is a 25 percent chance the spell fails as a result of the target making the spell’s gestures too slowly.\nAn affected target repeats the save at the end of each of its turns, ending the spell on itself on a success.","concDuration":"1 min","save":"wis","componentsShort":"V, S, M","effect":{"text":"Alter time around up to six creatures of your choice in a…"}},{"id":"sorcerous-burst","name":"Sorcerous Burst","level":0,"school":"Evocation","classes":["sorcerer"],"time":"Action","range":"120 ft","components":"V, S","duration":"Instantaneous","concentration":false,"text":"You cast sorcerous energy at one creature or object within range. Make a ranged spell attack against the target. On a hit, the target takes 1d8 damage of a type you choose: Acid, Cold, Fire, Lightning, Poison, Psychic, or Thunder.\nIf you roll an 8 on a d8 for this spell, you can roll another d8, and add it to the damage. When you cast this spell, the maximum number of these d8s you can add to the spell’s damage equals your spellcasting ability modifier.\nCantrip Upgrade. The damage increases by 1d8 when you reach levels 5 (2d8), 11 (3d8), and 17 (4d8).","attack":"ranged","componentsShort":"V, S","effect":{"text":"Cast sorcerous energy at one creature or object within range"}},{"id":"spare-the-dying","name":"Spare the Dying","level":0,"school":"Necromancy","classes":["cleric","druid"],"time":"Action","range":"15 ft","components":"V, S","duration":"Instantaneous","concentration":false,"text":"Choose a creature within range that has 0 Hit Points and isn’t dead. The creature becomes Stable.\nCantrip Upgrade. The range doubles when you reach levels 5 (30 ft), 11 (60 ft), and 17 (120 ft).","componentsShort":"V, S","effect":{"text":"Stabilize a creature at 0 HP"}},{"id":"speak-with-animals","name":"Speak with Animals","level":1,"school":"Divination","classes":["bard","druid","ranger","warlock"],"time":"Action","range":"Self","components":"V, S","duration":"10 minutes","concentration":false,"text":"For the duration, you can comprehend and verbally communicate with Beasts, and you can use any of the Influence action’s skill options with them. Most Beasts have little to say about topics that don’t pertain to survival or companionship, but at minimum, a Beast can give you information about nearby locations and monsters, including whatever it has perceived within the past day.","ritual":true,"componentsShort":"V, S","effect":{"text":"Talk with Beasts for 10 minutes"}},{"id":"speak-with-dead","name":"Speak with Dead","level":3,"school":"Necromancy","classes":["bard","cleric","wizard"],"time":"Action","range":"10 ft","components":"V, S, M (burning incense)","duration":"10 minutes","concentration":false,"text":"You grant the semblance of life to a corpse of your choice within range, allowing it to answer questions you pose. The corpse must have a mouth, and this spell fails if the deceased creature was Undead when it died. The spell also fails if the corpse was the target of this spell within the past 10 days.\nUntil the spell ends, you can ask the corpse up to five questions. The corpse knows only what it knew in life, including the languages it knew. Answers are usually brief, cryptic, or repetitive, and the corpse is under no compulsion to offer a truthful answer if you are antagonistic toward it or it recognizes you as an enemy. This spell doesn’t return the creature’s soul to its body, only its animating spirit. Thus, the corpse can’t learn new information, doesn’t comprehend anything that has happened since it died, and can’t speculate about future events.","componentsShort":"V, S, M","effect":{"text":"Grant the semblance of life to a corpse of your choice within…"}},{"id":"speak-with-plants","name":"Speak with Plants","level":3,"school":"Transmutation","classes":["bard","druid","ranger"],"time":"Action","range":"Self","components":"V, S","duration":"10 minutes","concentration":false,"text":"You imbue plants in an immobile 30-ft Emanation with limited sentience and animation, giving them the ability to communicate with you and follow your simple commands. You can question plants about events in the spell’s area within the past day, gaining information about creatures that have passed, weather, and other circumstances.\nYou can also turn Difficult Terrain caused by plant growth (such as thickets and undergrowth) into ordinary terrain that lasts for the duration. Or you can turn ordinary terrain where plants are present into Difficult Terrain that lasts for the duration.\nThe spell doesn’t enable plants to uproot themselves and move about, but they can move their branches, tendrils, and stalks for you.\nIf a Plant creature is in the area, you can communicate with it as if you shared a common language.","componentsShort":"V, S","effect":{"text":"Imbue plants in an immobile 30-ft Emanation with limited…"}},{"id":"spider-climb","name":"Spider Climb","level":2,"school":"Transmutation","classes":["sorcerer","warlock","wizard"],"time":"Action","range":"Touch","components":"V, S, M (a drop of bitumen and a spider)","duration":"Up to 1 hour","concentration":true,"text":"Until the spell ends, one willing creature you touch gains the ability to move up, down, and across vertical surfaces and along ceilings, while leaving its hands free. The target also gains a Climb Speed equal to its Speed.\nUsing a Higher-Level Spell Slot. You can target one additional creature for each spell slot level above 2.","concDuration":"1 hour","higher":"You can target one additional creature for each spell slot level above 2.","componentsShort":"V, S, M","effect":{"text":"Until the spell ends, one willing creature you touch gains…"}},{"id":"spike-growth","name":"Spike Growth","level":2,"school":"Transmutation","classes":["druid","ranger"],"time":"Action","range":"150 ft","components":"V, S, M (seven thorns)","duration":"Up to 10 minutes","concentration":true,"text":"The ground in a 20-ft-radius Sphere centered on a point within range sprouts hard spikes and thorns. The area becomes Difficult Terrain for the duration. When a creature moves into or within the area, it takes 2d4 Piercing damage for every 5 ft it travels.\nThe transformation of the ground is camouflaged to look natural. Any creature that can’t see the area when the spell is cast must take a Search action and succeed on a Wisdom (Perception or Survival) check against your spell save DC to recognize the terrain as hazardous before entering it.","concDuration":"10 min","effect":{"dice":"2d4","type":"piercing","text":"2d4 piercing per 5 ft moved"},"componentsShort":"V, S, M"},{"id":"spirit-guardians","name":"Spirit Guardians","level":3,"school":"Conjuration","classes":["cleric"],"time":"Action","range":"Self","components":"V, S, M (a prayer scroll)","duration":"Up to 10 minutes","concentration":true,"text":"Protective spirits flit around you in a 15-ft Emanation for the duration. If you are good or neutral, their spectral form appears angelic or fey (your choice). If you are evil, they appear fiendish.\nWhen you cast this spell, you can designate creatures to be unaffected by it. Any other creature’s Speed is halved in the Emanation, and whenever the Emanation enters a creature’s space and whenever a creature enters the Emanation or ends its turn there, the creature must make a Wisdom saving throw. On a failed save, the creature takes 3d8 Radiant damage (if you are good or neutral) or 3d8 Necrotic damage (if you are evil). On a successful save, the creature takes half as much damage. A creature makes this save only once per turn.\nUsing a Higher-Level Spell Slot. The damage increases by 1d8 for each spell slot level above 3.","concDuration":"10 min","save":"wis","effect":{"dice":"3d8","type":"radiant or necrotic"},"higher":"The damage increases by 1d8 for each spell slot level above 3.","upcast":{"dice":"1d8"},"componentsShort":"V, S, M"},{"id":"spiritual-weapon","name":"Spiritual Weapon","level":2,"school":"Evocation","classes":["cleric"],"time":"Bonus Action","range":"60 ft","components":"V, S","duration":"Up to 1 minute","concentration":true,"text":"You create a floating, spectral force that resembles a weapon of your choice and lasts for the duration.\nThe force appears within range in a space of your choice, and you can immediately make one melee spell attack against one creature within 5 ft of the force. On a hit, the target takes Force damage equal to 1d8 plus your spellcasting ability modifier.\nAs a Bonus Action on your later turns, you can move the force up to 20 ft and repeat the attack against a creature within 5 ft of it.\nUsing a Higher-Level Spell Slot. The damage increases by 1d8 for every slot level above 2.","concDuration":"1 min","attack":"melee","higher":"The damage increases by 1d8 for every slot level above 2.","componentsShort":"V, S","effect":{"dice":"1d8","addMod":true,"type":"force"}},{"id":"starry-wisp","name":"Starry Wisp","level":0,"school":"Evocation","classes":["bard","druid"],"time":"Action","range":"60 ft","components":"V, S","duration":"Instantaneous","concentration":false,"text":"You launch a mote of light at one creature or object within range. Make a ranged spell attack against the target. On a hit, the target takes 1d8 Radiant damage, and until the end of your next turn, it emits Dim Light in a 10-ft radius and can’t benefit from the Invisible condition.\nCantrip Upgrade. The damage increases by 1d8 when you reach levels 5 (2d8), 11 (3d8), and 17 (4d8).","attack":"ranged","effect":{"dice":"1d8","type":"radiant"},"componentsShort":"V, S"},{"id":"stinking-cloud","name":"Stinking Cloud","level":3,"school":"Conjuration","classes":["bard","sorcerer","wizard"],"time":"Action","range":"90 ft","components":"V, S, M (a rotten egg)","duration":"Up to 1 minute","concentration":true,"text":"You create a 20-ft-radius Sphere of yellow, nauseating gas centered on a point within range. The cloud is Heavily Obscured. The cloud lingers in the air for the duration or until a strong wind (such as the one created by Gust of Wind) disperses it.\nEach creature that starts its turn in the Sphere must succeed on a Constitution saving throw or have the Poisoned condition until the end of the current turn. While Poisoned in this way, the creature can’t take an action or a Bonus Action.","concDuration":"1 min","save":"con","componentsShort":"V, S, M","effect":{"text":"Poisoned and lose their action"}},{"id":"stone-shape","name":"Stone Shape","level":4,"school":"Transmutation","classes":["cleric","druid","wizard"],"time":"Action","range":"Touch","components":"V, S, M (soft clay)","duration":"Instantaneous","concentration":false,"text":"You touch a stone object of Medium size or smaller or a section of stone no more than 5 ft in any dimension and form it into any shape you like. For example, you could shape a large rock into a weapon, statue, or coffer, or you could make a small passage through a wall that is 5 ft thick. You could also shape a stone door or its frame to seal the door shut.\nThe object you create can have up to two hinges and a latch, but finer mechanical detail isn’t possible.","componentsShort":"V, S, M","effect":{"text":"Touch a stone object of Medium size or smaller or a section…"}},{"id":"stoneskin","name":"Stoneskin","level":4,"school":"Transmutation","classes":["druid","ranger","sorcerer","wizard"],"time":"Action","range":"Touch","components":"V, S, M (diamond dust worth 100+ GP, which the spell consumes)","duration":"Up to 1 hour","concentration":true,"text":"Until the spell ends, one willing creature you touch has Resistance to Bludgeoning, Piercing, and Slashing damage.","concDuration":"1 hour","componentsShort":"V, S, M","effect":{"text":"Resistance to bludgeoning, piercing, slashing"}},{"id":"storm-of-vengeance","name":"Storm of Vengeance","level":9,"school":"Conjuration","classes":["druid"],"time":"Action","range":"1 mile","components":"V, S","duration":"Up to 1 minute","concentration":true,"text":"A churning storm cloud forms for the duration, centered on a point within range and spreading to a radius of 300 ft. Each creature under the cloud when it appears must succeed on a Constitution saving throw or take 2d6 Thunder damage and have the Deafened condition for the duration.\nAt the start of each of your later turns, the storm produces different effects, as detailed below.\nTurn 2. Acidic rain falls. Each creature and object under the cloud takes 4d6 Acid damage.\nTurn 3. You call six bolts of lightning from the cloud to strike six different creatures or objects beneath it. Each target makes a Dexterity saving throw, taking 10d6 Lightning damage on a failed save or half as much damage on a successful one.\nTurn 4. Hailstones rain down. Each creature under the cloud takes 2d6 Bludgeoning damage. Turns 5–10. Gusts and freezing rain assail the area under the cloud. Each creature there takes 1d6 Cold damage. Until the spell ends, the area is Difficult Terrain and Heavily Obscured, ranged attacks with weapons are impossible there, and strong wind blows through the area.","concDuration":"1 min","save":"con","effect":{"dice":"2d6","type":"thunder"},"componentsShort":"V, S"},{"id":"suggestion","name":"Suggestion","level":2,"school":"Enchantment","classes":["bard","sorcerer","warlock","wizard"],"time":"Action","range":"30 ft","components":"V, M (a drop of honey)","duration":"Up to 8 hours","concentration":true,"text":"You suggest a course of activity—described in no more than 25 words—to one creature you can see within range that can hear and understand you.\nThe suggestion must sound achievable and not involve anything that would obviously deal damage to the target or its allies. For example, you could say, “Fetch the key to the cult’s treasure vault, and give the key to me.” Or you could say, “Stop fighting, leave this library peacefully, and don’t return.”\nThe target must succeed on a Wisdom saving throw or have the Charmed condition for the duration or until you or your allies deal damage to the target. The Charmed target pursues the suggestion to the best of its ability. The suggested activity can continue for the entire duration, but if the suggested activity can be completed in a shorter time, the spell ends for the target upon completing it.","concDuration":"8 hours","save":"wis","componentsShort":"V, M","effect":{"text":"Charmed; follows a reasonable suggestion"}},{"id":"summon-dragon","name":"Summon Dragon","level":5,"school":"Conjuration","classes":["wizard"],"time":"Action","range":"60 ft","components":"V, S, M (an object with the image of a dragon engraved on it worth 500+ GP)","duration":"Up to 1 hour","concentration":true,"text":"You call forth a Dragon spirit. It manifests in an unoccupied space that you can see within range and uses the Draconic Spirit stat block. The creature disappears when it drops to 0 Hit Points or when the spell ends.\nThe creature is an ally to you and your allies. In combat, the creature shares your Initiative count, but it takes its turn immediately after yours. It obeys your verbal commands (no action required by you). If you don’t issue any, it takes the Dodge action and uses its movement to avoid danger.\nUsing a Higher-Level Spell Slot. Use the spell slot’s level for the spell’s level in the stat block.\nDraconic Spirit Large Dragon, Neutral AC 14 + the spell’s level HP 50 + 10 for each spell level above 5 Speed 30 ft., Fly 60 ft., Swim 30 ft.\nMOD SAVE\nMOD SAVE\nMOD SAVE\nStr 19 +4 +4 Int 10 +0 +0\nDex 14 +2 +2 Wis 14 +2 +2\nCon 17 +3 +3 Cha 14 +2 +2\nResistances Acid, Cold, Fire, Lightning, Poison Immunities Charmed, Frightened, Poisoned Senses Blindsight 30 ft., Darkvision 60 ft.; Passive Perception 12 Languages Draconic, understands the languages you know CR None (XP 0; PB equals your Proficiency Bonus)\nTraits Shared Resistances. When you summon the spirit, choose one of its Resistances. You have Resistance to the chosen damage type until the spell ends.\nActions Multiattack. The spirit makes a number of Rend attacks equal to half the spell’s level (round down), and it uses Breath Weapon.\nRend. Melee Attack Roll: Bonus equals your spell attack modifier, reach 10 ft. Hit: 1d6 + 4 + the spell’s level Piercing damage.\nBreath Weapon. Dexterity Saving Throw: DC equals your spell save DC, each creature in a 30-ft Cone.\nFailure: 2d6 damage of a type this spirit has Resistance to (your choice when you cast the spell). Success:\nHalf damage.","concDuration":"1 hour","higher":"Use the spell slot’s level for the spell’s level in the stat block.","componentsShort":"V, S, M","effect":{"text":"A draconic spirit fights for you"}},{"id":"sunbeam","name":"Sunbeam","level":6,"school":"Evocation","classes":["cleric","druid","sorcerer","wizard"],"time":"Action","range":"Self","components":"V, S, M (a magnifying glass)","duration":"Up to 1 minute","concentration":true,"text":"You launch a sunbeam in a 5-ft-wide, 60-ft-long Line. Each creature in the Line makes a Constitution saving throw. On a failed save, a creature takes 6d8 Radiant damage and has the Blinded condition until the start of your next turn. On a successful save, it takes half as much damage only.\nUntil the spell ends, you can take a Magic action to create a new Line of radiance.\nFor the duration, a mote of brilliant radiance shines above you. It sheds Bright Light in a 30-ft radius and Dim Light for an additional 30 ft. This light is sunlight.","concDuration":"1 min","save":"con","effect":{"dice":"6d8","type":"radiant","addMod":false},"componentsShort":"V, S, M"},{"id":"sunburst","name":"Sunburst","level":8,"school":"Evocation","classes":["cleric","druid","sorcerer","wizard"],"time":"Action","range":"150 ft","components":"V, S, M (a piece of sunstone)","duration":"Instantaneous","concentration":false,"text":"Brilliant sunlight flashes in a 60-ft-radius Sphere centered on a point you choose within range. Each creature in the Sphere makes a Constitution saving throw. On a failed save, a creature takes 12d6 Radiant damage and has the Blinded condition for 1 minute. On a successful save, it takes half as much damage only.\nA creature Blinded by this spell makes another Constitution saving throw at the end of each of its turns, ending the effect on itself on a success.\nThis spell dispels Darkness in its area that was created by any spell.","save":"con","effect":{"dice":"12d6","type":"radiant","addMod":false},"componentsShort":"V, S, M"},{"id":"symbol","name":"Symbol","level":7,"school":"Abjuration","classes":["bard","cleric","druid","wizard"],"time":"1 minute","range":"Touch","components":"V, S, M (powdered diamond worth 1,000+ GP, which the spell consumes)","duration":"Until dispelled or triggered","concentration":false,"text":"You inscribe a harmful glyph either on a surface (such as a section of floor or wall) or within an object that can be closed (such as a book or chest). The glyph can cover an area no larger than 10 ft in diameter. If you choose an object, it must remain in place; if it is moved more than 10 ft from where you cast this spell, the glyph is broken, and the spell ends without being triggered.\nThe glyph is nearly imperceptible and requires a successful Wisdom (Perception) check against your spell save DC to notice.\nWhen you inscribe the glyph, you set its trigger and choose which effect the symbol bears: Death, Discord, Fear, Pain, Sleep, or Stunning. Each one is explained below.\nSet the Trigger. You decide what triggers the glyph when you cast the spell. For glyphs inscribed on a surface, common triggers include touching or stepping on the glyph, removing another object covering it, or approaching within a certain distance of it. For glyphs inscribed within an object, common triggers include opening that object or seeing the glyph.\nYou can refine the trigger so that only creatures of certain types activate it (for example, the glyph could be set to affect Aberrations). You can also set conditions for creatures that don’t trigger the glyph, such as those who say a certain password.\nOnce triggered, the glyph glows, filling a 60-ft-radius Sphere with Dim Light for 10 minutes, after which time the spell ends. Each creature in the Sphere when the glyph activates is targeted by its effect, as is a creature that enters the Sphere for the first time on a turn or ends its turn there. A creature is targeted only once per turn.\nDeath. Each target makes a Constitution saving throw, taking 10d10 Necrotic damage on a failed save or half as much damage on a successful save.\nDiscord. Each target makes a Wisdom saving throw. On a failed save, a target argues with other creatures for 1 minute. During this time, it is incapable of meaningful communication and has Disadvantage on attack rolls and ability checks.\nFear. Each target must succeed on a Wisdom saving throw or have the Frightened condition for 1 minute. While Frightened, the target must move at least 30 ft away from the glyph on each of its turns, if able.\nPain. Each target must succeed on a Constitution saving throw or have the Incapacitated condition for 1 minute.\nSleep. Each target must succeed on a Wisdom saving throw or have the Unconscious condition for 10 minutes. A creature awakens if it takes damage or if someone takes an action to shake it awake.\nStunning. Each target must succeed on a Wisdom saving throw or have the Stunned condition for 1 minute.","save":"con","effect":{"dice":"10d10","type":"necrotic"},"componentsShort":"V, S, M"},{"id":"telekinesis","name":"Telekinesis","level":5,"school":"Transmutation","classes":["sorcerer","wizard"],"time":"Action","range":"60 ft","components":"V, S","duration":"Up to 10 minutes","concentration":true,"text":"You gain the ability to move or manipulate creatures or objects by thought. When you cast the spell and as a Magic action on your later turns before the spell ends, you can exert your will on one creature or object that you can see within range, causing the appropriate effect below. You can affect the same target round after round or choose a new one at any time. If you switch targets, the prior target is no longer affected by the spell.\nCreature. You can try to move a Huge or smaller creature. The target must succeed on a Strength saving throw, or you move it up to 30 ft in any direction within the spell’s range. Until the end of your next turn, the creature has the Restrained condition, and if you lift it into the air, it is suspended there. It falls at the end of your next turn unless you use this option on it again and it fails the save.\nObject. You can try to move a Huge or smaller object. If the object isn’t being worn or carried, you automatically move it up to 30 ft in any direction within the spell’s range.\nIf the object is worn or carried by a creature, that creature must succeed on a Strength saving throw, or you pull the object away and move it up to 30 ft in any direction within the spell’s range.\nYou can exert fine control on objects with your telekinetic grip, such as manipulating a simple tool,","concDuration":"10 min","save":"str","componentsShort":"V, S","effect":{"text":"Gain the ability to move or manipulate creatures or objects…"}},{"id":"telepathic-bond","name":"Telepathic Bond","level":5,"school":"Divination","classes":["bard","wizard"],"time":"Action","range":"30 ft","components":"V, S, M (two eggs)","duration":"1 hour","concentration":false,"text":"You forge a telepathic link among up to eight willing creatures of your choice within range, psychically linking each creature to all the others for the duration. Creatures that can’t communicate in any languages aren’t affected by this spell. Until the spell ends, the targets can communicate telepathically through the bond whether or not they share a language. The communication is possible over any distance, though it can’t extend to other planes of existence.","ritual":true,"componentsShort":"V, S, M","effect":{"text":"Forge a telepathic link among up to eight willing creatures…"}},{"id":"teleport","name":"Teleport","level":7,"school":"Conjuration","classes":["bard","sorcerer","wizard"],"time":"Action","range":"10 ft","components":"V","duration":"Instantaneous","concentration":false,"text":"This spell instantly transports you and up to eight willing creatures that you can see within range, or a single object that you can see within range, to a destination you select. If you target an object, it must be Large or smaller, and it can’t be held or carried by an unwilling creature.\nThe destination you choose must be known to you, and it must be on the same plane of existence as you. Your familiarity with the destination determines whether you arrive there successfully. The GM rolls 1d100 and consults the Teleportation Outcome table and the explanations after it.\nTeleportation Outcome Mishap\nSimilar Area\nOff Target\nOn Target\nPermanent circle\n—\n—\n— 01–00\nLinked object\n—\n—\n— 01–00\nVery familiar 01–05 06–13 14–24 25–00\nSeen casually 01–33 34–43 44–53 54–00\nViewed once or described 01–43 44–53 54–73 74–00\nFalse destination 01–50 51–00\n—\n—\nFamiliarity Familiarity. Here are the meanings of the terms in the table’s Familiarity column:\n• “Permanent circle” means a permanent teleportation circle whose sigil sequence you know.\n• “Linked object” means you possess an object taken from the desired destination within the last six months, such as a book from a wizard’s library.\n• “Very familiar” is a place you have visited often, a place you have carefully studied, or a place you can see when you cast the spell.\n• “Seen casually” is a place you have seen more than once but with which you aren’t very familiar.\n• “Viewed once or described” is a place you have seen once, possibly using magic, or a place you know through someone else’s description, perhaps from a map.\n• “False destination” is a place that doesn’t exist.\nPerhaps you tried to scry an enemy’s sanctum but instead viewed an illusion, or you are attempting to teleport to a location that no longer exists.\nMishap. The spell’s unpredictable magic results in a difficult journey. Each teleporting creature (or the target object) takes 3d10 Force damage, and the GM rerolls on the table to see where you wind up (multiple mishaps can occur, dealing damage each time).\nSimilar Area. You and your group (or the target object) appear in a different area that’s visually or thematically similar to the target area. You appear in the closest similar place. If you are heading for your home laboratory, for example, you might appear in another person’s laboratory in the same city.\nOff Target. You and your group (or the target object) appear 2d12 miles away from the destination in a random direction. Roll 1d8 for the direction: 1, east; 2, southeast; 3, south; 4, southwest; 5, west; 6, northwest; 7, north; or 8, northeast.\nOn Target. You and your group (or the target object) appear where you intended.","effect":{"dice":"3d10","type":"force","text":"Teleport up to 9 creatures anywhere on the plane"},"componentsShort":"V"},{"id":"teleportation-circle","name":"Teleportation Circle","level":5,"school":"Conjuration","classes":["bard","sorcerer","warlock","wizard"],"time":"1 minute","range":"10 ft","components":"V, M (rare inks worth 50+ GP, which the spell consumes)","duration":"1 round","concentration":false,"text":"As you cast the spell, you draw a 5-ft-radius circle on the ground inscribed with sigils that link your location to a permanent teleportation circle of your choice whose sigil sequence you know and that is on the same plane of existence as you. A shimmering portal opens within the circle you drew and remains open until the end of your next turn. Any creature that enters the portal instantly appears within 5 ft of the destination circle or in the nearest unoccupied space if that space is occupied.\nMany major temples, guildhalls, and other important places have permanent teleportation circles. Each circle includes a unique sigil sequence—a string of runes arranged in a particular pattern.\nWhen you first gain the ability to cast this spell, you learn the sigil sequences for two destinations on the Material Plane, determined by the GM. You might learn additional sigil sequences during your adventures. You can commit a new sigil sequence to memory after studying it for 1 minute.\nYou can create a permanent teleportation circle by casting this spell in the same location every day for 365 days.","componentsShort":"V, M","effect":{"text":"As you cast the spell, you draw a 5-ft-radius circle on the…"}},{"id":"thaumaturgy","name":"Thaumaturgy","level":0,"school":"Transmutation","classes":["cleric"],"time":"Action","range":"30 ft","components":"V","duration":"Up to 1 minute","concentration":false,"text":"You manifest a minor wonder within range. You create one of the effects below within range. If you cast this spell multiple times, you can have up to three of its 1-minute effects active at a time.\nAltered Eyes. You alter the appearance of your eyes for 1 minute.\nBooming Voice. Your voice booms up to three times as loud as normal for 1 minute. For the duration, you have Advantage on Charisma (Intimidation) checks.\nFire Play. You cause flames to flicker, brighten, dim, or change color for 1 minute.\nInvisible Hand. You instantaneously cause an unlocked door or window to fly open or slam shut.\nPhantom Sound. You create an instantaneous sound that originates from a point of your choice within range, such as a rumble of thunder, the cry of a raven, or ominous whispers.\nTremors. You cause harmless tremors in the ground for 1 minute.","componentsShort":"V","effect":{"text":"Minor wonder"}},{"id":"thunderwave","name":"Thunderwave","level":1,"school":"Evocation","classes":["bard","druid","sorcerer","wizard"],"time":"Action","range":"Self","components":"V, S","duration":"Instantaneous","concentration":false,"text":"You unleash a wave of thunderous energy. Each creature in a 15-ft Cube originating from you makes a Constitution saving throw. On a failed save, a creature takes 2d8 Thunder damage and is pushed 10 ft away from you. On a successful save, a creature takes half as much damage only.\nIn addition, unsecured objects that are entirely within the Cube are pushed 10 ft away from you, and a thunderous boom is audible within 300 ft.\nUsing a Higher-Level Spell Slot. The damage increases by 1d8 for each spell slot level above 1.","save":"con","effect":{"dice":"2d8","type":"thunder"},"higher":"The damage increases by 1d8 for each spell slot level above 1.","upcast":{"dice":"1d8"},"componentsShort":"V, S"},{"id":"time-stop","name":"Time Stop","level":9,"school":"Transmutation","classes":["sorcerer","wizard"],"time":"Action","range":"Self","components":"V","duration":"Instantaneous","concentration":false,"text":"You briefly stop the flow of time for everyone but yourself. No time passes for other creatures, while you take 1d4 + 1 turns in a row, during which you can use actions and move as normal.\nThis spell ends if one of the actions you use during this period, or any effects that you create during it, affects a creature other than you or an object being worn or carried by someone other than you. In addition, the spell ends if you move to a place more than 1,000 ft from the location where you cast it.","componentsShort":"V","effect":{"text":"1d4 + 1 extra turns"}},{"id":"tiny-hut","name":"Tiny Hut","level":3,"school":"Evocation","classes":["bard","wizard"],"time":"1 minute","range":"Self","components":"V, S, M (a crystal bead)","duration":"8 hours","concentration":false,"text":"A 10-ft Emanation springs into existence around you and remains stationary for the duration. The spell fails when you cast it if the Emanation isn’t big enough to fully encapsulate all creatures in its area.\nCreatures and objects within the Emanation when you cast the spell can move through it freely.\nAll other creatures and objects are barred from passing through it. Spells of level 3 or lower can’t be cast through it, and the effects of such spells can’t extend into it.\nThe atmosphere inside the Emanation is comfortable and dry, regardless of the weather outside. Until the spell ends, you can command the interior to have Dim Light or Darkness (no action required). The Emanation is opaque from the outside and of any color you choose, but it’s transparent from the inside.\nThe spell ends early if you leave the Emanation or if you cast it again.","ritual":true,"componentsShort":"V, S, M","effect":{"text":"A 10-ft Emanation springs into existence around you and…"}},{"id":"tongues","name":"Tongues","level":3,"school":"Divination","classes":["bard","cleric","sorcerer","warlock","wizard"],"time":"Action","range":"Touch","components":"V, M (a miniature ziggurat)","duration":"1 hour","concentration":false,"text":"This spell grants the creature you touch the ability to understand any spoken or signed language that it hears or sees. Moreover, when the target communicates by speaking or signing, any creature that knows at least one language can understand it if that creature can hear the speech or see the signing.","componentsShort":"V, M","effect":{"text":"Understand and speak any language"}},{"id":"transport-via-plants","name":"Transport via Plants","level":6,"school":"Conjuration","classes":["druid"],"time":"Action","range":"10 ft","components":"V, S","duration":"1 minute","concentration":false,"text":"This spell creates a magical link between a Large or larger inanimate plant within range and another plant, at any distance, on the same plane of existence. You must have seen or touched the destination plant at least once before. For the duration, any creature can step into the target plant and exit from the destination plant by using 5 ft of movement.","componentsShort":"V, S","effect":{"text":"This spell creates a magical link between a Large or larger…"}},{"id":"tree-stride","name":"Tree Stride","level":5,"school":"Conjuration","classes":["druid","ranger"],"time":"Action","range":"Self","components":"V, S","duration":"Up to 1 minute","concentration":true,"text":"You gain the ability to enter a tree and move from inside it to inside another tree of the same kind within 500 ft. Both trees must be living and at least the same size as you. You must use 5 ft of movement to enter a tree. You instantly know the location of all other trees of the same kind within 500 ft and, as part of the move used to enter the tree, can either pass into one of those trees or step out of the tree you’re in. You appear in a spot of your choice within 5 ft of the destination tree, using another 5 ft of movement. If you have no movement left, you appear within 5 ft of the tree you entered.\nYou can use this transportation ability only once on each of your turns. You must end each turn outside a tree.","concDuration":"1 min","componentsShort":"V, S","effect":{"text":"Step into one tree and out of another"}},{"id":"true-polymorph","name":"True Polymorph","level":9,"school":"Transmutation","classes":["bard","warlock","wizard"],"time":"Action","range":"30 ft","components":"V, S, M (a drop of mercury, a dollop of gum arabic, and a wisp of smoke)","duration":"Up to 1 hour","concentration":true,"text":"Choose one creature or nonmagical object that you can see within range. The creature shape-shifts into a different creature or a nonmagical object, or the object shape-shifts into a creature (the object must be neither worn nor carried). The transformation lasts for the duration or until the target dies or is destroyed, but if you maintain Concentration on this spell for the full duration, the spell lasts until dispelled.\nAn unwilling creature can make a Wisdom saving throw, and if it succeeds, it isn’t affected by this spell.\nCreature into Creature. If you turn a creature into another kind of creature, the new form can be any kind you choose that has a Challenge Rating equal to or less than the target’s Challenge Rating or level. The target’s game statistics are replaced by the stat block of the new form, but it retains its Hit Points, Hit Point Dice, alignment, and personality. The target gains a number of Temporary Hit Points equal to the Hit Points of the new form. These Temporary Hit Points vanish if any remain when the spell ends.\nThe target is limited in the actions it can perform by the anatomy of its new form, and it can’t speak or cast spells.\nThe target’s gear melds into the new form. The creature can’t use or otherwise benefit from any of that equipment.\nObject into Creature. You can turn an object into any kind of creature, as long as the creature’s size is no larger than the object’s size and the creature has a Challenge Rating of 9 or lower. The creature is Friendly to you and your allies. In combat, it takes its turns immediately after yours, and it obeys your commands.\nIf the spell lasts more than an hour, you no longer control the creature. It might remain Friendly to you, depending on how you have treated it.\nCreature into Object. If you turn a creature into an object, it transforms along with whatever it is wearing and carrying into that form, as long as the object’s size is no larger than the creature’s size. The creature’s statistics become those of the object, and the creature has no memory of time spent in this form after the spell ends and it returns to normal.","concDuration":"1 hour","save":"wis","componentsShort":"V, S, M","effect":{"text":"Permanent transformation if held 1 hour"}},{"id":"true-resurrection","name":"True Resurrection","level":9,"school":"Necromancy","classes":["cleric","druid"],"time":"1 hour","range":"Touch","components":"V, S, M (diamonds worth 25,000+ GP, which the spell consumes)","duration":"Instantaneous","concentration":false,"text":"You touch a creature that has been dead for no longer than 200 years and that died for any reason except old age. The creature is revived with all its Hit Points.\nThis spell closes all wounds, neutralizes any poison, cures all magical contagions, and lifts any curses affecting the creature when it died. The spell replaces damaged or missing organs and limbs. If the creature was Undead, it is restored to its non-Undead form.\nThe spell can provide a new body if the original no longer exists, in which case you must speak the creature’s name. The creature then appears in an unoccupied space you choose within 10 ft of you.","componentsShort":"V, S, M","effect":{"text":"Touch a creature that has been dead for no longer than 200…"}},{"id":"true-seeing","name":"True Seeing","level":6,"school":"Divination","classes":["bard","cleric","sorcerer","warlock","wizard"],"time":"Action","range":"Touch","components":"V, S, M (mushroom powder worth 25+ GP, which the spell consumes)","duration":"1 hour","concentration":false,"text":"For the duration, the willing creature you touch has Truesight with a range of 120 ft.","componentsShort":"V, S, M","effect":{"text":"Truesight 120 ft"}},{"id":"true-strike","name":"True Strike","level":0,"school":"Divination","classes":["bard","sorcerer","warlock","wizard"],"time":"Action","range":"Self","components":"S, M (a weapon with which you have proficiency and that is worth 1+ CP)","duration":"Instantaneous","concentration":false,"text":"Guided by a flash of magical insight, you make one attack with the weapon used in the spell’s casting.\nThe attack uses your spellcasting ability for the attack and damage rolls instead of using Strength or Dexterity. If the attack deals damage, it can be Radiant damage or the weapon’s normal damage type (your choice).\nCantrip Upgrade. Whether you deal Radiant damage or the weapon’s normal damage type, the attack deals extra Radiant damage when you reach levels 5 (1d6), 11 (2d6), and 17 (3d6).","componentsShort":"S, M","effect":{"text":"Guided by a flash of magical insight, you make one attack…"}},{"id":"tsunami","name":"Tsunami","level":8,"school":"Conjuration","classes":["druid"],"time":"1 minute","range":"1 mile","components":"V, S","duration":"Up to 6 rounds","concentration":true,"text":"A wall of water springs into existence at a point you choose within range. You can make the wall up to 300 ft long, 300 ft high, and 50 ft thick. The wall lasts for the duration.\nWhen the wall appears, each creature in its area makes a Strength saving throw, taking 6d10 Bludgeoning damage on a failed save or half as much damage on a successful one.\nAt the start of each of your turns after the wall appears, the wall, along with any creatures in it, moves 50 ft away from you. Any Huge or smaller creature inside the wall or whose space the wall enters when it moves must succeed on a Strength saving throw or take 5d10 Bludgeoning damage. A creature can take this damage only once per round.\nAt the end of the turn, the wall’s height is reduced by 50 ft, and the damage the wall deals on later rounds is reduced by 1d10. When the wall reaches 0 ft in height, the spell ends.\nA creature caught in the wall can move by swimming. Because of the wave’s force, though, the creature must succeed on a Strength (Athletics) check against your spell save DC to move at all. If it fails the check, it can’t move. A creature that moves out of the wall falls to the ground.","save":"str","effect":{"dice":"6d10","type":"bludgeoning"},"componentsShort":"V, S"},{"id":"unseen-servant","name":"Unseen Servant","level":1,"school":"Conjuration","classes":["bard","warlock","wizard"],"time":"Action","range":"60 ft","components":"V, S, M (a bit of string and of wood)","duration":"1 hour","concentration":false,"text":"This spell creates an Invisible, mindless, shapeless, Medium force that performs simple tasks at your command until the spell ends. The servant springs into existence in an unoccupied space on the ground within range. It has AC 10, 1 Hit Point, and a Strength of 2, and it can’t attack. If it drops to 0 Hit Points, the spell ends.\nOnce on each of your turns as a Bonus Action, you can mentally command the servant to move up to 15 ft and interact with an object. The servant can perform simple tasks that a human could do, such as fetching things, cleaning, mending, folding clothes, lighting fires, serving food, and pouring drinks. Once you give the command, the servant performs the task to the best of its ability until it completes the task, then waits for your next command.\nIf you command the servant to perform a task that would move it more than 60 ft away from you, the spell ends.","ritual":true,"componentsShort":"V, S, M","effect":{"text":"This spell creates an Invisible, mindless, shapeless, Medium…"}},{"id":"vampiric-touch","name":"Vampiric Touch","level":3,"school":"Necromancy","classes":["sorcerer","warlock","wizard"],"time":"Action","range":"Self","components":"V, S","duration":"Up to 1 minute","concentration":true,"text":"The touch of your shadow-wreathed hand can siphon life force from others to heal your wounds. Make a melee spell attack against one creature within reach. On a hit, the target takes 3d6 Necrotic damage, and you regain Hit Points equal to half the amount of Necrotic damage dealt.\nUntil the spell ends, you can make the attack again on each of your turns as a Magic action, targeting the same creature or a different one.\nUsing a Higher-Level Spell Slot. The damage increases by 1d6 for each spell slot level above 3.","concDuration":"1 min","attack":"melee","effect":{"dice":"3d6","type":"necrotic"},"higher":"The damage increases by 1d6 for each spell slot level above 3.","upcast":{"dice":"1d6"},"componentsShort":"V, S"},{"id":"vicious-mockery","name":"Vicious Mockery","level":0,"school":"Enchantment","classes":["bard"],"time":"Action","range":"60 ft","components":"V","duration":"Instantaneous","concentration":false,"text":"You unleash a string of insults laced with subtle enchantments at one creature you can see or hear within range. The target must succeed on a Wisdom saving throw or take 1d6 Psychic damage and have Disadvantage on the next attack roll it makes before the end of its next turn.\nCantrip Upgrade. The damage increases by 1d6 when you reach levels 5 (2d6), 11 (3d6), and 17 (4d6).","save":"wis","effect":{"dice":"1d6","type":"psychic"},"componentsShort":"V"},{"id":"vitriolic-sphere","name":"Vitriolic Sphere","level":4,"school":"Evocation","classes":["sorcerer","wizard"],"time":"Action","range":"150 ft","components":"V, S, M (a drop of bile)","duration":"Instantaneous","concentration":false,"text":"You point at a location within range, and a glowing, 1-ft-diameter ball of acid streaks there and explodes in a 20-ft-radius Sphere. Each creature in that area makes a Dexterity saving throw. On a failed save, a creature takes 10d4 Acid damage and another 5d4 Acid damage at the end of its next turn.\nOn a successful save, a creature takes half the initial damage only.\nUsing a Higher-Level Spell Slot. The initial damage increases by 2d4 for each spell slot level above 4.","save":"dex","effect":{"dice":"10d4","type":"acid"},"higher":"The initial damage increases by 2d4 for each spell slot level above 4.","upcast":{"dice":"2d4"},"componentsShort":"V, S, M"},{"id":"wall-of-fire","name":"Wall of Fire","level":4,"school":"Evocation","classes":["druid","sorcerer","wizard"],"time":"Action","range":"120 ft","components":"V, S, M (a piece of charcoal)","duration":"Up to 1 minute","concentration":true,"text":"You create a wall of fire on a solid surface within range. You can make the wall up to 60 ft long, 20 ft high, and 1 ft thick, or a ringed wall up to 20 ft in diameter, 20 ft high, and 1 ft thick. The wall is opaque and lasts for the duration.\nWhen the wall appears, each creature in its area makes a Dexterity saving throw, taking 5d8 Fire damage on a failed save or half as much damage on a successful one.\nOne side of the wall, selected by you when you cast this spell, deals 5d8 Fire damage to each creature that ends its turn within 10 ft of that side or inside the wall. A creature takes the same damage when it enters the wall for the first time on a turn or ends its turn there. The other side of the wall deals no damage.\nUsing a Higher-Level Spell Slot. The damage increases by 1d8 for each spell slot level above 4.","concDuration":"1 min","save":"dex","effect":{"dice":"5d8","type":"fire","addMod":false},"higher":"The damage increases by 1d8 for each spell slot level above 4.","upcast":{"dice":"1d8"},"componentsShort":"V, S, M"},{"id":"wall-of-force","name":"Wall of Force","level":5,"school":"Evocation","classes":["wizard"],"time":"Action","range":"120 ft","components":"V, S, M (a shard of glass)","duration":"Up to 10 minutes","concentration":true,"text":"An Invisible wall of force springs into existence at a point you choose within range. The wall appears in any orientation you choose, as a horizontal or vertical barrier or at an angle. It can be free floating or resting on a solid surface. You can form it into a hemispherical dome or a globe with a radius of up to 10 ft, or you can shape a flat surface made up of ten 10-ft-by-10-ft panels. Each panel must be contiguous with another panel. In any form, the wall is 1/4 inch thick and lasts for the duration. If the wall cuts through a creature’s space when it appears, the creature is pushed to one side of the wall (you choose which side).\nNothing can physically pass through the wall. It is immune to all damage and can’t be dispelled by Dispel Magic. A Disintegrate spell destroys the wall instantly, however. The wall also extends into the Ethereal Plane and blocks ethereal travel through the wall.","concDuration":"10 min","componentsShort":"V, S, M","effect":{"text":"An Invisible wall of force springs into existence at a point…"}},{"id":"wall-of-ice","name":"Wall of Ice","level":6,"school":"Evocation","classes":["wizard"],"time":"Action","range":"120 ft","components":"V, S, M (a piece of quartz)","duration":"Up to 10 minutes","concentration":true,"text":"You create a wall of ice on a solid surface within range. You can form it into a hemispherical dome or a globe with a radius of up to 10 ft, or you can shape a flat surface made up of ten 10-ft-square panels. Each panel must be contiguous with another panel. In any form, the wall is 1 ft thick and lasts for the duration.\nIf the wall cuts through a creature’s space when it appears, the creature is pushed to one side of the wall (you choose which side) and makes a Dexterity saving throw, taking 10d6 Cold damage on a failed save or half as much damage on a successful one.\nThe wall is an object that can be damaged and thus breached. It has AC 12 and 30 Hit Points per 10-ft section, and it has Immunity to Cold, Poison, and Psychic damage and Vulnerability to Fire damage. Reducing a 10-ft section of wall to 0 Hit Points destroys it and leaves behind a sheet of frigid air in the space the wall occupied.\nA creature moving through the sheet of frigid air for the first time on a turn makes a Constitution saving throw, taking 5d6 Cold damage on a failed save or half as much damage on a successful one.\nUsing a Higher-Level Spell Slot. The damage the wall deals when it appears increases by 2d6 and the damage from passing through the sheet of frigid air increases by 1d6 for each spell slot level above 6.","concDuration":"10 min","save":"dex","effect":{"dice":"10d6","type":"cold"},"higher":"The damage the wall deals when it appears increases by 2d6 and the damage from passing through the sheet of frigid air increases by 1d6 for each spell slot level above 6.","upcast":{"dice":"1d6"},"componentsShort":"V, S, M"},{"id":"wall-of-stone","name":"Wall of Stone","level":5,"school":"Evocation","classes":["druid","sorcerer","wizard"],"time":"Action","range":"120 ft","components":"V, S, M (a cube of granite)","duration":"Up to 10 minutes","concentration":true,"text":"A nonmagical wall of solid stone springs into existence at a point you choose within range. The wall is 6 inches thick and is composed of ten 10-ft-by10-ft panels. Each panel must be contiguous with another panel. Alternatively, you can create 10-ftby-20-ft panels that are only 3 inches thick.\nIf the wall cuts through a creature’s space when it appears, the creature is pushed to one side of the wall (you choose which side). If a creature would be surrounded on all sides by the wall (or the wall and another solid surface), that creature can make a Dexterity saving throw. On a success, it can use its Reaction to move up to its Speed so that it is no longer enclosed by the wall.\nThe wall can have any shape you desire, though it can’t occupy the same space as a creature or object.\nThe wall doesn’t need to be vertical or rest on a firm foundation. It must, however, merge with and be solidly supported by existing stone. Thus, you can use this spell to bridge a chasm or create a ramp.\nIf you create a span greater than 20 ft in length, you must halve the size of each panel to create supports. You can crudely shape the wall to create battlements and the like. The wall is an object made of stone that can be damaged and thus breached. Each panel has AC 15 and 30 Hit Points per inch of thickness, and it has Immunity to Poison and Psychic damage. Reducing a panel to 0 Hit Points destroys it and might cause connected panels to collapse at the GM’s discretion.\nIf you maintain your Concentration on this spell for its full duration, the wall becomes permanent and can’t be dispelled. Otherwise, the wall disappears when the spell ends.","concDuration":"10 min","save":"dex","componentsShort":"V, S, M","effect":{"text":"A wall of solid stone"}},{"id":"wall-of-thorns","name":"Wall of Thorns","level":6,"school":"Conjuration","classes":["druid"],"time":"Action","range":"120 ft","components":"V, S, M (a handful of thorns)","duration":"Up to 10 minutes","concentration":true,"text":"You create a wall of tangled brush bristling with needle-sharp thorns. The wall appears within range on a solid surface and lasts for the duration. You choose to make the wall up to 60 ft long, 10 ft high, and 5 ft thick or a circle that has a 20-ft diameter and is up to 20 ft high and 5 ft thick.\nThe wall blocks line of sight.\nWhen the wall appears, each creature in its area makes a Dexterity saving throw, taking 7d8 Piercing damage on a failed save or half as much damage on a successful one.\nA creature can move through the wall, albeit slowly and painfully. For every 1 ft a creature moves through the wall, it must spend 4 ft of movement. Furthermore, the first time a creature enters a space in the wall on a turn or ends its turn there, the creature makes a Dexterity saving throw, taking 7d8 Slashing damage on a failed save or half as much damage on a successful one. A creature makes this save only once per turn.\nUsing a Higher-Level Spell Slot. Both types of damage increase by 1d8 for each spell slot level above 6.","concDuration":"10 min","save":"dex","effect":{"dice":"7d8","type":"piercing"},"higher":"Both types of damage increase by 1d8 for each spell slot level above 6.","upcast":{"dice":"1d8"},"componentsShort":"V, S, M"},{"id":"warding-bond","name":"Warding Bond","level":2,"school":"Abjuration","classes":["cleric","paladin"],"time":"Action","range":"Touch","components":"V, S, M (a pair of platinum rings worth 50+ GP each, which you and the target must wear for the duration)","duration":"1 hour","concentration":false,"text":"You touch another creature that is willing and create a mystic connection between you and the target until the spell ends. While the target is within 60 ft of you, it gains a +1 bonus to AC and saving throws, and it has Resistance to all damage. Also, each time it takes damage, you take the same amount of damage.\nThe spell ends if you drop to 0 Hit Points or if you and the target become separated by more than 60 ft. It also ends if the spell is cast again on either of the connected creatures.","componentsShort":"V, S, M","effect":{"text":"Touch another creature that is willing and create a mystic…"}},{"id":"water-breathing","name":"Water Breathing","level":3,"school":"Transmutation","classes":["druid","ranger","sorcerer","wizard"],"time":"Action","range":"30 ft","components":"V, S, M (a short reed)","duration":"24 hours","concentration":false,"text":"This spell grants up to ten willing creatures of your choice within range the ability to breathe underwater until the spell ends. Affected creatures also retain their normal mode of respiration.","ritual":true,"componentsShort":"V, S, M","effect":{"text":"This spell grants up to ten willing creatures of your choice…"}},{"id":"water-walk","name":"Water Walk","level":3,"school":"Transmutation","classes":["cleric","druid","ranger","sorcerer"],"time":"Action","range":"30 ft","components":"V, S, M (a piece of cork)","duration":"1 hour","concentration":false,"text":"This spell grants the ability to move across any liquid surface—such as water, acid, mud, snow, quicksand, or lava—as if it were harmless solid ground (creatures crossing molten lava can still take damage from the heat). Up to ten willing creatures of your choice within range gain this ability for the duration.\nAn affected target must take a Bonus Action to pass from the liquid’s surface into the liquid itself and vice versa, but if the target falls into the liquid, the target passes through the surface into the liquid below.","ritual":true,"componentsShort":"V, S, M","effect":{"text":"This spell grants the ability to move across any liquid…"}},{"id":"web","name":"Web","level":2,"school":"Conjuration","classes":["sorcerer","wizard"],"time":"Action","range":"60 ft","components":"V, S, M (a bit of spiderweb)","duration":"Up to 1 hour","concentration":true,"text":"You conjure a mass of sticky webbing at a point within range. The webs fill a 20-ft Cube there for the duration. The webs are Difficult Terrain, and the area within them is Lightly Obscured.\nIf the webs aren’t anchored between two solid masses (such as walls or trees) or layered across a floor, wall, or ceiling, the web collapses on itself, and the spell ends at the start of your next turn.\nWebs layered over a flat surface have a depth of 5 ft.\nThe first time a creature enters the webs on a turn or starts its turn there, it must succeed on a Dexterity saving throw or have the Restrained condition while in the webs or until it breaks free. A creature Restrained by the webs can take an action to make a Strength (Athletics) check against your spell save DC. If it succeeds, it is no longer Restrained.\nThe webs are flammable. Any 5-ft Cube of webs exposed to fire burns away in 1 round, dealing 2d4 Fire damage to any creature that starts its turn in the fire.","concDuration":"1 hour","save":"dex","effect":{"dice":"2d4","type":"fire","text":"Restrained in sticky webs"},"componentsShort":"V, S, M"},{"id":"weird","name":"Weird","level":9,"school":"Illusion","classes":["warlock","wizard"],"time":"Action","range":"120 ft","components":"V, S","duration":"Up to 1 minute","concentration":true,"text":"You try to create illusory terrors in others’ minds. Each creature of your choice in a 30-ft-radius Sphere centered on a point within range makes a Wisdom saving throw. On a failed save, a target takes 10d10 Psychic damage and has the Frightened condition for the duration. On a successful save, a target takes half as much damage only.\nA Frightened target makes a Wisdom saving throw at the end of each of its turns. On a failed save, it takes 5d10 Psychic damage. On a successful save, the spell ends on that target.","concDuration":"1 min","save":"wis","effect":{"dice":"10d10","type":"psychic"},"componentsShort":"V, S"},{"id":"wind-walk","name":"Wind Walk","level":6,"school":"Transmutation","classes":["druid"],"time":"1 minute","range":"30 ft","components":"V, S, M (a candle)","duration":"8 hours","concentration":false,"text":"You and up to ten willing creatures of your choice within range assume gaseous forms for the duration, appearing as wisps of cloud. While in this cloud form, a target has a Fly Speed of 300 ft and can hover; it has Immunity to the Prone condition; and it has Resistance to Bludgeoning, Piercing, and Slashing damage. The only actions a target can take in this form are the Dash action or a Magic action to begin reverting to its normal form. Reverting takes 1 minute, during which the target has the Stunned condition. Until the spell ends, the target can revert to cloud form, which also requires a Magic action followed by a 1-minute transformation.\nIf a target is in cloud form and flying when the effect ends, the target descends 60 ft per round for 1 minute until it lands, which it does safely. If it can’t land after 1 minute, it falls the remaining distance.","componentsShort":"V, S, M","effect":{"text":"And up to ten willing creatures of your choice within range…"}},{"id":"wind-wall","name":"Wind Wall","level":3,"school":"Evocation","classes":["druid","ranger"],"time":"Action","range":"120 ft","components":"V, S, M (a fan and a feather)","duration":"Up to 1 minute","concentration":true,"text":"A wall of strong wind rises from the ground at a point you choose within range. You can make the wall up to 50 ft long, 15 ft high, and 1 ft thick. You can shape the wall in any way you choose so long as it makes one continuous path along the ground. The wall lasts for the duration.\nWhen the wall appears, each creature in its area makes a Strength saving throw, taking 4d8 Bludgeoning damage on a failed save or half as much damage on a successful one.\nThe strong wind keeps fog, smoke, and other gases at bay. Small or smaller flying creatures or objects can’t pass through the wall. Loose, lightweight materials brought into the wall fly upward. Arrows, bolts, and other ordinary projectiles launched at targets behind the wall are deflected upward and miss automatically. Boulders hurled by Giants or siege engines, and similar projectiles, are unaffected. Creatures in gaseous form can’t pass through it.","concDuration":"1 min","save":"str","effect":{"dice":"4d8","type":"bludgeoning"},"componentsShort":"V, S, M"},{"id":"wish","name":"Wish","level":9,"school":"Conjuration","classes":["sorcerer","wizard"],"time":"Action","range":"Self","components":"V","duration":"Instantaneous","concentration":false,"text":"Wish is the mightiest spell a mortal can cast. By simply speaking aloud, you can alter reality itself.\nThe basic use of this spell is to duplicate any other spell of level 8 or lower. If you use it this way, you don’t need to meet any requirements to cast that spell, including costly components. The spell simply takes effect.\nAlternatively, you can create one of the following effects of your choice:\nObject Creation. You create one object of up to 25,000 GP in value that isn’t a magic item. The object can be no more than 300 ft in any dimension, and it appears in an unoccupied space that you can see on the ground.\nInstant Health. You allow yourself and up to twenty creatures that you can see to regain all Hit Points, and you end all effects on them listed in the Greater Restoration spell.\nResistance. You grant up to ten creatures that you can see Resistance to one damage type that you choose. This Resistance is permanent.\nSpell Immunity. You grant up to ten creatures you can see immunity to a single spell or other magical effect for 8 hours.\nSudden Learning. You replace one of your feats with another feat for which you are eligible. You lose all the benefits of the old feat and gain the benefits of the new one. You can’t replace a feat that is a prerequisite for any of your other feats or features.\nRoll Redo. You undo a single recent event by forcing a reroll of any die roll made within the last round (including your last turn). Reality reshapes itself to accommodate the new result. For example, a Wish spell could undo an ally’s failed saving throw or a foe’s Critical Hit. You can force the reroll to be made with Advantage or Disadvantage, and you choose whether to use the reroll or the original roll.\nReshape Reality. You may wish for something not included in any of the other effects. To do so, state your wish to the GM as precisely as possible. The GM has great latitude in ruling what occurs in such an instance; the greater the wish, the greater the likelihood that something goes wrong. This spell might simply fail, the effect you desire might be achieved only in part, or you might suffer an unforeseen consequence as a result of how you worded the wish. For example, wishing that a villain were dead might propel you forward in time to a period when that villain is no longer alive, effectively removing you from the game.\nSimilarly, wishing for a Legendary magic item or an Artifact might instantly transport you to the presence of the item’s current owner. If your wish is granted and its effects have consequences for a whole community, region, or world, you are likely to attract powerful foes. If your wish would affect a god, the god’s divine servants might instantly intervene to prevent it or to encourage you to craft the wish in a particular way. If your wish would undo the multiverse itself, your wish fails.\nThe stress of casting Wish to produce any effect other than duplicating another spell weakens you.\nAfter enduring that stress, each time you cast a spell until you finish a Long Rest, you take 1d10 Necrotic damage per level of that spell. This damage can’t be reduced or prevented in any way. In addition, your Strength score becomes 3 for 2d4 days. For each of those days that you spend resting and doing nothing more than light activity, your remaining recovery time decreases by 2 days. Finally, there is a 33 percent chance that you are unable to cast Wish ever again if you suffer this stress.","effect":{"dice":"1d10","type":"necrotic","text":"Duplicate any spell of 8th level or lower, or more"},"componentsShort":"V"},{"id":"word-of-recall","name":"Word of Recall","level":6,"school":"Conjuration","classes":["cleric"],"time":"Action","range":"5 ft","components":"V","duration":"Instantaneous","concentration":false,"text":"You and up to five willing creatures within 5 ft of you instantly teleport to a previously designated sanctuary. You and any creatures that teleport with you appear in the nearest unoccupied space to the spot you designated when you prepared your sanctuary (see below). If you cast this spell without first preparing a sanctuary, the spell has no effect.\nYou must designate a location, such as a temple, as a sanctuary by casting this spell there.","componentsShort":"V","effect":{"text":"And up to five willing creatures within 5 ft of you instantly…"}},{"id":"zone-of-truth","name":"Zone of Truth","level":2,"school":"Enchantment","classes":["bard","cleric","paladin"],"time":"Action","range":"60 ft","components":"V, S","duration":"10 minutes","concentration":false,"text":"You create a magical zone that guards against deception in a 15-ft-radius Sphere centered on a point within range. Until the spell ends, a creature that enters the spell’s area for the first time on a turn or starts its turn there makes a Charisma saving throw. On a failed save, a creature can’t speak a deliberate lie while in the radius. You know whether a creature succeeds or fails on this save.\nAn affected creature is aware of the spell and can avoid answering questions to which it would normally respond with a lie. Such a creature can be evasive yet must be truthful.","save":"cha","componentsShort":"V, S","effect":{"text":"Creatures can’t knowingly lie"}}] });
})();
